window.__Q=window.__Q||{};window.__Q["tcm/2/A2"]=[{"q":"患者，男，45岁。素有肝疾，常有右胁部刺痛感，夜间加重，舌紫边有瘀斑。其脉象可见","o":["代脉","散脉","革脉","牢脉","涩脉"],"a":4,"e":"肝失疏泄，瘀血内停胁络，脉道滞涩不利，故脉见细迟短涩、往来不畅。代脉止有定数主脏气衰微，散脉浮散无根主元气离散，革脉弦急搏指主失血失精，三者皆非瘀血之象。牢脉沉实主阴寒内盛之癥积，与刺痛瘀斑机理不同"},{"q":"患者，男，60岁。患者平素有尿血病史，西医诊断为泌尿系感染，观察其面部淡白，心悸失眠，少气懒言，舌淡白，脉弱。辨证为","o":["气血两虚证","气虚血瘀证","气不摄血证","气随血脱证","气滞血瘀证"],"a":2,"e":"久病尿血耗伤气血，气虚不能统摄血液，血溢脉外则尿血，气血不足则面色淡白、心悸失眠、少气懒言、舌淡脉弱。气血两虚虽有虚象但无出血；气虚血瘀必有刺痛固定；气随血脱见于大出血后气脱，均与本例不符"},{"q":"口气臭秽难闻，牙龈腐烂者，多为","o":["胃热","食积胃肠","龋齿","牙疳","消化不良"],"a":3,"e":"牙疳以牙龈腐烂、口气臭秽难闻为特征，多由胃火炽盛或阴虚火旺上攻牙龈所致。胃热仅见口臭、牙龈肿痛而未腐烂；龋齿为牙齿蛀蚀缺损；食积胃肠口气酸腐伴嗳腐吞酸，皆非牙龈腐烂"},{"q":"患者，男，55岁。高血压病史10年，常感头目眩晕不适，曾服中、西药治疗但无显效，近1个月来症状加重。症见头目眩晕如坐舟船，耳鸣时轻时重，面红目赤，急燥易怒，腰膝酸软，头重脚轻，步履不稳，失眠多梦，舌质红，脉弦细数。其病证机理多属","o":["肝阳上亢","气血两亏","痰湿内阻","肾精亏虚","肝火上炎"],"a":0,"e":"肝肾阴亏于下，肝阳上扰于上，故眩晕如坐舟船、耳鸣、面红目赤，下虚则腰膝酸软、头重脚轻，脉弦细数。肝火上炎为实火，见口苦便秘尿黄而无腰膝酸软；肾精亏虚纯虚无上亢；气血两亏、痰湿内阻均无面红目赤之象"},{"q":"患者精神沮丧，意志消沉，面色惨淡，神疲乏力，宜诊断为","o":["喜伤证","悲伤证","思伤证","惊伤证","恐伤证"],"a":1,"e":"悲伤过度则气消，肺气耗伤，故精神沮丧、意志消沉、面色惨淡、神疲乏力。喜伤证见喜笑不休、心神涣散；思伤证思虑过度、纳呆腹胀；惊伤证惊悸不安；恐伤证恐惧怯懦、二便失司，皆与本例情志消沉不同"},{"q":"患者，男，60岁。面色黄而虚浮，辨证为","o":["气血亏虚","气滞血瘀","脾胃虚寒","肾阳亏虚","脾虚湿蕴"],"a":4,"e":"脾虚失运，水湿内停，泛溢肌肤，故面色黄而虚浮，即黄胖。气血亏虚面色萎黄无华而不虚浮；脾胃虚寒见面色㿠白、腹痛喜温；肾阳亏虚面色黧黑，均非黄而虚浮之象"},{"q":"患者，女，18岁。近半个月因复习考试，每日入睡较晚且夜寐多梦，心烦，口渴，便秘溲黄，舌尖部有烧灼感，可见红刺，苔黄，脉数。其病证机理为","o":["心火亢盛","肝胆火旺","痰火内扰","热陷心包","胃火亢盛"],"a":0,"e":"心火内盛，上炎舌尖，故心烦、舌尖烧灼有红刺；里热伤津则口渴、便秘溲黄、苔黄脉数。肝胆火旺兼口苦胁痛；痰火内扰多见癫狂、喉间痰鸣；热陷心包必有神昏谵语；胃火亢盛以口臭牙龈肿痛为主，均非本例"},{"q":"患者，男，23岁。3天来恶寒发热，鼻塞流浊涕，头痛咽痛，咳嗽，口干，稍有汗出，舌尖红，苔薄黄，脉浮数。属于","o":["风热表证","风热犯肺","痰湿阻肺","痰热壅肺","阴虚肺燥"],"a":0,"e":"风热犯表，卫气失宣，故恶寒发热、头痛咽痛、鼻塞流浊涕；风热上扰则舌尖红、苔薄黄、脉浮数，腠理疏松故稍有汗出。风热犯肺以咳嗽痰黄为主，表证不突出；痰湿阻肺痰多清稀；痰热壅肺痰黄稠；阴虚肺燥无表证"},{"q":"患者自觉胸闷善太息，胁肋胃脘胀满，嗳气，吞酸嘈杂，情志抑郁，舌苔薄白，脉弦略数。宜诊断为","o":["肝气郁结证","胃热证","食滞胃脘证","肝脾不调证","肝胃不和证"],"a":4,"e":"肝失疏泄，横逆犯胃，胃失和降，故胸胁胃脘胀满、嗳气吞酸嘈杂、情志抑郁、脉弦。肝气郁结仅见胁胀太息而无胃脘症状；食滞胃脘见嗳腐吞酸、脘腹胀痛；肝脾不调以腹痛泄泻为主，均可鉴别"},{"q":"患者，女，32岁。3年前于产后出现畏寒肢冷，秋冬尤甚，得温可缓。现症见畏寒肢冷，腰膝酸冷，乏力自汗，食少腹胀，大便溏薄，夜尿频多，舌淡胖有齿痕，苔白滑，脉沉迟无力。其汗出的病机是","o":["血虚","气陷","气脱","津液不足","阳气亏虚"],"a":4,"e":"阳气亏虚，卫外不固，腠理疏松，故自汗出；阳虚温煦失职则畏寒肢冷、腰膝酸冷、夜尿频多、脉沉迟无力。血虚自汗伴面色淡白心悸；气陷以脱肛、久泻为主；气脱大汗淋漓、脉微；津液不足见口干尿少而非自汗"},{"q":"咳嗽阵作，痰黄黏稠，面红目赤，躁热易怒，舌红苔黄，脉数。应诊断为","o":["痰热蕴肺证","肺热炽盛证","肝火犯肺证","肺燥津亏证","风热犯肺证"],"a":2,"e":"肝火上炎，循经犯肺，肺失清肃，故咳嗽阵作、痰黄黏稠；肝火上炎则面红目赤、急躁易怒、脉数。痰热蕴肺以痰黄稠、胸闷为主，无面红目赤急躁；肺热炽盛见高热喘促；风热犯肺有表证；肺燥津亏痰少而干"},{"q":"患者，女，64岁。诉皮肤干燥，口唇干，不渴，平时经常用化妆品敷脸，但是仍然不解，舌红少津，脉细，辨证为","o":["阴虚火旺证","津液亏虚证","血热证","血脱证","血寒证"],"a":1,"e":"津液亏虚不能濡润肌肤口唇，故皮肤干燥、口唇干、舌红少津、脉细；津伤未甚故不渴。阴虚火旺必有五心烦热、潮热盗汗；血热见出血、舌绛；血脱见于大出血后；血寒见手足冷痛、舌淡，均非本例"},{"q":"患者，男，49岁。自诉数日前与人争吵后出现耳鸣，逐渐加重，现听力下降，伴有头痛而胀，烦躁易怒，失眠多梦，大便秘结，小便短黄，舌红苔黄，脉弦数。辨证属","o":["肝阴虚证","肝火炽盛证","肝胆湿热证","肝阳上亢证","寒滞肝脉证"],"a":1,"e":"情志过极化火，肝火循经上扰清窍，故耳鸣、头痛而胀、烦躁易怒；里热结实则便秘尿黄、舌红苔黄、脉弦数。肝阳上亢兼腰膝酸软、头重脚轻；肝胆湿热见口苦、胁痛、苔黄腻；寒滞肝脉见少腹冷痛；肝阴虚为虚热"},{"q":"患者，男，32岁。发热，微恶风寒，少汗，口鼻干燥，咽喉干痛，干咳少痰，舌红，苔薄白而干，脉浮数，其临床意义是","o":["风热犯卫","燥热犯肺","湿热犯卫","热扰胸膈","热邪壅肺"],"a":1,"e":"燥热之邪犯肺，耗伤津液，故口鼻干燥、咽喉干痛、干咳少痰、舌干；卫表失和则发热微恶风寒、脉浮数。风热犯卫以咽痛、流浊涕为主，燥象不显；热邪壅肺高热咳喘痰多；湿热犯卫苔腻；热扰胸膈见心烦懊憹"},{"q":"胸胁胀痛，胸闷喜太息，纳少，腹胀便溏，肠鸣矢气。宜诊断为","o":["肝气郁结证","脾胃气虚证","肝脾不和证","肝胃不和证","肝胆湿热证"],"a":2,"e":"肝失疏泄，横逆乘脾，脾失健运，故胸胁胀痛、太息，兼纳少、腹胀便溏、肠鸣矢气。肝气郁结仅有情志抑郁、胁胀而无脾虚泄泻；肝胃不和以太息、嗳气吞酸、胃脘胀满为主；肝胆湿热见口苦苔黄腻；脾胃气虚无胸胁胀痛"},{"q":"郭某，男，5岁。家长叙述，患儿鼻塞流清涕3天，微有发热，精神尚可，饮食如常，未予重视。今日从幼儿园回家，精神不振，体温升高，口渴喜饮，不欲进食咀嚼，左腮部漫肿压痛。该患儿最应重点询问的内容是","o":["是否受风着凉","是否饮食积滞","预防接种史","传染病接触史","是否受惊吓"],"a":3,"e":"患儿发热、左腮漫肿压痛，提示流行性腮腺炎，属传染病，故重点询问传染病接触史以明确传染源。是否受风着凉、饮食积滞、受惊吓仅为一般诱因；预防接种史虽相关，但当前急在明确是否接触传染源"},{"q":"患者，男，12岁。左侧腮部以耳垂为中心肿起，边缘不清，皮色不红，疼痛，按之有触痛者，最可能的诊断是","o":["抱头火丹","大头瘟","痄腮","发颐","面肿"],"a":2,"e":"痄腮以耳垂为中心肿胀、边缘不清、皮色不红、触痛明显为特征，多发于儿童。抱头火丹色赤灼热、边界清楚；大头瘟头面红肿焮痛；发颐为颧骨处化脓性肿痛，成人多见；面肿无局部触痛"},{"q":"病人发热1天，伴汗出，恶风，脉浮，其证属","o":["太阳中风证","太阳伤寒证","太阳蓄水证","太阳蓄血证","少阳病证"],"a":0,"e":"太阳中风为外感风寒、卫强营弱，腠理疏松故汗出、恶风，脉浮。太阳伤寒无汗而喘、脉浮紧；太阳蓄水见小便不利、渴欲饮水；太阳蓄血见少腹急结、小便自利；少阳病寒热往来、口苦咽干，均不同"},{"q":"患儿，男，9岁。昨晚食冰水后出现腹痛，食少，便溏，泛恶欲吐，小便短少，舌淡胖苔白腻，脉濡缓。诊为","o":["脾阳虚证","寒湿困脾证","肠燥津亏证","寒滞胃脘证","食滞胃脘证"],"a":1,"e":"寒湿内生，困阻脾阳，运化失司，故腹痛、食少、便溏、泛恶欲吐，湿阻则小便短少、舌淡胖苔白腻、脉濡缓。脾阳虚起病缓、病程长，以喜温喜按为主；寒滞胃脘痛连胃脘；食滞胃脘见嗳腐吞酸；肠燥津亏大便干结"},{"q":"患者，男，50岁。心悸反复发作2个月，伴心烦，眠浅多梦，时有盗汗，平素形体较瘦，口燥咽干，自觉午后低热，颧红，舌红少苔，脉细数。此属下列何证","o":["心阴虚证","肝阴虚证","心肾不交证","心血虚证","心火上炎证"],"a":0,"e":"心阴不足，虚火内扰，心神不宁，故心悸、心烦、眠浅多梦；阴虚内热则盗汗、午后低热、颧红、口燥咽干、舌红少苔、脉细数。心血虚无潮热盗汗等热象；肝阴虚以目涩胁痛为主；心肾不交兼腰膝酸软；心火亢盛属实热"},{"q":"患者，男。腹部胀大如鼓，按之如囊裹水者，多为","o":["气臌","实满","水鼓","虚满","虫臌"],"a":2,"e":"水鼓以腹胀大如鼓、按之如囊裹水、动摇有声为特征，因水湿停聚腹中。气臌按之空空然、叩之如鼓，无形质水液；实满、虚满为胀满而非鼓胀；虫臌见腹大青筋、形瘦腹大，由虫积所致"},{"q":"患者神思恍惚，食少纳呆，腹胀脘痞，面色萎黄，失眠消瘦，宜诊断为","o":["喜伤证","忧伤证","思伤证","悲伤证","恐伤证"],"a":2,"e":"思虑过度则气结，损伤心脾，心神失养则神思恍惚、失眠，脾失健运则食少纳呆、腹胀脘痞、面色萎黄消瘦。忧伤证以悲忧、气消为主；悲伤证精神沮丧；喜伤证喜笑不休；恐伤证恐惧、二便失司，均非本例"},{"q":"患者，女，68岁。望诊面色黧黑，肌肤甲错，辨证为","o":["肾虚","水饮","寒盛","气滞","血瘀"],"a":4,"e":"瘀血内停，肌肤失养，故面色黧黑、肌肤甲错，即皮肤干燥粗糙如鳞。肾虚面色黑而晦暗、伴腰膝酸软；水饮面色黑而虚浮、肢体水肿；寒盛面色青白；气滞以胀痛走窜为主，皆无肌肤甲错"},{"q":"干咳痰少，声音嘶哑，颧红潮热，遗精，脉细数，宜诊断为","o":["肺肾阴虚证","肺燥伤津证","阴虚火旺证","肾阴亏虚证","肺阴亏虚证"],"a":0,"e":"肺肾阴虚，虚火上炎，肺失润降则干咳痰少、声音嘶哑；肾阴亏虚、虚火扰动精室则遗精；颧红潮热、脉细数为阴虚内热。肺阴亏虚仅有干咳咽干，无遗精；肾阴亏虚无咳喘；阴虚火旺、肺燥伤津均不兼具肺肾两脏"},{"q":"石某，男，38岁。近3日出现纳呆食少，烦躁，呕恶腹胀，脘痞身重，小便发黄，其舌象可见","o":["舌质淡白，苔润滑","舌质绛红，苔黄燥","舌质红，苔黄腻","舌质黯，苔薄白","舌质淡红，苔白腻"],"a":2,"e":"湿热内蕴中焦，故纳呆、呕恶、腹胀脘痞、身重、小便黄；舌红为热，苔黄腻为湿热之象。舌淡白润滑主虚寒；舌绛红黄燥主热盛伤津；舌黯薄白主血瘀或正常；舌淡红白腻主寒湿，均非湿热"},{"q":"患者近期急躁易怒，胸胁走窜疼痛，甚至刺痛，舌质紫黯，脉弦。属于","o":["气虚血瘀证","气滞血瘀证","气血两虚证","气不摄血证","气随血脱证"],"a":1,"e":"情志不遂，气机郁滞，血行不畅，故胸胁走窜疼痛、继而刺痛固定、舌紫黯、脉弦。气虚血瘀以乏力、刺痛为主，无走窜胀痛；气血两见面色淡白、心悸；气不摄血有出血；气随血脱见于大出血后"},{"q":"患者牙齿松动，牙根宣露，齿龈溃烂萎缩，溃烂边缘微红肿。宜诊断为","o":["胃火亢盛","肾阴亏损","气血不足","心脾积热","肝胆火旺"],"a":1,"e":"肾主骨，齿为骨之余，肾阴亏虚，虚火上炎，故牙齿松动、牙根宣露、齿龈溃烂萎缩、边缘微红肿。胃火亢盛牙龈肿痛出血、口臭；气血不足牙龈淡白萎缩无红肿；心脾积热口舌生疮；肝胆火旺见口苦胁痛"},{"q":"患者，女，35岁。自述秋季面色微白，入冬之后面色渐黑，此现象称为","o":["主色","客色","善色","病色","恶色"],"a":1,"e":"客色指随季节、气候、环境变化而发生的面色改变，属正常生理现象，秋白冬黑即四时相应。主色为个体一生不变的固有面色；善色为病色明润有光泽；病色为疾病面色；恶色为晦暗枯槁，均非随季节变化"},{"q":"患者与人争执后，情绪低落，胸胁胀满疼痛，或走窜疼痛，食少，脉弦，多属","o":["气虚证","气闭证","气逆证","气滞证","气陷证"],"a":3,"e":"情志不遂，气机郁滞不通，故胸胁胀满、走窜疼痛、脉弦；气滞胃纳受影响则食少。气闭证见突然昏厥、口噤；气逆证见咳喘、呕恶、头胀；气陷证见久泻脱肛；气虚证以乏力、气短、自汗为主，无胀痛"},{"q":"患者鼻中出血，点滴而出，色鲜红，量不多。兼见咳嗽痰少，发热口干，舌边红，舌苔薄白而干，脉浮数。多辨证为","o":["肺经风热","胃热炽盛","肝火上逆","肺肾阴虚","脾不统血"],"a":0,"e":"风热犯肺，损伤肺络，血溢脉外则鼻衄点滴而出、色鲜红；肺失宣肃则咳嗽痰少，发热口干、舌边红、脉浮数为风热表象。胃热炽盛鼻衄量多、口臭便秘；肝火上逆见头痛目赤、烦躁；肺肾阴虚为虚热；脾不统血血色淡"},{"q":"患者中府穴有明显压痛，应考虑为","o":["心病","肝病","脾病","肺病","肾病"],"a":3,"e":"中府为肺之募穴，肺脏病变可在募穴处出现压痛，故中府压痛提示肺病。心病的敏感受穴在膻中、巨阙；肝病在期门；脾病在章门；肾病在京门，均非中府"},{"q":"嗳气频作响亮，常因情志变化而增减者，证属","o":["食滞胃脘","寒邪客胃","胃肠实热","肝气犯胃","胃虚气逆"],"a":3,"e":"肝失疏泄，横逆犯胃，胃气上逆则嗳气频作响亮，且随情志波动而增减。食滞胃脘嗳气酸腐、脘腹胀满；寒邪客胃嗳气无酸腐、胃脘冷痛；胃肠实热见口臭、便秘；胃虚气逆嗳气低沉、乏力，均可区分"},{"q":"患者症见突然昏倒，口吐涎沫，四肢抽搐，口中发出猪羊叫声，醒后如常，其诊断是","o":["狂证","癫证","痫证","中暑","中风"],"a":2,"e":"痫证为痰浊内伏、风痰上扰，故突然昏仆、口吐涎沫、四肢抽搐、喉中作猪羊声，醒后如常。狂证躁狂妄动、打骂；癫证表情淡漠、喃喃自语；中风昏仆后遗留歪斜偏瘫；中暑有高温环境史，均不同"},{"q":"患者表情淡漠，面色苍白，冷汗淋漓、汗质稀淡，四肢厥冷，呼吸微弱，舌白脉微。证属","o":["表寒证","里热证","亡阳证","亡阴证","阴阳两虚证"],"a":2,"e":"阳气暴脱，温煦固摄失职，故冷汗淋漓、汗质稀淡、四肢厥冷、呼吸微弱、脉微，面色苍白。亡阴证汗出如油、身热烦渴、脉细数疾；表寒证恶寒发热无汗；里热证发热口渴；阴阳两虚见虚寒虚热并见，非暴脱"},{"q":"患者干咳无痰，咳声清脆，咽干，舌淡红，脉浮者，多属","o":["寒饮内停","燥热伤肺","肺气不宣","肾水不足","痰浊蕴肺"],"a":1,"e":"燥热伤肺，津液受损，肺气上逆则干咳无痰、咳声清脆、咽干；燥邪在表故脉浮。寒饮内停痰多清稀；肺气不宣咳嗽伴鼻塞气促；肾水不足见腰膝酸软、潮热；痰浊蕴肺痰多黏稠，均非干咳"},{"q":"患者近日因外感出现咳嗽痰黄稠，鼻塞流浊涕，咽痛，发热微恶寒，口干微渴，舌尖红，苔薄黄，考虑最可能的脉象是","o":["浮紧脉","浮缓脉","浮滑脉","浮数脉","沉紧脉"],"a":3,"e":"风热外袭，卫表失和则发热微恶寒，热邪灼津则痰黄稠、咽痛、苔薄黄、舌尖红，浮脉主表、数脉主热，故见浮数脉。浮紧脉主风寒表证；浮缓脉主太阳中风；浮滑脉主风痰；沉紧脉主里寒，均非风热表证"},{"q":"患者，女，45岁。久病面色苍白，却时而泛红如妆、游移不定，辨证为","o":["心火上炎","阳明热盛","肝胆湿热","虚阳外越","阴虚火旺"],"a":3,"e":"久病阳气虚衰，虚阳浮越于上，故面色苍白却时泛红如妆、游移不定，为戴阳证。心火上炎见面红目赤、口舌生疮；阳明热盛满面通红、大汗大渴；肝胆湿热见面目发黄、口苦；阴虚火旺见颧红潮热盗汗，均不同"},{"q":"患者多年来小便清长，淋漓不尽，肢冷蜷卧，近日突见小便闭塞不通，腹胀痛，急躁不安，证属","o":["虚实夹杂","虚证转实","实证转虚","寒证化热","寒热错杂"],"a":1,"e":"久病阳虚、小便清长淋漓本属虚证，今突然小便闭塞、腹胀痛、急躁不安，为虚证基础上转生实证，即虚证转实。虚实夹杂为虚实同时并见；实证转虚是先实后虚；寒证化热、寒热错杂均无本例如此转变"},{"q":"患者，男，35岁。时有突然昏蒙，甚则昏仆反复发作已历2年。近2年来常无明显诱因突然一过性昏蒙，随即清醒；重则昏倒仆地，人事不省，口吐涎沫，喉有痰鸣，持续数十秒才能逐渐清醒。平素面色晦暗，胸闷，呕恶，舌苔白腻，脉滑。此属下列哪个证候","o":["肝阳化风证","痰火扰神证","心火亢盛证","胆郁痰扰证","痰蒙心神证"],"a":4,"e":"痰浊内蕴，蒙蔽心神，故反复一过性昏蒙、甚则昏仆、喉有痰鸣、口吐涎沫，兼面色晦暗、胸闷呕恶、苔白腻、脉滑。痰火扰神见神昏谵语、躁动、苔黄腻；肝阳化风见眩晕震颤；胆郁痰扰见惊悸失眠；心火亢盛神昏谵语"},{"q":"患者，男，45岁。失眠反复发作2个月，自觉眠浅多梦，夜间盗汗，伴心烦心悸。平素形体较瘦，口干饮水较多，大便干结，小便黄，舌尖红绛少苔，脉细数。此属下列何种证候","o":["心阴虚证","心火上炎证","心血虚证","心肾不交证","肝阴虚证"],"a":0,"e":"心阴亏虚，虚火内扰心神，故眠浅多梦、心烦心悸；阴虚内热则盗汗、口干便干尿黄、舌尖红绛少苔、脉细数。心血虚无潮热盗汗、舌淡；心火上炎属实热、口舌生疮；心肾不交兼腰膝酸软遗精；肝阴虚以目涩胁痛为主"},{"q":"患者头痛，眩晕，自觉气从少腹上冲于胸咽，随即咯血，苔白，脉弦。为","o":["气滞证","气逆证","气闭证","气脱证","血瘀证"],"a":1,"e":"气机升降失常，气逆于上，肝气上冲则头痛眩晕、自觉气从少腹上冲胸咽，气逆血随上溢则咯血，脉弦。气滞以胀痛走窜为主；气闭见昏厥；气脱见大汗脉微；血瘀刺痛固定，均无上冲之象"},{"q":"患者，男，40岁。自述右胁胀痛1个月，腹胀，厌食油腻，舌红苔黄腻，其胁痛的病机是","o":["肝脾不调","肝胆湿热","肝郁气滞","肝经瘀血","肝胃不和"],"a":1,"e":"湿热蕴结肝胆，胆汁疏泄失常，故右胁胀痛、厌食油腻；湿热中阻则腹胀、舌红苔黄腻。肝脾不调以胁胀、腹痛泄泻为主；肝郁气滞胀痛走窜、苔薄白；肝经瘀血刺痛固定、舌紫黯；肝胃不和见嗳气吞酸"},{"q":"患者，女，20岁。近1个月来神情抑郁，淡漠痴呆，有时喃喃独语，见人则止，舌苔白腻，脉滑。此属下列何证","o":["痰蒙心神证","心气虚证","痰火扰心证","瘀阻脑络证","胆郁痰扰证"],"a":0,"e":"痰浊蒙蔽心神，故神情抑郁、淡漠痴呆、喃喃独语、见人则止，苔白腻、脉滑为痰浊之象。痰火扰心见狂躁谵语、苔黄腻；心气虚见心悸气短、神疲；瘀阻脑络刺痛固定、舌紫；胆郁痰扰见惊悸失眠、口苦"},{"q":"患者下肢肿胀，皮肤粗厚如象皮，多为感染","o":["蛔虫","绦虫","钩虫","血吸虫","丝虫"],"a":4,"e":"丝虫病晚期因淋巴回流受阻，下肢及阴囊皮肤粗厚、肿胀如象皮，称象皮肿。蛔虫多见腹痛、疳积；绦虫见腹胀、便中节片；钩虫致贫血、异食癖；血吸虫致腹水、肝脾肿大，均无象皮肿"},{"q":"患者，男，60岁。心悸胸闷反复发作半年。平素自觉气短难续，倦怠肢沉，容易疲惫，活动后更加明显。刻下：面色淡白，舌质淡，脉虚。此属下列何证","o":["心阳虚证","心气虚证","心肾不交证","心血虚证","心脾气虚两虚证"],"a":1,"e":"心气不足，鼓动无力，故心悸胸闷、气短难续、神疲乏力，活动后耗气故加重，面色淡白、舌淡、脉虚为气虚之象。心阳虚兼畏寒肢冷、舌胖；心血虚见失眠健忘、面色无华；心肾不交见失眠腰酸；心脾气虚兼食少便溏"},{"q":"患者，女，26岁，已婚。胃脘隐痛，饥不欲食，口燥咽干，大便干结，舌红少津，脉细数。其病机是","o":["脾阴不足","胃阴不足","胃燥津亏","胃热炽盛","肝胃不和"],"a":1,"e":"胃阴亏虚，胃失濡养，故胃脘隐痛、饥不欲食；津液不足则口燥咽干、大便干结、舌红少津、脉细数。脾阴不足兼腹胀便溏；胃燥津亏侧重口干、大便干；胃热炽盛见口臭、牙龈肿痛；肝胃不和见胁胀、嗳气"},{"q":"患者，男，68岁。半小时前突然昏仆，不省人事，口吐涎沫，喉有痰声，并见面色晦暗，胸闷欲呕，舌苔白腻，脉滑。此属下列何证","o":["心阳虚证","痰火扰心证","瘀阻脑络证","胆郁痰扰证","痰蒙心神证"],"a":4,"e":"痰浊上蒙清窍，心神失守，故突然昏仆、不省人事、口吐涎沫、喉有痰声，兼面色晦暗、胸闷欲呕、苔白腻、脉滑。痰火扰心见面红气粗、躁动、苔黄腻；瘀阻脑络昏迷伴刺痛、舌紫；心阳虚见畏寒、脉微；胆郁痰扰无昏仆"},{"q":"患者，女，50岁。经常头晕心悸，失眠健忘，面色淡白，气短懒言，舌淡脉细，其头晕的病机是","o":["痰湿内阻","阳气不足","阳气暴脱","肾精亏虚","气血亏虚"],"a":4,"e":"气血亏虚，清窍失养，故头晕；心失所养则心悸失眠健忘，气血不足则面色淡白、气短懒言、舌淡脉细。痰湿内阻头晕伴头重、苔腻；阳气不足头晕伴畏寒；阳气暴脱见晕厥、脉微；肾精亏虚头晕伴耳鸣、腰膝酸软"},{"q":"患者，男，34岁。素嗜辛辣香燥之品，半年来时有胃脘隐隐疼痛，干呕呃逆，饥不欲食，口燥咽干，伴见形体消瘦，大便干结，舌红少津，脉细而数。其病证机理为","o":["胃火炽盛","脾胃气虚","胃阴不足","胃强脾弱","食积化热"],"a":2,"e":"辛辣香燥日久耗伤胃阴，胃失濡降，故胃脘隐痛、干呕呃逆、饥不欲食；津亏则口燥咽干、形瘦便干、舌红少津、脉细数。胃火炽盛见口臭、牙龈肿痛；脾胃气虚见食少乏力、便溏；胃强脾弱能食而便溏；食积化热见嗳腐酸腐"},{"q":"咳喘，心悸，咯痰清稀，声低气喘，面白神疲，舌淡紫，宜诊断为","o":["心肺气虚证","饮停胸胁证","肺气虚证","心脉瘀阻证","寒痰阻肺证"],"a":0,"e":"心肺气虚，肺失宣降则咳喘、咯痰清稀、声低气短，心气不足则心悸、面白神疲，气虚血行不畅则舌淡紫。饮停胸胁见胸胁胀满、咳唾引痛；肺气虚仅有咳喘无心悸；心脉瘀阻刺痛固定；寒痰阻肺痰多清稀、形寒"},{"q":"患者，女。经期出现腹痛，痛处拒按，固定不移，月经色紫黯，有血块，舌紫黯有瘀斑，最可能的脉象是","o":["弦滑脉","滑数脉","沉迟脉","细涩脉","沉实脉"],"a":3,"e":"瘀血内停胞宫，气血运行不畅，故经期腹痛拒按、固定不移、经色紫黯有块，脉细涩为血少、血行不畅之象。弦滑脉主痰饮或肝郁；滑数脉主湿热痰火；沉迟脉主寒证；沉实脉主里实，均非瘀血"},{"q":"疔的诊断要点，应除外下列哪一项","o":["形如粟如米","根脚坚硬较深","顶白而痛","易化脓，脓溃易愈","麻木或发痒"],"a":3,"e":"疔疮初起形如粟米、根脚坚硬较深、顶白而痛，伴麻木或发痒，因根深毒重，难化脓、溃后难愈，故易化脓、脓溃易愈不是疔的特点。其余各项均为疔的典型表现"},{"q":"患者素体痰盛，近来又感受外邪者，其最可能的脉象为","o":["滑数脉","浮滑脉","浮数脉","浮紧脉","浮缓脉"],"a":1,"e":"素体痰盛，痰浊内蕴则脉滑；新感外邪，邪在表则脉浮，故见浮滑脉，主外感风痰。滑数脉主痰热或湿热；浮数脉主风热表证；浮紧脉主风寒表证；浮缓脉主太阳中风，均不兼痰盛"},{"q":"患者鼻中出血，量多，血色鲜红，鼻干，口干口臭，烦渴引饮，大便干燥，小便短赤，舌红，苔黄厚干，脉洪大而数。最宜辨证为","o":["肺经风热","胃热炽盛","肝火上逆","肺肾阴虚","脾不统血"],"a":1,"e":"胃火炽盛，循经上炎，灼伤鼻络则鼻衄量多、血色鲜红；里热炽盛则口干口臭、烦渴引饮、便秘尿赤、舌红苔黄厚干、脉洪大。肺经风热鼻衄量少、伴咳嗽；肝火上逆见头痛目赤；肺肾阴虚为虚热；脾不统血血色淡"},{"q":"患者神疲乏力，少气懒言，头昏眼花，常自汗出，面白舌淡，证属","o":["痰湿内阻证","肾精不足证","气虚证","气陷证","肝郁脾虚证"],"a":2,"e":"气虚则脏腑功能减退，故神疲乏力、少气懒言、头昏眼花；气虚卫外不固则自汗，面色淡白、舌淡为气血不足之象。痰湿内阻伴头重苔腻；肾精不足伴耳鸣腰酸；气陷证见脱肛、久泻；肝郁脾虚见胁胀、泄泻"},{"q":"患者自觉烦热，颧赤如妆，口干但不多饮，欲加衣被，小便清长，脉沉迟无力，证属","o":["表里实寒证","表寒里热证","表热里寒证","真寒假热证","真热假寒证"],"a":3,"e":"内有真寒、外现假热，阴寒内盛格阳于外，故烦热、颧赤如妆但口干不多饮、欲加衣被，小便清长、脉沉迟无力为里真寒。真热假寒见身热、口渴喜冷、脉滑数；表热里寒、表寒里热、表里实寒均无此格阳假热"},{"q":"患者发热，其额上热甚于手心，多为","o":["表热","里热","实热","虚热","郁热"],"a":0,"e":"额上属表，手心属里，额上热甚于手心为表热，多见于外感发热初起，邪在卫表。里热、实热多手心热甚于额上或手足心热；虚热以五心烦热、午后潮热为主；郁热见身热不扬、手足不温，均非额上独热"},{"q":"陈某，女，62岁。平素嗜食肥甘酒酿，反复脘腹痞闷3个月余，伴纳呆呕恶，便溏尿黄，肢体困重，舌红苔黄腻，脉濡数。诊为","o":["食滞胃脘证","寒滞胃脘证","肠燥津亏证","热盛伤津证","湿热蕴脾证"],"a":4,"e":"嗜食肥甘酒酿，湿热内生，困阻脾胃，故脘腹痞闷、纳呆呕恶、肢体困重、便溏尿黄，舌红苔黄腻、脉濡数为湿热之象。食滞胃脘见嗳腐吞酸；寒滞胃脘见冷痛喜温；肠燥津亏大便干结；热盛伤津见大渴、苔燥"},{"q":"患者皮肤发赤，伴有口干，面红，小便短黄，舌红，苔黄，脉数，其病机不可能是","o":["寒湿困脾","心火偏旺，风热乘袭","肾火内蕴，湿热下注","热毒内结","丹毒流火"],"a":0,"e":"本例皮肤发赤、口干面红、尿黄、舌红苔黄、脉数，均属热象，可由心火、风热、湿热、热毒或丹毒所致；寒湿困脾属寒湿，见面色晦暗、脘痞便溏、舌淡苔白腻、脉濡缓，不能出现上述热象"},{"q":"病人小腹急结，小便自利，身体发黄，脉沉结，其证属","o":["太阳中风证","太阳伤寒证","太阳蓄水证","太阳蓄血证","少阳病证"],"a":3,"e":"太阳病邪热内传下焦，与血相结，故小腹急结；病在血分、不在气分，故小便自利；血瘀发黄、脉沉结为蓄血之象。太阳蓄水证小便不利；太阳中风汗出恶风；太阳伤寒无汗而喘；少阳病寒热往来，均不同"},{"q":"患者久病，颈项软弱，头垂不抬，眼窝深陷，多属","o":["心血瘀阻","热极生风","精气衰竭","风寒侵袭","水气凌心"],"a":2,"e":"久病精气衰竭，元气大伤，筋骨肌肉失养，故颈项软弱、头垂不抬、眼窝深陷，为病危之象。心血瘀阻见胸痛、舌紫；热极生风见抽搐、角弓反张；风寒侵袭见项强恶寒；水气凌心见心悸、水肿，均非衰竭"},{"q":"患者，男，47岁，农民。自述5年前因过食生冷而腹痛，温熨热敷可缓解，未系统治疗。1周前不慎着凉腹痛加重。现症见腹痛，喜温喜按，腹胀纳少，食后胀甚，大便溏薄，四肢不温，舌淡胖苔白，脉沉迟无力。其腹痛的病机是","o":["脾胃气虚","脾胃虚寒","寒湿困脾","气滞湿阻","肝郁脾虚"],"a":1,"e":"脾胃阳气亏虚，寒从中生，故腹痛喜温喜按、四肢不温、大便溏薄，舌淡胖苔白、脉沉迟无力。脾胃气虚仅有乏力、食少、便溏，无寒冷象；寒湿困脾苔白腻、身重；气滞湿阻胀痛走窜；肝郁脾虚见胁胀、情志相关"},{"q":"皮肤、面目、爪甲发黄，黄色鲜明如橘子色，伴有汗、尿色深黄，口渴，舌苔黄腻者，主要病机是","o":["外感风热","脾胃或肝胆湿热","寒湿所困","下焦湿热","水湿浸淫"],"a":1,"e":"湿热蕴结脾胃或肝胆，胆汁外溢肌肤，故身目爪甲发黄、色泽鲜明如橘，汗尿深黄、口渴、苔黄腻为湿热之象。寒湿所困黄色晦暗如烟熏；外感风热、下焦湿热、水湿浸淫均无此鲜明黄疸"},{"q":"头晕心悸，目眩，视物模糊，失眠，月经量少、色淡，面白，舌淡脉细。宜诊断为","o":["心脾两虚证","心肝血虚证","肝血虚证","气血两虚证","肝阳上亢证"],"a":1,"e":"心肝血虚，心失所养则心悸失眠，肝血不足、目失所养则目眩视物模糊、头晕，血虚冲任不足则月经量少色淡，面白舌淡脉细为血虚之象。心脾两虚兼食少腹胀便溏；肝血虚无心悸；气血两虚兼气短乏力；肝阳上亢见头胀、脉弦"},{"q":"神识清楚而言语时有错乱，语后自知言错，称为","o":["独语","错语","谵语","郑声","狂言"],"a":1,"e":"错语指神识清楚而语言时有错乱、说后自知言错，多因心气不足、神无所养。独语为喃喃自语、见人则止；谵语为神昏胡言、声高有力；郑声为神识不清、语言重复、声低；狂言为躁妄叫骂，均与本例不同"},{"q":"患者发热恶热，面红目赤，渴喜冷饮，尿短便秘，舌红苔黄燥，脉洪数有力，宜诊断为","o":["风淫证","暑淫证","燥淫证","火淫证","湿淫证"],"a":3,"e":"火邪亢盛，燔灼内外，故发热恶热、面红目赤、渴喜冷饮，津伤则尿短便秘、舌红苔黄燥，脉洪数有力为里热实证。风淫证以恶风、汗出、脉浮为主；暑淫证见身热汗多、乏力气短；燥淫证干咳少痰；湿淫证苔腻、身重"},{"q":"患者耳内流脓，脓液清稀而量多，或牵丝如胶，多为","o":["肝胆火热上蒸","脾虚有湿","肾虚","湿热熏蒸","肝经火旺"],"a":1,"e":"脾虚运化失司，湿浊内生，上犯清窍，故耳内流脓清稀量多、或牵丝如胶，病程迁延。肝胆火热上蒸脓液黄稠、量多臭秽；湿热熏蒸脓稠黄；肾虚耳流清稀伴耳鸣、腰酸，但无牵丝如胶之湿象；肝经火旺见口苦、胁痛"},{"q":"患者恶风发热，汗出，鼻塞流涕，喷嚏，咽痒咳嗽，舌淡苔薄白，脉浮，宜诊断为","o":["风淫证","寒淫证","暑淫证","燥淫证","火淫证"],"a":0,"e":"风邪袭表，卫气失固，故恶风发热、汗出、脉浮；风邪上犯肺窍则鼻塞流涕、喷嚏、咽痒咳嗽，舌淡苔薄白为风邪在表。寒淫证恶寒重、无汗；暑淫证汗多、口渴、身倦；燥淫证干咳少痰、口鼻干；火淫证高热、口渴、苔黄"},{"q":"患者，女，48岁。主诉眩晕，两目干涩，胁肋隐痛，伴有咽干口燥，五心烦热，潮热盗汗，舌红少苔，脉弦细数。辨证属","o":["肝阴虚证","肝火炽盛证","肝血虚证","肝风内动证","寒滞肝脉证"],"a":0,"e":"肝阴亏虚，目失所养则两目干涩、眩晕；肝络失养则胁肋隐痛；阴虚内热则咽干口燥、五心烦热、潮热盗汗、舌红少苔、脉弦细数。肝火炽盛为实热、口苦便秘；肝血虚无潮热；肝风内动见震颤抽搐；寒滞肝脉见冷痛"},{"q":"不属于疮疡一类外科疾患的是","o":["痈","疽","疔","疖","疹"],"a":4,"e":"疮疡指痈、疽、疔、疖等发生于体表的化脓性外科疾患，多由火热毒邪壅聚、气血凝滞所致。疹为皮肤斑疹、瘾疹之类，多属皮肤病或外感发斑，不属疮疡范畴"},{"q":"患者，女，22岁。发热，微恶风寒，咳嗽，头痛，口渴，鼻塞，舌边尖红，脉浮数，其临床意义是","o":["邪热壅肺证","湿热阻肺证","邪犯肺卫证","邪陷心包证","湿蒙心包证"],"a":2,"e":"外感温邪犯肺卫，卫气失宣则发热、微恶风寒、头痛、鼻塞；肺失宣肃则咳嗽，舌边尖红、脉浮数为风热犯卫之象。邪热壅肺见高热、咳喘、痰黄；湿热阻肺见胸闷、苔腻；邪陷心包、湿蒙心包均有神昏谵语"},{"q":"患者胸闷，心悸怔忡，健忘，面色淡黄无华，舌淡，脉细无力，诊断为","o":["血虚证","气虚证","血瘀证","阴虚证","气陷证"],"a":0,"e":"血虚不能濡养心神，故心悸怔忡、健忘、胸闷；血虚不能上荣则面色淡黄无华，舌淡、脉细无力为血虚之象。气虚证以气短乏力、自汗为主；血瘀证刺痛固定、舌紫；阴虚证见潮热、舌红少苔；气陷证见脱肛、久泻"},{"q":"患者反复口舌生疮，此起彼伏，缠绵难愈，伴口干咽燥，腰膝酸软，舌红，少苔，脉细数。此病最宜诊断为","o":["心脾积热","阴虚火旺","气血不足","湿热秽浊上蒸","肺胃热盛"],"a":1,"e":"阴虚火旺，虚火上炎口腔，故口舌生疮反复发作、缠绵难愈；肾阴亏虚则腰膝酸软，口干咽燥、舌红少苔、脉细数为阴虚内热。心脾积热疮疡肿痛明显、口臭便秘，属实热；肺胃热盛见口臭、牙龈肿痛；气血不足疮面淡白"},{"q":"患者脘腹绞痛剧烈，时作时止，继而波及右上腹部，面目身俱黄，呕吐黄绿色苦水，多考虑","o":["肠道蛔虫病","胆道蛔虫病","蛔厥证","钩虫病","蛲虫病"],"a":1,"e":"蛔虫钻入胆道，胆道痉挛则脘腹绞痛、阵发性加剧、波及右上腹；胆汁淤滞、逆流则呕吐黄绿色苦水、面目身黄。肠道蛔虫病以脐周腹痛为主；蛔厥证为蛔虫所致四肢厥冷、腹痛；钩虫、蛲虫均无胆绞痛与黄疸"},{"q":"患者，女，68岁。患冠状动脉粥样硬化性心脏病10年余。今突然心痛剧作，面色青灰，冷汗淋漓，四肢厥冷，呼吸微弱，舌淡苔白润，脉微欲绝。其证候是","o":["心脉痹阻证","心阳暴脱证","心阳虚证","亡阴证","亡阳证"],"a":1,"e":"心阳暴脱，阳气骤亡，温煦固摄失职，故突然心痛剧作、面色青灰、冷汗淋漓、四肢厥冷、呼吸微弱、脉微欲绝。心阳虚为渐见畏寒、胸闷、脉弱；心脉痹阻见胸闷刺痛但无亡阳；亡阴证汗热、身热；亡阳证无心中痛剧之定位"},{"q":"患者，女，33岁。面目肌肤发黄10天，色泽鲜明，皮肤瘙痒，脘腹胀闷，纳呆呕恶，便溏尿黄，舌红苔黄腻，脉濡数。诊为","o":["湿热蕴脾证","肝胆湿热证","大肠湿热证","寒湿困脾证","胃热炽盛证"],"a":0,"e":"湿热蕴结脾胃，胆汁外溢则面目肌肤发黄、色泽鲜明、皮肤瘙痒；脾失健运则脘腹胀闷、纳呆呕恶、便溏尿黄，舌红苔黄腻、脉濡数为湿热。肝胆湿热以胁痛、口苦为主；大肠湿热见痢疾、便脓血；寒湿困脾黄色晦暗；胃热炽盛见口臭、牙龈肿痛"},{"q":"患者口内唇边，舌面部位生数个黄豆大小黄白色溃烂点，周围黏膜鲜红，微肿，有灼痛感，说话进食困难，兼见发热，口渴，口臭，大便秘结，舌红苔黄，脉数。上述症状宜诊断为","o":["湿热秽浊上蒸","痰湿凝聚","阴虚火旺","肺胃热盛","心脾积热"],"a":4,"e":"心脾积热，循经上炎口腔，故口舌生疮、溃烂点周围鲜红肿痛；里热结实则发热、口渴、口臭、便秘、舌红苔黄、脉数。肺胃热盛见口臭、牙龈肿痛；阴虚火旺疮面淡红、缠绵、舌红少苔；湿热秽浊上蒸、痰湿凝聚均无此实热"},{"q":"“白㾦”产生的主要病机是","o":["湿邪中阻","湿郁肺卫","上焦湿热","湿热内郁，汗出不彻","肝胆湿热"],"a":3,"e":"白㾦为湿热之邪郁于肌肤，汗出不彻，湿郁热蒸，故皮肤出现白色小疱疹，晶莹如粟。湿邪中阻、湿郁肺卫、上焦湿热、肝胆湿热虽均有湿，但均非白㾦形成的关键，关键在于湿热内郁、汗出不畅"},{"q":"嗳气频作连续，无酸腐气味，兼见脘腹冷痛者，属于","o":["寒邪客胃","湿困脾胃","胃虚气逆","食积内停","肝气犯胃"],"a":0,"e":"寒邪客胃，胃气上逆则嗳气频作连续、无酸腐气味；寒凝气滞则脘腹冷痛、喜温。胃虚气逆嗳气低沉、乏力；食积内停嗳气酸腐、脘腹胀满；肝气犯胃嗳气随情志增减、伴胁胀；湿困脾胃见身重、苔腻"},{"q":"腹痛腹泻，泻后痛减，胁胀，食少乏力，苔白脉弦，宜诊断为","o":["食滞胃肠证","胃肠气滞证","寒湿困脾证","脾胃阳虚证","肝郁脾虚证"],"a":4,"e":"肝失疏泄，横逆乘脾，脾失健运，故腹痛腹泻、泻后痛减、食少乏力，肝郁则胁胀、脉弦。食滞胃肠泻后痛减但伴嗳腐酸腐；胃肠气滞以胀痛为主；寒湿困脾见便溏、苔白腻、无泻后痛减；脾胃阳虚见腹中冷痛、喜温喜按"},{"q":"患者，男，2岁。头颅狭小，颅缝迟闭，智力低下。最可能的原因是什么","o":["火邪上攻","吐泻伤津","气血不足","肾精不足","痰饮内停"],"a":3,"e":"肾主骨生髓，脑为髓海，肾精不足则骨骼、智力发育迟缓，故头颅狭小、颅缝迟闭、智力低下。火邪上攻多见头痛、目赤；吐泻伤津致囟门凹陷；气血不足致面色淡白、发育迟缓但颅缝多正常；痰饮内停无此特征"},{"q":"病人恶寒身蜷而下利，手足逆冷，其证属","o":["太阴病证","厥阴病证","阳明病证","少阳病证","少阴病证"],"a":4,"e":"少阴病为心肾阳虚、阴寒内盛，阳气衰微不能温煦四末则恶寒身蜷、手足逆冷，阳虚寒盛则下利清谷。太阴病以腹满而吐、食不下、自利为主；厥阴病寒热错杂、消渴、吐蛔；阳明病身热、汗出、便秘；少阳病寒热往来"},{"q":"患者，女，60岁。有哮喘病史15年，近日因感冒而复发。咳喘无力，咯痰清稀，少气懒言，神疲乏力，动则尤甚，舌淡苔白，脉弱。其辨证为","o":["肺气虚证","风寒犯肺证","风寒表证","脾气虚证","肺肾气虚证"],"a":0,"e":"肺气亏虚，宣降无力，故咳喘无力、咯痰清稀、少气懒言、神疲乏力，活动后耗气故动则尤甚，舌淡苔白、脉弱为气虚。风寒犯肺见恶寒、痰白、脉浮紧；风寒表证以表证为主；脾气虚见食少便溏；肺肾气虚兼腰膝酸软、呼多吸少"},{"q":"患者，女，44岁。因外伤而出现面色苍白，大汗淋漓，手足厥冷，脉微。故辨证为","o":["气血亏虚证","气滞血瘀证","气不摄血证","气随血脱证","血随气脱证"],"a":3,"e":"外伤大出血，血脱则气无所附，随血外脱，故面色苍白、大汗淋漓、手足厥冷、脉微，为气随血脱。气血亏虚起病缓、无大汗淋漓；气滞血瘀刺痛固定；气不摄血有出血但无气脱；血随气脱非本例病机"},{"q":"患者，男，56岁。主诉头痛而晕，伴有烦躁易怒，失眠，耳鸣如潮，面红口干，大便秘结，小便短黄，舌红苔黄，脉弦数。辨证属","o":["肝阴虚证","肝火炽盛证","肝胆湿热证","肝阳上亢证","寒滞肝脉证"],"a":1,"e":"肝火炽盛，循经上扰清窍，故头痛而晕、耳鸣如潮、面红口干；火热扰心则烦躁易怒、失眠，里热结实则便秘尿黄，舌红苔黄、脉弦数。肝阳上亢兼腰膝酸软、头重脚轻；肝胆湿热见口苦、苔黄腻；肝阴虚为虚热；寒滞肝脉见冷痛"},{"q":"患者头项强痛、恶寒发热，四肢关节微痛，口渴，下利黄色粪水，肛门灼热，其证属","o":["少阴兼阳明病证","少阳兼太阳病证","太阳兼阳明病证","太阳病证","阳明病证"],"a":2,"e":"头项强痛、恶寒发热、四肢关节痛为太阳表证；口渴、下利黄色粪水、肛门灼热为阳明里热，表里同病故为太阳兼阳明。少阳兼太阳见寒热往来、口苦；少阴兼阳明见脉微细、但欲寐；单纯太阳病无里热下利；阳明病但热不寒、无表证"},{"q":"患者反复咽中不适，微痛，有干痒灼热感，异物感，常伴咽痒咳嗽，易受刺激而引起恶心干呕，腰酸，舌红少津，脉细数。检查，咽部微红，肿痛不显，有散在颗粒。上述症状宜诊断为","o":["肺胃热盛","痰湿凝聚","肺肾阴虚","风热袭肺","心脾热盛"],"a":2,"e":"肺肾阴虚，虚火上炎，咽喉失养，故咽中不适、微痛干痒灼热、异物感、咽痒咳嗽、恶心干呕；肾虚则腰酸，舌红少津、脉细数为阴虚内热。肺胃热盛咽痛红肿明显、口臭；风热袭肺起病急、咽痛；痰湿凝聚咽中痰梗、苔腻；心脾热盛口舌生疮"},{"q":"患者因胸胁刺痛数月就诊，症见面色晦滞，神疲乏力，少气懒言，胸胁疼痛固定，可触及肿块，质硬，舌淡紫，有瘀斑，最有可能的脉象是","o":["沉迟无力","弦数有力","细涩无力","脉弱","脉细数"],"a":2,"e":"胸胁刺痛固定、肿块质硬、舌淡紫瘀斑为瘀血内停，脉应细涩；兼神疲乏力、少气懒言、面色晦滞为气虚，故见细涩无力，属气虚血瘀。沉迟无力主阳虚寒盛；弦数有力主肝火；脉弱主气虚；脉细数主阴虚，均不兼瘀"},{"q":"患者，男，45岁。体胖，平素喜食油腻，5日前出现咳嗽，痰黄稠量多，发热，口渴喜冷饮，小便短赤，大便秘结，舌红苔黄腻，脉滑数。辨证为","o":["痰热壅肺证","风热犯肺证","肺热炽盛证","肝火犯肺证","湿热蕴脾证"],"a":0,"e":"痰热互结壅滞于肺，肺失宣降，故咳嗽、痰黄稠量多；里热炽盛则发热、口渴喜冷、尿赤便秘，舌红苔黄腻、脉滑数为痰热。风热犯肺痰少、表证明显；肺热炽盛见高热喘促、痰少；肝火犯肺见胁痛、急躁；湿热蕴脾以脘痞、便溏为主"},{"q":"患者3天前受凉，恶寒发热，现症见体温38、5℃，时冷时热，心烦喜呕，舌红，属于","o":["表热里寒证","表寒里热证","表里俱热证","表里俱寒证","半表半里证"],"a":4,"e":"寒热往来、时冷时热、心烦喜呕为少阳枢机不利、邪居半表半里之特征，舌红为有热。表热里寒、表寒里热、表里俱热、表里俱寒均为表里同病，寒热并见而无往来交替、口苦喜呕之半表半里特点"},{"q":"病人恶寒发热1天，脉浮紧，无汗而喘，舌苔薄白，其证属","o":["太阳中风证","太阳伤寒证","太阳蓄水证","太阳蓄血证","少阳病证"],"a":1,"e":"太阳伤寒为风寒袭表、卫阳被遏、营阴郁滞，故恶寒发热、无汗而喘、脉浮紧、苔薄白。太阳中风汗出、脉浮缓；太阳蓄水见小便不利；太阳蓄血见少腹急结、小便自利；少阳病寒热往来、脉弦，均不同"},{"q":"患者，男，25岁。3天前因打篮球出汗后，未及时穿外套，受凉而发病。现咳嗽，痰稀色白，伴见恶寒发热，鼻塞流清涕，头身疼痛，舌淡红，苔薄白，脉浮紧。其辨证为","o":["风寒表证","风寒犯肺证","寒痰阻肺证","饮停胸胁证","肺气虚证"],"a":1,"e":"风寒袭肺，肺气失宣，故咳嗽、痰稀色白、鼻塞流清涕；风寒束表则恶寒发热、头身疼痛、脉浮紧，苔薄白。风寒表证以表证为主、咳嗽不突出；寒痰阻肺痰多清稀、无表证；饮停胸胁见胸胁引痛；肺气虚见气短乏力"},{"q":"颅内压力增高所致的呕吐特点是","o":["饭后即吐","吐利并作","朝食暮吐","吐物酸腐","呕吐如喷"],"a":4,"e":"颅内压力增高刺激呕吐中枢，故呕吐呈喷射状、来势急骤，常伴剧烈头痛。饭后即吐多属食积或胃热；吐利并作为霍乱；朝食暮吐为反胃；吐物酸腐为食积，均无喷射之象"},{"q":"患者，女，49岁。舌体疼痛衄血伴发热3天，平素时有心烦失眠，便秘，尿黄，舌尖红，苔黄，脉数有力。此属下列何证","o":["心阴虚证","心火亢盛证","肺热炽盛证","膀胱湿热证","脾胃湿热证"],"a":1,"e":"心火亢盛，循经上炎，故舌尖红、舌体疼痛衄血；火热扰心则心烦失眠，里热结实则便秘尿黄、苔黄、脉数有力。心阴虚为虚热、舌红少苔、盗汗；肺热炽盛见咳喘；膀胱湿热见尿频尿急尿痛；脾胃湿热见脘痞、苔腻"},{"q":"暑天病人发热，猝然昏倒，汗出不止，口渴气急，考虑中暑，最可能的脉象是","o":["濡数脉","弦滑脉","细涩脉","浮紧脉","浮缓脉"],"a":0,"e":"暑为阳邪，暑天感受暑热，耗气伤津，故发热、汗出不止、口渴气急、猝然昏倒；濡脉主湿、数脉主热，暑多夹湿，故见濡数脉。弦滑脉主痰饮；细涩脉主血虚瘀血；浮紧脉主风寒；浮缓脉主中风，均非中暑"},{"q":"患者腹胀拒按，纳呆食少，神疲乏力，少气懒言，形体消瘦，多考虑","o":["食积于胃","食积于肠","脾虚食积","肝郁乘脾","心脾两虚"],"a":2,"e":"脾气虚弱，运化无力，食积内停，故腹胀拒按、纳呆食少；气虚则神疲乏力、少气懒言、形体消瘦。食积于胃以嗳腐吞酸、胃脘胀满为主，无脾虚乏力；食积于肠见腹痛、大便臭如败卵；肝郁乘脾见胁胀、情志相关；心脾两虚见心悸失眠"},{"q":"患者心烦，失眠，惊悸多梦，腰膝酸软，耳鸣遗精，潮热盗汗，舌红少苔，脉细数。宜诊断为","o":["心脾两虚证","肺肾阴虚证","心肾不交证","肝肾阴虚证","心肝血虚证"],"a":2,"e":"肾阴亏虚于下，心火独亢于上，水火不交，故心烦失眠、惊悸多梦；肾虚则腰膝酸软、耳鸣遗精，阴虚内热则潮热盗汗、舌红少苔、脉细数。心脾两虚见食少便溏；肺肾阴虚见干咳；肝肾阴虚见目涩胁痛；心肝血虚见目眩、月经少"},{"q":"患者口中干渴，胸中烦热，频欲呕吐，腹部冷痛，大便溏泄，舌红苔黄白相间，脉濡数。证属","o":["上热下寒","上寒下热","表热里寒","表寒里热","真热假寒"],"a":0,"e":"胸中烦热、口渴欲呕属上焦有热；腹部冷痛、大便溏泄属下焦有寒，寒热错位，故为上热下寒。上寒下热与此相反；表热里寒、表寒里热为表里定位；真热假寒内有真热、外现假寒，与本例上下寒热并见不同"},{"q":"患者，女，38岁。症见心悸失眠，头晕健忘，面白，月经后期，舌淡，脉细，其心悸多属","o":["血虚失养","心胆气虚","阴虚火旺","心阳亏虚","水湿内停"],"a":0,"e":"血虚不能濡养心神，故心悸失眠、头晕健忘；血虚冲任不足则月经后期、量少，面白、舌淡、脉细为血虚之象。心胆气虚见惊悸、善恐；阴虚火旺见潮热盗汗、舌红；心阳亏虚见畏寒、胸闷；水湿内停见头重、苔腻、水肿"},{"q":"患者，女，49岁。时值更年，近半年来自觉躁烦不安，眠浅梦多，时常发热出汗，口干饮水不多，大便不爽，小便短黄。舌质红尖红绛，苔黄腻，脉滑数。此属下列何证","o":["心阴虚证","心火亢盛证","肝火炽盛证","痰蒙心神证","痰火扰神证"],"a":4,"e":"痰浊与火邪互结，上扰心神，故躁烦不安、眠浅梦多；痰火内蕴则苔黄腻、脉滑数，舌尖红绛、尿黄为有热，口干饮水不多、大便不爽为痰湿。痰蒙心神见神情淡漠、苔白腻；心阴虚、心火亢盛、肝火炽盛均无痰腻之象"},{"q":"心烦失眠，腰酸梦遗，头晕，舌红无苔，宜诊断为","o":["心火亢盛证","肾阴虚证","肾精不足证","心肾不交证","心阴虚证"],"a":3,"e":"肾阴亏虚，心火独亢，水火不济，故心烦失眠；肾虚精关不固则腰酸梦遗，头晕、舌红无苔为阴虚火旺。心火亢盛见口舌生疮、便秘；肾阴虚或肾精不足仅见腰酸耳鸣等肾象，无失眠；心阴虚以心悸、盗汗为主"},{"q":"患者，女，35岁。患带下病5年。带下色白质稠量多，如豆腐渣样，气味腥臭，伴阴部瘙痒，饮食二便如常。查体：舌淡红，苔灰白而腻，脉象濡缓。此人带下病的病机是","o":["脾气下陷","脾肾阳虚","湿浊下注","肝经郁热","热毒蕴蒸"],"a":2,"e":"脾虚湿浊内生，下注胞宫，故带下色白质稠量多、如豆腐渣样、气味腥臭、阴部瘙痒，苔腻、脉濡缓为湿浊之象。脾气下陷见脱肛、久泻；脾肾阳虚见带下清稀、腰膝冷痛；肝经郁热带下黄稠、口苦；热毒蕴蒸带下黄绿、臭秽"},{"q":"患者全目赤肿，伴见发热、微恶风寒，巅顶头痛，舌红，苔薄黄者，脉浮数，最宜诊断为","o":["肝胆湿热","肝经风热","肝郁气滞","肝火炽盛","心肝火旺"],"a":1,"e":"风热之邪循肝经上攻于目，故全目赤肿；巅顶为肝经循行之处，故巅顶头痛；发热、微恶风寒、脉浮数、苔薄黄为风热表证。肝胆湿热见目黄、口苦、苔黄腻；肝郁气滞见胁胀、脉弦；肝火炽盛见目赤肿痛、便秘尿黄而无表证；心肝火旺见心烦失眠"},{"q":"形寒肢冷，脘腹冷痛，纳呆呕恶，大便稀溏，肢体水肿，腰膝酸软，舌淡苔白滑，应辨证为","o":["脾气虚","脾阳虚","脾肾阳虚","寒湿困脾","寒滞胃肠"],"a":2,"e":"脾肾阳气亏虚，温煦失职，故形寒肢冷、脘腹冷痛；脾失健运则纳呆呕恶、便稀，肾阳虚水泛则肢体水肿、腰膝酸软，舌淡苔白滑为阳虚水寒。脾气虚、脾阳虚均无腰膝酸软、水肿；寒湿困脾、寒滞胃肠无腰膝酸软等肾象"},{"q":"患者脘腹胀满，嗳腐吞酸，恶心呕吐，多考虑","o":["食积于胃","食积于肠","脾虚食积","肝郁乘脾","心脾两虚"],"a":0,"e":"食积停滞于胃，胃失和降，故脘腹胀满、嗳腐吞酸、恶心呕吐，吐后胀减。食积于肠以腹痛、大便臭如败卵为主；脾虚食积兼神疲乏力、形体消瘦；肝郁乘脾见腹痛泄泻、泻后痛减；心脾两虚见心悸失眠、食少乏力"},{"q":"患者发热，其手背较手心热甚者，多为","o":["外感发热","内伤发热","气郁发热","虚证发热","瘀血发热"],"a":0,"e":"手背属表、手心属里，手背热甚于手心为外感发热，因外邪袭表、邪郁肌表，故表热明显。内伤发热、虚证发热多手心热甚于手背或五心烦热；气郁发热见身热不扬、胸胁胀满；瘀血发热见午后潮热、身体局部灼热、舌紫"},{"q":"小儿高热3日，无鼻涕咳嗽，今晨见头面胸腹部疹出，随即热退，证属","o":["半表半里","表里同病","里邪出表","热毒内闭","热证转寒"],"a":2,"e":"高热数日，邪气内郁于里，今疹毒外透、头面胸腹疹出、热随疹退，为正气驱邪外出、里邪出表的佳象。半表半里见寒热往来；表里同病为表里同时受病；热毒内闭见高热神昏、疹出不透；热证转寒见热退后现寒象，均非透疹热退"},{"q":"患者，女，35岁。腹胀痛1个月余，腹痛喜温喜按，纳少，大便清稀，白带量多质稀，舌淡胖，苔白滑，脉沉迟无力。诊为","o":["肾气不固证","寒湿困脾证","脾阳虚证","脾气虚证","脾虚气陷证"],"a":2,"e":"脾阳虚衰，寒从中生，故腹胀痛、喜温喜按、大便清稀；阳虚水湿不化，下注胞宫则白带量多质稀，舌淡胖苔白滑、脉沉迟无力。脾气虚无寒象；寒湿困脾苔白腻、身重；肾气不固见腰膝酸软、遗尿、滑胎；脾虚气陷见脱肛、久泻"},{"q":"病人口燥咽干，腹胀硬满而痛，不大便或下利清水，其证属","o":["少阴兼阳明病证","少阴兼太阳病证","少阳兼太阳病证","少阳病证","少阴病证"],"a":0,"e":"口燥咽干、腹胀硬满而痛、不大便或下利清水为阳明腑实、热结旁流；兼少阴阴亏，故为少阴兼阳明病证。少阴兼太阳见恶寒发热、脉沉；少阳兼太阳见寒热往来、头项强痛；单纯少阳病见口苦、寒热往来；少阴病但欲寐、脉微细"},{"q":"病人寒热往来，复见腹满痛，郁郁微烦，心以下急，大便不通，舌苔干黄等，其证属","o":["少阳兼阳明病证","阳明兼太阳病证","少阳兼太阳病证","少阳病证","阳明病证"],"a":0,"e":"寒热往来、郁郁微烦为少阳枢机不利；腹满痛、心下急、大便不通、苔干黄为阳明腑实，故为少阳兼阳明病证。阳明兼太阳见身热、汗出、恶寒；少阳兼太阳见头项强痛；单纯少阳病无腹满便秘；阳明病但热不寒、无寒热往来"},{"q":"患者心脾有热，其舌态可见","o":["痿软舌","强硬舌","歪斜舌","颤动舌","吐弄舌"],"a":4,"e":"心脾有热，热灼津伤，扰动心神，故舌体伸出即收回、反复吐弄，即吐弄舌，多见于小儿。痿软舌主气血津液亏虚；强硬舌主热入心包或中风；歪斜舌主中风偏瘫；颤动舌主肝风内动，均非心脾有热"},{"q":"久流浊涕，质稠量多，气味腥臭属","o":["外感风邪","湿热蕴阻","痰热壅肺","外感风寒","燥邪犯肺"],"a":1,"e":"湿热蕴阻鼻窍，气血壅滞，故久流浊涕、质稠量多、气味腥臭，即鼻渊。外感风邪、外感风寒多流清涕、病程短；痰热壅肺见咳痰黄稠；燥邪犯肺鼻干、涕少而稠，均无久流腥臭浊涕"},{"q":"患者畏冷肢凉，喜静蜷卧，口淡不渴，小便清长，夜尿多，面色淡白，恶心欲吐，脉沉迟无力。证属","o":["表实寒证","表实热证","里实寒证","里虚寒证","里虚热证"],"a":3,"e":"阳气亏虚，寒自内生，病在脏腑，故畏冷肢凉、喜静蜷卧、脉沉迟无力；里寒则口淡不渴、小便清长、夜尿多、面色淡白。表实寒证恶寒发热、无汗、脉浮紧；表实热证发热恶寒、脉浮数；里实寒证起病急、腹痛拒按；里虚热证见潮热盗汗"},{"q":"患者，女，47岁。近半年来经常头晕耳鸣，两目干涩，五心烦热，夜寐多梦，口燥咽干，舌红少津，脉弦细数。其五心烦热的病机是","o":["阴虚内热","精血亏虚","津液亏虚","肾精亏虚","气血亏虚"],"a":0,"e":"肝肾阴虚，阴液不足，虚热内生，故五心烦热、口燥咽干、舌红少津、脉细数；阴虚阳亢则头晕耳鸣、两目干涩、夜寐多梦。精血亏虚、津液亏虚、肾精亏虚均以亏虚为主，无明显虚热；气血亏虚见面白、乏力、舌淡"},{"q":"选择与脘腹胀满，不思饮食，身重困倦，大便溏薄，小便短赤，脉濡数等证候相符合的舌象","o":["舌绛红苔腻","舌红苔黄腻","舌青紫苔白润","舌红苔黄燥","红舌苔黄"],"a":1,"e":"湿热内蕴中焦，故脘腹胀满、不思饮食、身重困倦、大便溏薄、小便短赤，脉濡数；舌红主热、苔黄腻主湿热。舌绛红苔腻主热入营血；舌青紫苔白润主寒凝血瘀；舌红苔黄燥主热盛伤津；红舌苔黄主里热、腻象不显"},{"q":"病人脉微细，但欲寐，其证属","o":["太阴病证","厥阴病证","少阴病证","阳明病证","太阳病证"],"a":2,"e":"少阴病为心肾阳虚、气血不足，故脉微细、但欲寐，即神疲欲睡、精神萎靡，为少阴病提纲证。太阴病腹满而吐、自利；厥阴病寒热错杂、消渴吐蛔；阳明病身热汗出、便秘；太阳病恶寒发热、脉浮，均不同"},{"q":"患者，女，45岁，教师。因工作繁忙于半年前开始出现心悸心烦，失眠多梦等症，伴五心烦热，盗汗，颧红，舌红少津，脉细数。其盗汗的病机是","o":["血虚失养","心脾两虚","阴虚火旺","痰火扰神","心胆气虚"],"a":2,"e":"阴虚火旺，虚火内扰心神，故心悸心烦、失眠多梦；阴虚内热则五心烦热、盗汗、颧红、舌红少津、脉细数。血虚失养见面白、舌淡、无潮热；心脾两虚见食少乏力；痰火扰神见苔黄腻、躁动；心胆气虚见惊悸、善恐"},{"q":"患者，男，31岁。多汗，烦躁口渴，但热不寒，咳嗽气喘，苔黄，脉数，其临床意义是","o":["邪热壅肺证","湿热阻肺证","邪犯肺卫证","邪陷心包证","湿蒙心包证"],"a":0,"e":"邪热壅滞于肺，肺失宣降，故咳嗽气喘；里热炽盛则但热不寒、烦躁口渴、多汗、苔黄、脉数。湿热阻肺见胸闷、苔腻；邪犯肺卫见发热恶寒、脉浮数；邪陷心包、湿蒙心包均有神昏谵语，均非本例"},{"q":"患者，男，20岁。5天前受凉后出现恶寒发热，无汗，咳嗽，夜间加剧，咳痰稀薄色白，舌苔薄白腻，脉浮紧。其证候是","o":["风寒束肺证","寒邪客肺证","痰湿阻肺证","燥邪犯肺证","饮停于肺证"],"a":0,"e":"风寒外束，肺气闭郁，故恶寒发热、无汗、咳嗽、痰稀薄色白，脉浮紧、苔薄白腻。寒邪客肺病程较长、无表证；痰湿阻肺痰多黏稠、胸闷；燥邪犯肺干咳少痰、口鼻干；饮停于肺痰多清稀、倚息不得卧"},{"q":"患者心悸，失眠，多梦，健忘，头晕目眩，面色淡白，口唇淡白，舌淡白，脉沉细无力。应诊断为","o":["心阴虚证","心气虚证","心血虚证","心肾不交证","心脾两虚证"],"a":2,"e":"心血亏虚，心神失养，故心悸、失眠多梦、健忘；血虚不能上荣则头晕目眩、面色与口唇淡白、舌淡白、脉沉细无力。心阴虚见潮热盗汗、舌红少苔；心气虚见气短乏力；心肾不交见腰膝酸软；心脾两虚见食少便溏"},{"q":"患者咳嗽无痰，乏力咽燥，低热不退，舌红少苔，脉细数。此属","o":["阳虚证","阴虚证","阴阳两虚证","真实假虚证","真虚假实证"],"a":1,"e":"阴液亏虚，虚热内生，肺失润降则咳嗽无痰、咽燥；虚热则低热不退，乏力、舌红少苔、脉细数为阴虚之象。阳虚证见畏寒肢冷、舌淡；阴阳两虚寒热并见；真实假虚、真虚假实为虚实真假错杂，与本例不符"},{"q":"患者，女，53岁。近来时感口咽干燥，但不欲饮水，伴见头身困重，身热不扬，脘闷不饥，舌红苔黄腻，脉濡数。其口渴的病机为","o":["燥邪袭表","湿遏热伏","痰火内扰","热盛阴伤","热入营分"],"a":1,"e":"湿邪遏阻，热邪郁伏于内，不能外达，故身热不扬；湿胜则口咽干燥却不欲饮水、头身困重、脘闷不饥，舌红苔黄腻、脉濡数为湿热。燥邪袭表口干欲饮、苔干；痰火内扰见苔黄腻、神烦；热盛阴伤大渴喜冷；热入营分见神昏、舌绛"},{"q":"患者，女，48岁。手足蠕动，瘈疭，五心烦热，心中憺憺大动，舌绛苔少，脉虚，其临床意义是","o":["肝阴虚证","肾精耗损证","肾阴虚证","血虚动风证","虚风内动证"],"a":0,"e":"肝阴亏虚，筋脉失养，虚风内动，故手足蠕动、瘈疭、心中憺憺大动；阴虚内热则五心烦热，舌绛苔少、脉虚。肾精耗损以发育迟缓、早衰为主；肾阴虚兼腰膝酸软、遗精；血虚动风见面白、舌淡；本例以阴虚为本，故属肝阴虚"},{"q":"Page-FrameX年X月X日X时 XX科别姓名 性别 年龄 职业主诉：患者就诊的主要症状（或体征）及持续时间。病史：主症发生的时间、病情的发展变化、诊治经过及重要的既往病史、个人史和过敏史等。体格检查：记录生命体征、中西医检查阳性体征及具有鉴别意义的阴性体征。特别要注意舌象、脉象。实验室检查：记录就诊时已获得的有关检查结果。诊断：中医诊断（包括疾病诊断与证的诊断）：西医诊断：处理：（1）中医论治：记录治则治法、方药、用法等。（2）西医治疗：记录具体用药、剂量、用法等。（3）进一步的检查项目。（4）饮食起居宜忌、随诊要求、注意事项。医师签名：以上病历书写格式是","o":["门诊病历的初诊记录","门诊病历的复诊记录","住院病历的初诊记录","住院病历的复诊记记录","住院病历的病程记录"],"a":0,"e":"该格式含主诉、病史、体格检查、实验室检查、诊断及处理、医师签名等完整项目，为门诊病历初诊记录。复诊记录着重记录复诊时病情变化与用药反应；住院病历初诊含入院记录、病程记录等更详细内容；病程记录为住院期间病情演变记录，均不符"},{"q":"陈某，男，20岁，学生。2011年3月9日初诊。因发热、咳嗽、气喘1天就诊。患者于昨日外出春游，忽遇大雨，全身淋湿，当夜即感恶寒，随之发热，一身疼痛……病案中的“陈某，男，20岁，学生。2011年3月9日初诊。”是","o":["一般情况","主诉","现病史","既往史","个人史"],"a":0,"e":"姓名、性别、年龄、职业及就诊日期属病案中的一般情况。主诉为主要症状及持续时间；现病史为主症发生、发展及诊治经过；既往史为既往疾病史；个人史为生活、习惯等，均非本例所述内容"},{"q":"患者恶风发热，口干，咽喉不利，干咳少痰，尿少边干，苔干燥，脉浮，宜诊断为","o":["风淫证","寒淫证","暑淫证","燥淫证","火淫证"],"a":3,"e":"燥邪伤津，肺失润降，故口干、咽喉不利、干咳少痰、苔干燥、尿少；燥邪在表则恶风发热、脉浮。风淫证以恶风汗出、咽痒咳嗽为主；寒淫证恶寒重、无汗；暑淫证汗多、身倦；火淫证高热、口渴、苔黄，均非燥象"},{"q":"霍乱的呕吐特点是","o":["饮后即吐","吐利并作","朝食暮吐","吐物酸腐","呕吐酸腐"],"a":1,"e":"霍乱由秽浊疫邪直中脾胃，清浊相干，上吐下泻并作，故呕吐特点为吐利并作。饮后即吐多属水逆或胃热；朝食暮吐为反胃；吐物酸腐为食积；呕吐酸腐亦属食积或胃热，均无吐利同时发作之特征"},{"q":"心悸，面白，肢体麻木，月经量少、色淡，舌淡脉细。宜诊断为","o":["心脾两虚证","心血虚证","肝血虚证","心肝血虚证","心阴虚证"],"a":3,"e":"心血不足则心悸，肝血亏虚、筋脉失养则肢体麻木，冲任血虚则月经量少色淡，面白、舌淡、脉细为血虚之象，故为心肝血虚。心脾两虚兼食少腹胀便溏；心血虚无麻木、月经改变；肝血虚无心悸；心阴虚见潮热、舌红少苔"},{"q":"哮病的原因是","o":["肺肾亏虚，气失摄纳","水汽上凌心肺","寒邪、热邪袭肺","痰饮内伏，复感外邪","脾肺气虚，内生痰湿"],"a":3,"e":"哮病以痰饮内伏于肺为夙根，复感外邪、饮食、情志等诱发，痰气交阻、气道挛急，故发作性喉中哮鸣、呼吸急促。肺肾亏虚、气失摄纳为喘证之虚；水气凌心肺见心悸、水肿；寒热袭肺为外感诱因之一，但非夙根；脾肺气虚生痰为兼夹"},{"q":"患者，女，35岁。主诉月经量多，每次月经持续10余日不止，现自觉眩晕，肢体不自主震颤，四肢麻木拘急，面白无华，舌质淡白，脉细无力。辨证属","o":["肝阴虚证","肝火炽盛证","肝血虚证","肝阳上亢证","血虚生风证"],"a":4,"e":"月经量多致血虚，筋脉失养，虚风内动，故肢体不自主震颤、四肢麻木拘急、眩晕，面白无华、舌淡白、脉细无力为血虚之象。肝阴虚见目涩、潮热；肝火炽盛见目赤、便秘；肝血虚虽有血虚但无动风；肝阳上亢见头胀、脉弦"},{"q":"肖某，女，70岁。长期反复腹泻，肛门Ⅰ度脱垂，腹痛隐隐，喜温喜按，平素畏寒、神疲乏力、气短懒言，舌淡苔白滑，脉弱。最宜辨证为","o":["肺气虚证","肾阳虚证","肠虚滑泻证","肾气不固证","寒凝肠道证"],"a":2,"e":"久病大肠虚寒，失于固摄，故长期腹泻、肛门脱垂、腹痛隐隐、喜温喜按，畏寒、神疲乏力、气短懒言、舌淡苔白滑、脉弱为阳虚气弱。肺气虚见咳喘；肾阳虚兼腰膝冷痛、五更泄；肾气不固见遗尿、滑精；寒凝肠道见冷痛、便秘"},{"q":"患者突然昏仆，经救治后口舌歪斜，语言謇涩，一侧上下肢痿废不用，舌淡红，脉弦细。多见于","o":["痿病","中风","截瘫","痹病","佝偻病"],"a":1,"e":"中风以突然昏仆、口舌歪斜、语言謇涩、半身不遂为主症，因风痰瘀血闭阻脑络。痿病为肢体筋脉弛缓、软弱无力、日久肌肉萎缩，无昏仆、口歪；截瘫为下肢瘫痪、有外伤或脊髓病史；痹病为关节疼痛、重着；佝偻病为小儿骨骼畸形"},{"q":"患者腹痛腹泻，大便臭如败卵，多考虑","o":["食积于胃","食积于肠","脾虚食积","肝郁乘脾","心脾两虚"],"a":1,"e":"食积停滞于肠，传导失常，腐败下行，故腹痛腹泻、大便臭如败卵，泻后痛减。食积于胃以脘腹胀满、嗳腐吞酸、恶心呕吐为主；脾虚食积兼乏力、消瘦；肝郁乘脾见腹痛泄泻、泻后痛减、胁胀、脉弦；心脾两虚见心悸失眠、食少"},{"q":"患者，男，76岁。患有慢性支气管炎20余年，胸廓饱满，胁间胀闷，呼吸、咳嗽或转侧时牵引作痛，咯吐白色泡沫痰，舌苔白滑，脉沉弦。辨证为","o":["肺气虚证","痰热壅肺证","风寒犯肺证","寒痰阻肺证","饮停胸胁证"],"a":4,"e":"水饮停聚胸胁，气机阻滞，故胸廓饱满、胁间胀闷，呼吸咳嗽或转侧时牵引作痛；饮为阴邪则咯白色泡沫痰、苔白滑、脉沉弦。肺气虚见气短乏力；痰热壅肺痰黄稠；风寒犯肺有表证；寒痰阻肺痰多清稀、畏寒，均无胸胁引痛"},{"q":"患者心悸失眠，月经量少色淡，头晕目眩，舌质淡白，脉虚，辨证为","o":["气不摄血证","气血两虚证","气随血脱证","亡阳证","亡阴证"],"a":1,"e":"气血亏虚，心神失养则心悸失眠，清窍失养则头晕目眩，冲任血虚则月经量少色淡，舌淡白、脉虚为气血两虚。气不摄血有出血；气随血脱见于大出血后；亡阳证见冷汗、四肢厥冷、脉微；亡阴证见汗热、身热、脉细数"},{"q":"患者，男，68岁。近半月来自觉心慌怔忡，时有心胸憋闷疼痛。平素畏冷肢凉，动辄气短，汗出，随后发凉，神疲乏力。刻下：面色㿠白，口唇发紫，舌质淡胖或紫黯，苔白滑，脉结而无力。此属下列哪个证候","o":["心阴虚证","心血虚证","心气虚证","心阳虚证","心阳暴脱证"],"a":3,"e":"心阳亏虚，温煦推动无力，故心慌怔忡、心胸憋闷疼痛、畏冷肢凉；阳虚卫外不固则汗出，汗后阳更虚故发凉；气血瘀滞则口唇发紫、舌紫黯，脉结而无力。心气虚无畏冷、舌胖；心血虚见失眠、舌淡；心阴虚见潮热、舌红少苔；心阳暴脱见大汗、脉微欲绝"},{"q":"患者，男。右少腹突发疼痛而拒按，且有反跳痛，多为","o":["虫积","肠痈","癥积","瘕聚","筋瘤"],"a":1,"e":"肠痈以右下腹突发疼痛、拒按、反跳痛为特征，因湿热瘀滞、肠道不通。虫积多见脐周阵痛；癥积为腹内肿块、痛有定处、病程长；瘕聚为肿块推之可移、痛无定处；筋瘤为静脉曲张团块，均无反跳痛"},{"q":"患者消渴，气上撞心，心中疼热，饥而不欲食，食则吐蛔，下之利不止，其证属","o":["太阴病证","厥阴病证","少阴病证","阳明病证","太阳病证"],"a":1,"e":"厥阴病为寒热错杂、阴阳相争，肝木乘脾，故消渴、气上撞心、心中疼热、饥不欲食、食则吐蛔，误下则利不止。太阴病腹满自利、口不渴；少阴病脉微细、但欲寐；阳明病身热、便秘、口渴；太阳病恶寒发热、脉浮，均不同"},{"q":"患者，女，主诉痛经，月经不调，周期不定，伴有善太息，胸胁、少腹胀满疼痛，走窜不定，舌苔薄白，脉弦。辨证属","o":["肝阴虚证","肝火炽盛证","肝郁气滞证","肝风内动证","寒滞肝脉证"],"a":2,"e":"肝失疏泄，气机郁滞，冲任失调，故痛经、月经不调、周期不定；气滞则善太息、胸胁少腹胀满疼痛、走窜不定，脉弦。肝阴虚见目涩、潮热；肝火炽盛见口苦、便秘、目赤；肝风内动见震颤、抽搐；寒滞肝脉见少腹冷痛、得温则减"},{"q":"患者发热，面红口渴，心烦失眠，小便黄赤，大便干结，舌红苔黄，脉数。证属","o":["表热证","里热证","表里俱热证","真寒假热证","真热假寒证"],"a":1,"e":"邪热入里，燔灼脏腑，故发热、面红、口渴、心烦失眠；里热伤津则小便黄赤、大便干结、舌红苔黄、脉数，无恶寒表证。表热证发热轻、恶寒重、脉浮；表里俱热兼恶寒、脉浮数；真寒假热、真热假寒为寒热真假错杂，均非本例"},{"q":"呕吐呈喷射状，属于","o":["热扰神明","肝气犯胃","胃痛","反胃","胃热"],"a":0,"e":"热扰神明致胃气上逆，故呕吐呈喷射状、来势急，多伴头痛、神昏。肝气犯胃呕吐伴胁胀、嗳气、情志相关；胃痛以胃脘痛为主；反胃为朝食暮吐、暮食朝吐；胃热呕吐伴口臭、口渴、苔黄，均无喷射之象"},{"q":"鼻渊的主要特征是","o":["鼻翼扇动","鼻流脓涕","偶流清涕","久流浊涕而腥臭","鼻流黄涕"],"a":3,"e":"鼻渊以鼻流浊涕、量多、久流不止、气味腥臭为主要特征，因湿热蕴阻鼻窍。鼻翼扇动为呼吸困难、肺热壅盛；鼻流脓涕、黄涕可见于鼻渊或风热，但未突出久流、腥臭；偶流清涕为正常或风寒初起，均非鼻渊特征"},{"q":"咳声如犬吠样，伴声音嘶哑，吸气困难者，称为","o":["百日咳","白喉","燥咳","热咳","寒哮"],"a":1,"e":"白喉为白喉杆菌感染，咽喉部有灰白色假膜，气道狭窄，故咳声如犬吠、声音嘶哑、吸气困难。百日咳咳声阵发、连续十余声后伴鸡鸣样回声；燥咳干咳少痰；热咳痰黄稠；寒哮喉中哮鸣、呼吸急促，均无犬吠样咳"},{"q":"患者，女，35岁。胃脘疼痛反复发作5年余，每因饮食不慎而发。1周前因进食冷面而诱发。现症见胃脘冷痛，喜温喜按，得食痛减，形体消瘦，神疲乏力，纳少，舌淡，脉沉无力。其脘痛的病机是","o":["胃气虚","胃阳虚","寒凝胃脘","气滞胃脘","饮停胃脘"],"a":1,"e":"胃阳不足，寒自内生，胃失温养，故胃脘冷痛、喜温喜按、得食痛减；阳虚运化失职则形瘦、神疲乏力、纳少，舌淡、脉沉无力。胃气虚仅有隐痛、乏力，无冷痛；寒凝胃脘起病急、痛剧；气滞胃脘胀痛、脉弦；饮停胃脘见脘闷、呕吐清涎"},{"q":"患者，男，30岁。 高热3天，大渴喜饮，面赤，汗出，舌红苔黄燥，其发热的病机是","o":["气分热盛","阳明腑证","热陷心包","热入营分","湿热蕴结"],"a":0,"e":"邪热入气分，正邪剧争，故高热；热盛伤津则大渴喜饮、面赤、汗出、舌红苔黄燥。阳明腑证见潮热、便秘、腹满硬痛；热陷心包见神昏谵语；热入营分见身热夜甚、舌绛、斑疹；湿热蕴结见身热不扬、苔腻，均非气分大热"},{"q":"患者，女，23岁。痛经5年，平素急躁易怒，每至经期小腹疼痛难忍，脾气不能自控，舌质紫黯，脉弦，辨证为","o":["气血两虚证","气虚血瘀证","气不摄血证","气随血脱证","气滞血瘀证"],"a":4,"e":"情志不畅，肝气郁结，气滞则血行不畅，瘀阻胞宫，故经行小腹疼痛难忍、急躁易怒、舌紫黯、脉弦。气血两虚见面白、隐痛；气虚血瘀见乏力、刺痛；气不摄血有出血；气随血脱见于大出血后，均非本例"},{"q":"李某，女，31岁。昨日因家事不和，争吵怒骂，今晨突然耳鸣，声大如雷鸣，伴有口苦，左目内眦红赤，胁肋灼痛，胸闷心烦，舌红苔薄黄而干，脉象弦数。该病人突发耳鸣的病机是","o":["肝胆火盛","痰浊上蒙","瘀血阻滞","风邪上袭","肾气虚弱"],"a":0,"e":"暴怒伤肝，肝胆火盛，循经上扰清窍，故突发耳鸣、声大如雷鸣；肝胆火旺则口苦、目赤、胁肋灼痛、心烦，舌红苔黄、脉弦数。痰浊上蒙耳鸣声低、头重苔腻；瘀血阻滞刺痛固定；风邪上袭伴外感表证；肾气虚弱耳鸣渐起、腰膝酸软"},{"q":"患者，男。感受寒邪，出现少腹冷痛，阴囊收缩掣痛，遇寒加重，得温则减，呕吐清涎，形寒肢冷，舌苔白，最有可能的脉象是","o":["弦紧脉","弦数脉","细数脉","沉细脉","细弦脉"],"a":0,"e":"寒邪侵袭肝脉，寒凝气滞，故少腹冷痛、阴囊收缩掣痛、遇寒加重、得温则减、形寒肢冷；弦脉主痛、主肝，紧脉主寒，故见弦紧脉。弦数脉主肝火；细数脉主阴虚；沉细脉主血虚；细弦脉主肝郁血虚，均非寒凝肝脉"},{"q":"患者，男，40岁。平时性情急躁易怒，近2周失眠多梦，头晕，口舌溃疡肿痛，尿黄，大便干结，舌红苔黄，脉滑数。其证候为","o":["肝火上炎证","心火亢盛证","胃火上冲证","脾胃湿热证","肾火上炎证"],"a":1,"e":"心火亢盛，上炎口舌则口舌溃疡肿痛；火热扰心则失眠多梦、头晕、急躁；里热结实则尿黄、大便干结、舌红苔黄、脉数。肝火上炎见目赤、胁痛；胃火上冲见口臭、牙龈肿痛；脾胃湿热见脘痞、苔腻；肾火上炎见潮热、腰酸，均非本例"},{"q":"患者，女，10岁。壮热烦躁，满面通红，目赤口渴，辨证为","o":["戴阳证","阳虚证","阴虚证","湿热证","实热证"],"a":4,"e":"实热证为邪热亢盛、正气不虚，故壮热、烦躁、满面通红、目赤、口渴，属里实热。戴阳证面色浮红如妆、游移不定、四肢厥冷；阳虚证畏寒肢冷、面色㿠白；阴虚证潮热盗汗、颧红；湿热证身热不扬、苔腻，均不同"},{"q":"患者咳血，心烦，身热，舌红绛，脉滑数，诊断为","o":["气虚证","气滞证","血虚证","血热证","血瘀证"],"a":3,"e":"热入血分，迫血妄行则咳血；热扰心神则心烦；身热、舌红绛、脉滑数皆为里热炽盛之象，故属血热证。气虚证项实为气不摄血，虽可出血但伴神疲乏力、舌淡脉弱；血瘀证项见出血色暗夹块、刺痛固定、舌紫暗；血虚证项以面色淡白、头晕心悸、舌淡为特征"},{"q":"患者，男，37岁。1周前出现恶寒发热，倦怠乏力，脘闷不饥，厌油腻，经某医院按“感冒”治疗，恶寒发热减轻。现患者腹痛泄泻，便溏不爽，伴呕恶纳呆，厌食油腻，脘腹痞闷，肢体困重，身热不扬，口微渴，小便短黄，舌质红，苔黄腻，脉濡数。其病证机理为","o":["肝胆湿热","脾胃湿热","湿热感冒","食滞胃脘","肝火犯胃"],"a":1,"e":"湿热蕴结脾胃，运化失司则脘腹痞闷、呕恶纳呆、便溏不爽；肢体困重、身热不扬、苔黄腻、脉濡数均为湿热之征。肝胆湿热项实为肝胆疏泄失常，以胁痛、口苦、黄疸为主；食滞胃脘项描述的是嗳腐吞酸、泻后痛减；肝火犯胃项见胁痛灼热、呕吐酸水"},{"q":"患者，女，50岁。两颧潮红，午后低热，心烦失眠，辨证为","o":["阳虚证","阴虚证","戴阳证","实热证","湿热证"],"a":1,"e":"阴液亏少，虚火内扰，故两颧潮红、午后低热、心烦失眠，舌红少苔、脉细数。阳虚证项实为阳气不足，见畏寒肢冷、舌淡苔白；戴阳证项描述的是虚阳上浮，面红如妆而下肢厥冷、脉微；实热证项见高热烦渴、苔黄燥、脉洪数；湿热证项身热不扬、苔黄腻"},{"q":"患者，男，60岁。腹胀大如鼓，按之如囊裹水，有波动感。应首先考虑的是","o":["水饮","痞满","积聚","水臌","内痈"],"a":3,"e":"腹胀大如鼓、按之如囊裹水且有波动感，为水饮停聚腹中、气化不利之水臌。水饮项实为饮停胃肠，见脘腹痞满、水声辘辘而腹不大；痞满项描述的是自觉胀满而外形无形；积聚项见腹内结块、或痛或胀；内痈项有局部红肿热痛与发热"},{"q":"患者头面部皮肤焮红灼热，色如涂丹，肿胀疼痛，甚至发生水疱，眼胞肿胀难睁；伴恶寒发热，头痛，舌红，苔薄黄，脉浮数。此病宜诊断为","o":["风热火毒上攻之抱头火丹","天行时疫，火毒上攻之大头瘟","血分火毒之丹毒","湿热毒蕴之流火","肝经郁火之赤游丹"],"a":0,"e":"风热火毒上攻头面，血分受热则皮肤焮红灼热、色如涂丹、肿胀疼痛，兼恶寒发热、脉浮数，为抱头火丹。大头瘟项实为天行时疫之毒上攻，头面红肿而传染性强；丹毒项描述的是血分火毒泛发躯干四肢；流火项为湿热毒蕴下注之小腿丹毒；赤游丹项多见小儿、红肿游走不定"},{"q":"患者潮热，盗汗2年，昨日起恶寒低热，头项强痛，舌红苔白，脉浮细，证属","o":["表实寒里虚热","表实热里虚寒","表实寒里虚寒","表实热里虚热","表实热里实寒"],"a":0,"e":"潮热盗汗两年为里有虚热，昨起恶寒低热、头项强痛、脉浮为复感风寒之邪，故属表实寒里虚热。表实热里虚寒项实为外感风热兼里阳虚；表实寒里虚寒项描述的是外寒内寒、无潮热盗汗；表实热里虚热项见发热重恶寒轻与五心烦热并见；表实热里实寒项里无虚象"},{"q":"患者，女，39岁。小便频数2日，一昼夜达20余次，尿时涩痛不爽，小腹胀闷，尿道灼热，小便黄赤短少，口干，舌红，苔根部黄腻，脉滑数。其尿频的病机为","o":["膀胱湿热","小肠实热","肾阴亏虚","肾阳不足","肾气不固"],"a":0,"e":"湿热下注膀胱，气化不利则尿频涩痛、灼热黄赤，舌根黄腻、脉滑数为湿热之征。小肠实热项实为心火下移，见心烦口舌生疮、小便赤涩；肾阴亏虚项描述的是腰膝酸软、潮热盗汗、尿频无灼痛；肾阳不足项见夜尿清长、畏寒；肾气不固项见尿频失禁、尿色清"},{"q":"患者，男，28岁。腹痛泄泻反复发作已2年余，常因情志不遂或精神紧张而发，曾在某西医院诊断为“肠易激综合征”，因服西药无显效而求治中医。患者腹痛即泻，泻后痛减，每日4～5次，伴胸胁胀闷，情志抑郁，善太息，腹胀纳呆，肠鸣矢气，舌苔白，脉弦。中医辨证为","o":["脾气虚弱","肝郁脾虚","大肠湿热","心脾两虚","脾肾阳虚"],"a":1,"e":"情志不遂致肝气郁结，横逆犯脾，肝病则胸胁胀闷、善太息、脉弦，脾病则腹痛即泻、泻后痛减、腹胀纳呆，故为肝郁脾虚。脾气虚弱项实为运化失职，见食后腹胀、便溏乏力而无情志诱因；大肠湿热项描述的是下痢脓血、里急后重；脾肾阳虚项见五更泄泻、畏寒肢冷"},{"q":"患者颈前结喉处有肿块突起，见于双侧，可随吞咽上下移动，伴有眼球突出，形体消瘦，为","o":["瘿瘤","瘰疬","痄腮","发颐","乳蛾"],"a":0,"e":"颈前结喉处肿块随吞咽上下移动，伴眼球突出、形体消瘦，为瘿瘤，因气郁痰凝、肝火上扰所致。瘰疬项实为颈部淋巴结结核，见多个小结节如串珠；痄腮项描述的是耳下腮部肿痛、发热；发颐项为急性化脓性腮腺炎，红肿热痛明显；乳蛾项见咽喉肿痛、扁桃体红肿"},{"q":"蔡某，女，42岁，3日前食生鱼片后自觉胃脘冷痛，遇寒加剧，得温则减，口淡不渴，口泛清水，舌苔白润，脉弦。诊为","o":["胃阳虚证","寒滞胃脘证","胃热炽盛证","饮停胃肠证","食滞胃脘证"],"a":1,"e":"冷积新伤胃脘，寒凝气滞则冷痛遇寒加剧、得温则减，胃气上逆则口泛清水、口淡不渴，脉弦为寒痛，故属寒滞胃脘。胃阳虚证项实为虚寒，病程长、喜温喜按、畏寒肢冷；胃热炽盛项描述的是胃脘灼痛、口臭牙龈肿痛；饮停胃肠项见胃脘水声辘辘；食滞胃脘项见嗳腐吞酸、泻后痛减"},{"q":"患者，男，34岁。感冒痊愈后，遗留了咳痰的后遗症，刻下症见咳嗽痰多，痰质黏稠，恶心纳呆，头晕目眩，舌苔腻，脉滑。辨证为","o":["津液亏虚证","饮证","痰证","水停证","血热证"],"a":2,"e":"痰浊内停，阻滞气机则咳嗽痰多黏稠、恶心纳呆；痰蒙清阳则头晕目眩，苔腻脉滑为痰之常象。津液亏虚项实为津伤化燥，见口干咽燥、舌干少津；饮证项描述的是痰涎清稀、水声辘辘；水停项见水肿、小便不利；血热项见出血、舌红绛、脉数"},{"q":"患者，女，78岁。主诉手足震颤，肢体不自主抽动，伴有眩晕，口干，五心烦热，形体消瘦，舌红少津，脉弦细数。辨证属","o":["肝阴虚证","肝火炽盛证","阴虚动风正","肝阳上亢证","寒滞肝脉证"],"a":2,"e":"阴液亏虚，筋脉失养，虚风内动则手足震颤、肢体抽动；眩晕、五心烦热、消瘦、舌红少津、脉弦细数皆为阴虚风动之象。肝阴虚证项实为阴亏而无风动，仅见目涩、潮热；肝火炽盛项描述的是目赤口苦、便秘尿黄；肝阳上亢项见头目胀痛、面红目赤；寒滞肝脉项见少腹冷痛、阴器收缩"},{"q":"患者胸胁灼痛，急躁易怒，咳嗽阵作，有时痰中带血，痰色黄黏，面红目赤，舌红苔黄，脉弦数。应诊断为","o":["痰热壅肺证","肝火上炎证","肺热炽盛证","肝火犯肺证","肝胃不和证"],"a":3,"e":"肝郁化火，上逆犯肺，木火刑金则胸胁灼痛、急躁易怒、咳嗽阵作、痰黄带血，面红目赤、脉弦数为肝火之象。痰热壅肺项实为痰热蕴肺，见咳喘痰黄稠、胸闷而无胸胁灼痛；肝火上炎项描述的是目赤口苦、头痛眩晕但不咳血；肺热炽盛项见发热咳喘、口渴便秘；肝胃不和项见胃脘胀痛、嗳气吞酸"},{"q":"患者小腿青筋怒张隆起，形似蚯蚓，多属","o":["肝风内动，筋脉拘急","寒湿内侵，络脉血瘀","寒湿久留，气血亏虚","脾肾失调，水湿停留","肾精亏损，发育不良"],"a":1,"e":"小腿青筋怒张隆起、形似蚯蚓，为寒湿之邪内侵下肢，阻滞络脉，血行瘀滞所致。肝风内动项实为筋脉拘急，见肢体震颤、抽搐、眩晕；寒湿久留气血亏虚项描述的是肢体麻木无力、面色萎黄；脾肾失调水湿停留项见下肢水肿、按之没指；肾精亏损项见发育不良、五迟五软"},{"q":"患者肛门内生有紫红色柔软肿块，伴便血、疼痛、便秘等症状，为","o":["肛裂","痔疮","肛瘘","脱肛","肛痈"],"a":1,"e":"肛门内紫红色柔软肿块伴便血、疼痛、便秘，为痔，因血脉瘀滞、湿热下注肛门所致。肛裂项实为肛管裂伤，见排便刀割样痛、少量鲜血；肛瘘项描述的是肛周瘘管反复流脓；脱肛项为直肠脱出肛外；肛痈项为肛周脓肿，见局部红肿热痛、发热"},{"q":"患者畏寒肢冷，尿少浮肿，心悸怔忡，口唇爪甲青紫，舌质淡胖，苔白滑，脉沉细。应诊断","o":["脾阳虚证","心阴虚证","肾阳虚证","心肾阳虚证","脾肾阳虚证"],"a":3,"e":"心阳虚衰则心悸怔忡、唇甲青紫，肾阳虚衰则畏寒肢冷、尿少浮肿，舌淡胖苔白滑、脉沉细为阳虚水停，故属心肾阳虚。脾阳虚证项实为运化失职，见腹胀便溏、纳差；心阴虚证项描述的是心悸失眠、五心烦热、舌红少苔；肾阳虚证项见腰膝酸软、夜尿多而心悸不显；脾肾阳虚项见五更泄泻"},{"q":"患者，男，30岁。寒战后高热，反复发作，每2日1次，伴剧烈头痛，口渴多汗等症，其寒热类型属于","o":["恶寒发热","但寒不热","新病恶寒","寒热往来","但热不寒"],"a":3,"e":"寒战与高热交替、反复发作且有定时，为邪伏半表半里、正邪交争之寒热往来，疟疾即其典型。恶寒发热项实为恶寒与发热同时并见，属表证；但寒不热项描述的是只有寒象、属里寒；新病恶寒项见初起恶寒重发热轻；但热不寒项为里热证，无寒战"},{"q":"患者经常刷牙时牙龈渗血，见牙龈萎缩，颜色淡白，牙根宣露，牙齿松动，咀嚼无力。症见面色淡白，倦怠乏力，头晕眼花，胃呆纳少，舌淡，苔薄白，脉沉细。此病最宜诊断为","o":["脾不统血","肾阴亏虚","胃阴不足","脾阳亏虚","胃火亢盛"],"a":0,"e":"脾气虚弱，统血失职则牙龈渗血；气血不足，齿失所养则牙龈萎缩色淡、牙根宣露、牙齿松动，面色淡白、乏力、脉沉细皆为脾虚气血亏少。肾阴亏虚项实为阴虚火旺，见牙齿松动、潮热盗汗、舌红少苔；胃阴不足项描述的是口干咽燥、舌红少苔；脾阳亏虚项见畏寒便溏、腹痛喜温；胃火亢盛项见牙龈红肿疼痛、口臭"},{"q":"患者怵惕不安，闭门独处，形体消瘦，甚则二便失禁，宜诊断为","o":["喜伤证","忧伤证","思伤证","惊伤证","恐伤证"],"a":4,"e":"恐伤肾，肾气不固则怵惕不安、闭门独处、二便失禁；肾精耗伤则形体消瘦。喜伤证项实为喜笑不休、心神涣散；忧伤证项描述的是忧愁沮丧、气短乏力；思伤证项见思虑过度、纳呆腹胀；惊伤证项见惊悸怔忡、坐卧不安，均无二便失禁"},{"q":"听声音不包括下列哪项内容","o":["呼吸","肠鸣","耳鸣","语言","咳嗽"],"a":2,"e":"听声音是医生听辨患者发出的呼吸、语言、咳嗽、肠鸣等声响；耳鸣为患者自觉耳内鸣响，属耳窍病变，不属医生听声音范畴。呼吸项、语言项、咳嗽项皆为听声音的常规内容；肠鸣项实为听腹部肠管蠕动之声，亦属听诊内容"},{"q":"患者身热，口渴，面赤，烦躁不宁，月经先期量多，舌红绛，脉弦数，此证为","o":["阴虚证","瘀热互结证","血热证","湿热证","气虚发热证"],"a":2,"e":"热入血分，迫血妄行则月经先期量多；热扰心神则烦躁，身热、口渴、面赤、舌红绛、脉弦数皆里热之象。阴虚证项实为虚热，见潮热盗汗、舌红少苔、经量偏少；瘀热互结项描述的是刺痛、肿块、经色暗红有块；湿热证项见身热不扬、苔黄腻、带下黄稠；气虚发热项见自汗气短、舌淡"},{"q":"患儿，男，12岁，学生。2天前出现发热，恶寒，伴有咳嗽、口微渴、咽痛、小便黄，其舌象表现多为","o":["舌质淡红，苔薄白","舌质红、苔薄黄","舌质淡红，苔黄燥","舌质红，苔黄腻","舌质红绛，苔少"],"a":1,"e":"发热恶寒、咽痛、咳嗽、口微渴、小便黄为风热表证，邪热在表未盛，故舌质红、苔薄黄。淡红苔薄白项实为正常舌或风寒初起；淡红苔黄燥项描述的是里热伤津；红苔黄腻项为湿热内蕴；红绛苔少项为热入营阴或阴虚火旺"},{"q":"患者腹痛灼热，拒按，按之痛甚，伴有腹部硬满者为","o":["鼓胀","气胀","内痈","阳明腑证","阳明经证"],"a":3,"e":"腹痛灼热、拒按、按之痛甚、腹部硬满，为燥屎内结、腑气不通之阳明腑证。鼓胀项实为腹胀大如鼓、皮色苍黄、青筋暴露；气胀项描述的是腹胀叩之空空然、无硬满压痛；内痈项见局部红肿热痛、发热；阳明经证项见大热大汗大渴、脉洪大而无腹满硬痛"},{"q":"患者，女，49岁。平素胸胁胀满疼痛，情志抑郁或烦躁，且出现脘腹胀满，呃逆食少，腹胀便溏等症状，望诊可能的面色为","o":["青黄","红色","白色","黄色","青色"],"a":0,"e":"平素胸胁胀痛、情志抑郁或烦躁为肝气郁结，脘腹胀满、呃逆食少、腹胀便溏为脾失健运，肝郁脾虚之面色为青黄。红色项实主热证，见满面通红；白色项描述的是虚寒，面色㿠白；黄色项主脾虚湿盛，面色萎黄；青色项主肝郁、瘀血、惊风，面青无黄"},{"q":"患者反复鼻中出血，量不多，口燥咽干，鼻干，干咳无痰，五心烦热，潮热盗汗，舌红少苔，脉细数。诊为","o":["肺经风热","胃热炽盛","肝火上逆","阴虚肺燥","脾不统血"],"a":3,"e":"肺阴亏虚，虚火上炎，灼伤鼻络则反复鼻出血；口燥咽干、鼻干、干咳无痰、五心烦热、潮热盗汗、舌红少苔、脉细数皆为阴虚肺燥。肺经风热项实为外感风热，见鼻塞流黄涕、发热咽痛；胃热炽盛项描述的是牙龈肿痛、口臭便秘；肝火上逆项见头痛目赤、急躁易怒；脾不统血项见鼻衄伴面白乏力、舌淡"},{"q":"患者平素易汗出，活动后更甚，伴气短，疲乏，舌淡嫩，脉虚。证属","o":["气虚证","气陷证","气不固证","气逆证","气滞证"],"a":2,"e":"卫气虚弱，不能固密肌表则平素自汗、活动后更甚；气短、疲乏、舌淡嫩、脉虚为气虚，故属气不固证。气虚证项实为气少乏力，以神疲、气短为主而自汗不显；气陷证项描述的是中气下陷，见脱肛、子宫下垂、久泻；气逆证项见咳嗽喘息、呃逆呕吐；气滞证项见胀痛、脉弦"},{"q":"患者头晕目眩，乏力少气，自汗，面色萎黄，心悸多梦，唇甲淡白，舌淡瘦薄，脉细无力。其临床意义是","o":["气虚血瘀证","气滞血瘀证","气血两虚证","气虚证","血虚证"],"a":2,"e":"头晕目眩、乏力少气、自汗为气虚；面色萎黄、心悸多梦、唇甲淡白、舌淡瘦薄、脉细为血虚，二者并见即气血两虚证。气虚血瘀项实为气虚兼瘀，见刺痛固定、舌紫暗；气滞血瘀项描述的是胀痛、肿块、脉弦涩；单纯气虚证项无血虚之象；血虚证项无气短自汗"},{"q":"张某，男，11岁，学生。1个月前出现咳嗽，未予重视。近半月来咳嗽加重，但不吐痰，夜间盗汗，午后低热，咽干微渴，食纳欠佳，大便稍干，其舌象可见","o":["舌质淡红，苔薄白","舌质红，苔黄腻","舌质淡红，苔白腻","舌质红，苔少","舌质红，苔黄燥"],"a":3,"e":"久咳、午后低热、夜间盗汗、咽干微渴、大便稍干为肺阴亏虚之虚热证，阴虚内热故舌质红、苔少。淡红苔薄白项实为正常舌或外感初起；红苔黄腻项描述的是湿热；淡红苔白腻项为寒湿内停；红苔黄燥项为里热伤津、邪热炽盛"},{"q":"神识昏迷而鼾声不绝者，多属","o":["慢性鼻病","睡姿不当","高热神昏","身体肥胖","老年之人"],"a":2,"e":"神识昏迷而鼾声不绝，为热邪内陷心包、痰热壅滞气道之高热神昏，属危重证候。慢性鼻病项实为鼻窍局部病变，神识清楚；睡姿不当项描述的是气道受压而鼾，改变体位即止；身体肥胖项与老年之人项皆可见鼾声，但均无神识昏迷"},{"q":"患者，男，35岁。身热气粗，面红目赤，腹满便秘，口燥咽干，大便干结，小便短赤，苔黄燥，其临床意义是","o":["湿滞脾胃证","湿热积滞肠腑证","阳明燥结证","太阴湿热","热郁胆经"],"a":2,"e":"身热气粗、面红目赤、腹满便秘、大便干结、口燥咽干、小便短赤、苔黄燥，为燥屎内结、腑气不通之阳明燥结证。湿滞脾胃项实为湿困中焦，见脘痞、苔腻、脉濡；湿热积滞肠腑项描述的是下痢脓血、里急后重；太阴湿热项见腹满自利、苔黄腻；热郁胆经项见口苦胁痛、寒热往来"},{"q":"患者，女，42岁。主诉视力减退，伴有爪甲脆折，肢体麻木，关节屈伸不利，月经量少、色淡。面唇淡白，舌淡，脉细。辨证属","o":["肝阴虚证","肝火炽盛证","肝血虚证","肝风内动证","寒滞肝脉证"],"a":2,"e":"肝开窍于目，肝主筋、其华在爪，肝血不足则视力减退、爪甲脆折、肢体麻木、关节屈伸不利、月经量少色淡，面唇淡白、舌淡脉细。肝阴虚证项实为阴亏，见目涩、潮热盗汗、舌红少苔；肝火炽盛项描述的是目赤口苦、便秘尿黄；肝风内动项见震颤抽动；寒滞肝脉项见少腹冷痛"},{"q":"患者神识痴呆，半身不遂，皮肤干燥如鱼鳞，舌有紫色斑点，脉弦细涩，为","o":["血虚证","液脱证","血瘀证","阴虚证","津亏证"],"a":2,"e":"瘀血阻于脑络则神识痴呆、半身不遂；肌肤失于濡养则干燥如鱼鳞；舌有紫色斑点、脉弦细涩皆为血瘀之征。血虚证项实为血液不足，见面白、舌淡、脉细；液脱证项描述的是皮肤干燥、目眶凹陷但无瘀斑；阴虚证项见潮热盗汗、舌红少苔；津亏证项见口干咽燥、舌干"},{"q":"患者大渴喜冷饮，壮热，面赤，汗出，舌红苔黄燥，脉洪数，属","o":["阳明经证（气分热盛）","阳明腑证","消渴病","温病营分证","湿热证"],"a":0,"e":"大渴喜冷饮、壮热、面赤、汗出、脉洪数即气分热盛之四大症，苔黄燥为邪热伤津，属阳明经证。阳明腑证项实为燥屎内结，见腹满硬痛、便秘；消渴病项描述的是多饮多尿多食、形体消瘦、起病缓慢；温病营分证项见身热夜甚、神昏谵语、舌红绛；湿热证项身热不扬、苔黄腻"},{"q":"患者，女，54岁。患者双足浮肿，时间长达1年，近期出现下肢浮肿3个月余，舌胖大，苔白，脉濡。辨证为","o":["痰证","饮证","阴水","阳水","支饮"],"a":2,"e":"浮肿长达一年、下肢肿三月余、舌胖大苔白、脉濡，起病缓、病程长、肿处色白，属阴水。阳水项实为风邪水毒，起病急、上半身先肿、伴表证、脉浮；痰证项描述的是痰多稠黏、苔腻、脉滑；饮证项见水声辘辘、咳吐清稀涎沫；支饮项为饮停胸肺，见咳喘倚息不得卧"},{"q":"患者突然腹部绞痛，弯腰屈背，辗转不宁，冷汗淋漓，恶心呕吐，手足厥冷，多考虑","o":["肠道蛔虫病","胆道蛔虫病","蛔厥证","钩虫病","蛲虫病"],"a":2,"e":"蛔虫扰动，胆腹气机逆乱则突发腹部绞痛、弯腰屈背、辗转不宁；剧痛致阳气暴郁则冷汗淋漓、手足厥冷、恶心呕吐，为蛔厥证。肠道蛔虫病项实为虫积肠中，见脐周腹痛、时作时止；胆道蛔虫病项描述的是剑突下钻顶样剧痛而厥象不著；钩虫病项见面黄虚浮、乏力；蛲虫病项见肛门瘙痒、夜寐不安"},{"q":"患者面色淡白，神疲乏力，气短懒言，食少纳呆；面色晦滞、局部青紫、肿胀、刺痛不移而拒按，舌淡紫有紫斑，脉细涩，其临床意义是","o":["气滞血瘀证","气滞证","气虚血瘀证","血瘀证","血虚证"],"a":2,"e":"面色淡白、神疲乏力、气短懒言、食少纳呆为气虚；面色晦滞、局部青紫肿胀、刺痛不移拒按、舌淡紫有紫斑、脉细涩为血瘀，合为气虚血瘀证。气滞血瘀项实为气滞兼瘀，见胀痛、痞满、脉弦涩而无神疲；气滞证项描述的是胀痛走窜；单纯血瘀证项无气虚象；血虚证项见面白、舌淡、脉细"},{"q":"患者新病耳内流脓，脓液黄稠而量多，伴面红目赤，口苦咽干，大便干燥，小便黄赤，舌质红，苔黄腻，脉弦数。上述症状宜辨证为","o":["肝经火热，热伤血分","脾虚湿困，上犯耳窍","肾虚，虚火上炎","肝胆湿热上蒸","心火炽热，上侵脑髓"],"a":3,"e":"新病耳内流脓、脓黄稠量多，伴面红目赤、口苦咽干、便秘尿赤、舌红苔黄腻、脉弦数，为肝胆湿热循经上蒸耳窍。肝经火热伤血分项实为热入血分，见出血、神昏、舌绛；脾虚湿困上犯耳窍项描述的是脓液清稀、乏力便溏、舌淡苔腻；肾虚虚火上炎项见腰膝酸软、舌红少苔；心火炽盛项见口舌生疮、神昏"},{"q":"患者下肢痿软无力，不能站立，神疲乏力，食少，舌淡嫩，脉弱，属于","o":["气虚证","气陷证","气不固证","血虚证","气逆证"],"a":0,"e":"脾气虚弱，筋脉肌肉失养故下肢痿软无力、不能站立；神疲乏力、食少、舌淡嫩、脉弱皆为气虚。气陷证项实为中气下陷，见脱肛、子宫下垂、久泻；气不固证项描述的是自汗、小便失禁；血虚证项见面色淡白、心悸、舌淡；气逆证项见咳喘、呃逆、呕吐"},{"q":"患者，女，70岁。数年来常感神疲乏力，腹胀便溏。半个月前因劳累再发，现自觉阴道中有物突出，并有下坠感，神疲乏力，气短，头晕目眩，纳少便溏，舌淡苔白，脉缓弱，多属","o":["气虚证","气陷证","气不固证","血虚证","气血两虚证"],"a":1,"e":"中气不足，升举无力则阴道中有物突出、下坠感；神疲乏力、气短、头晕目眩、纳少便溏、舌淡苔白、脉缓弱为气虚下陷，属气陷证。气虚证项实为气少乏力，无下脱之象；气不固证项描述的是自汗、滑脱不禁；血虚证项见面色淡白、唇甲失华；气血两虚证项兼见心悸失眠、舌淡瘦薄"},{"q":"患者惊悸怔忡，健忘失眠，坐卧不安，甚则神志错乱，宜诊断为","o":["喜伤证","忧伤证","思伤证","惊伤证","恐伤证"],"a":3,"e":"惊则气乱，心神失守，故惊悸怔忡、健忘失眠、坐卧不安，甚则神志错乱，属惊伤证。喜伤证项实为喜笑不休、心神涣散；忧伤证项描述的是愁忧沮丧、气短乏力；思伤证项见思虑过度、纳呆腹胀；恐伤证项见恐惧怯懦、二便失司"},{"q":"患者，男，20岁。咳嗽2天。痰稠色黄，伴有发热微恶风寒，鼻塞流浊涕，舌尖红，苔薄黄，辨为风热犯肺证。其脉象最易表现为","o":["浮缓","浮紧","浮数","浮细","浮滑"],"a":2,"e":"风热犯肺，邪在卫表则发热微恶风寒；热邪上扰则舌尖红、苔薄黄，风热之脉当浮数。浮缓项实为太阳中风、风寒表虚；浮紧项描述的是风寒表实、恶寒重；浮细项主血虚或湿邪；浮滑项主风痰或表证夹痰"},{"q":"患者胞睑肿胀，白睛红赤，痒痛兼作，羞明多泪。伴有头痛鼻塞，恶风发热，舌苔薄白或微黄，脉浮数等。此病宜诊断为","o":["肝火上炎","外感风热","脾胃湿热","肝经风热","肺热炽盛"],"a":1,"e":"胞睑肿胀、白睛红赤、痒痛羞明，伴头痛鼻塞、恶风发热、脉浮数，为风热上攻目窍之外感风热证。肝火上炎项实为里热，见目赤肿痛、口苦便秘、脉弦数而无表证；脾胃湿热项描述的是眼睑糜烂、苔黄腻；肝经风热项见目赤痒痛伴胁痛、脉弦数；肺热炽盛项见咳嗽气喘、口渴"},{"q":"患者在临床上表现为肋间饱满，咳唾引痛，胸闷息促，应为","o":["痰饮","悬饮","溢饮","支饮","皮饮"],"a":1,"e":"饮邪停于胸胁，气机阻滞则肋间饱满，咳唾、呼吸牵引作痛，胸闷息促，为悬饮。痰饮项实为饮停胃肠，见脘腹痞满、水声辘辘；溢饮项描述的是饮溢四肢，见肢体肿胀、无汗；支饮项为饮停胸肺，见咳喘倚息不得卧；皮饮项为水饮泛于肌肤，见肢体浮肿"},{"q":"患者，老年男性。体素弱，按诊虚里搏动迟弱，多为","o":["中气不足","心阴亏虚","心阳不足","心血亏虚","心肺气虚"],"a":2,"e":"虚里为宗气外现之处，老年体素弱而搏动迟弱，为心阳不足、宗气不振、推动无力。中气不足项实为脾胃气虚，见纳差便溏、乏力；心阴亏虚项描述的是心悸、舌红少苔、脉细数；心血亏虚项见心悸失眠、面色淡白；心肺气虚项见咳喘心悸、气短乏力"},{"q":"患者反复咳喘7年，叩诊肺下界下移，可见于","o":["肺痨","肺痿","肺痈","肺胀","肺热"],"a":3,"e":"反复咳喘七年，肺气胀满不收，气道阻塞，胸廓呈桶状，叩诊肺下界下移，为肺胀。肺痨项实为痨虫蚀肺，见咳嗽咯血、潮热盗汗、形体消瘦；肺痿项描述的是咳吐浊唾涎沫、气短；肺痈项见发热胸痛、咳吐腥臭脓痰；肺热项为实热新病，病程短"},{"q":"患者女，乳房有大小不一的肿块，边界不清，质地不硬，活动度好，每次月经前疼痛，多为","o":["乳痈","乳痨","乳癖","乳癌","乳疬"],"a":2,"e":"乳房肿块大小不一、边界不清、质地不硬、活动度好且经前疼痛，随月经周期变化，为乳癖，多因肝郁痰凝、冲任失调。乳痈项实为急性化脓性乳腺炎，见红肿热痛、发热；乳痨项描述的是乳房肿块、溃后流脓、形体消瘦；乳癌项见肿块质硬、活动差、橘皮样变；乳疬项见于儿童或老年男性乳晕下"},{"q":"患者，男，19岁。患者今晨猝然昏倒，四肢抽搐，两目上视，口吐白沫，口中发出如猪羊叫声，3~5分钟后苏醒，醒后一如常人。属于","o":["中风","癫病","痫病","狂病","郁病"],"a":2,"e":"猝然昏倒、四肢抽搐、两目上视、口吐白沫、作猪羊叫声，数分钟后苏醒且醒后如常，为痫病，因痰浊内蕴、肝风夹痰上扰清窍。中风项实为风痰瘀阻经络，见半身不遂、口眼歪斜，多留后遗症；癫病项描述的是神情抑郁、神志痴呆；狂病项见躁狂叫骂、打人毁物；郁病项见情志抑郁、胸闷太息"},{"q":"患者寒热往来，口苦，咽干，目眩，舌淡红，脉弦细，诊断为少阳病，其中寒热往来，口苦，咽干，目眩，属于具备诊断的","o":["必要性资料","特征性资料","偶见性资料","一般性资料","否定性资料"],"a":1,"e":"寒热往来、口苦、咽干、目眩为少阳病独有的主症群，见到即可诊断少阳病，属特征性资料。必要性资料项实为诊断必须具备的资料；偶见性资料项描述的是出现率低、仅少数病例可见；一般性资料项为常见但无特异性的症状；否定性资料项为排除其他病证的依据"},{"q":"腹痛肠鸣，大便不调，矢气痛减，胁胀窜痛，苔白脉弦，宜诊断为","o":["胃肠气滞证","肝气郁结证","肝胃不和证","肝脾不和证","气机阻滞证"],"a":3,"e":"腹痛肠鸣、大便不调、矢气痛减为脾失健运；胁胀窜痛、苔白脉弦为肝气郁结，肝脾不和则肝郁脾虚并见。胃肠气滞项实为胃肠气机阻滞，见脘腹胀痛、嗳气矢气而无胁胀；肝气郁结项描述的是胁胀太息但无腹痛泄泻；肝胃不和项见胃脘胀痛、嗳气吞酸；气机阻滞项泛指，无定位"},{"q":"患者，男，70岁。目无光彩，面色晦暗，两眼运动呆滞，皮肤枯槁，面色晦暗，见于","o":["失神","少神","得神","假神","神乱"],"a":0,"e":"目无光彩、面色晦暗、两眼运动呆滞、皮肤枯槁为精亏神衰、脏腑功能衰败之失神，提示病情危重。少神项实为精神不振、倦怠乏力但目尚有光；得神项描述的是目光明亮、面色红润、反应灵敏；假神项为久病重病突然精神好转、面红如妆；神乱项见神志错乱、哭笑无常"},{"q":"患者手足厥冷，烦渴喜冷，便干尿赤，舌红苔黄而干，脉洪数有力，证属","o":["阳虚外寒证","真热假寒证","阴虚内热证","表寒里热证","真寒假热证"],"a":1,"e":"手足厥冷为假寒，烦渴喜冷、便干尿赤、舌红苔黄而干、脉洪数有力为里热炽盛之真热，阳盛格阴、热深厥亦深，属真热假寒。阳虚外寒项实为里虚寒，见舌淡苔白、脉沉迟；阴虚内热项描述的是潮热盗汗、舌红少苔；表寒里热项见恶寒无汗、口渴烦躁；真寒假热项见身热反欲盖衣、脉微欲绝"},{"q":"长期咳喘，气短乏力，呼多吸少，自汗耳鸣，舌淡脉弱，应辨证为","o":["脾肺气虚证","肺气虚证","肾气不固证","肺肾气虚证","肾阳虚证"],"a":3,"e":"长期咳喘、气短乏力为肺气虚；呼多吸少、耳鸣、舌淡脉弱为肾不纳气，肺肾两虚、摄纳无权，故属肺肾气虚证。脾肺气虚项实为脾虚生痰，见食少便溏、痰多清稀；肺气虚项描述的是咳喘自汗但无呼多吸少；肾气不固项见遗尿滑精、腰膝酸软；肾阳虚项见畏寒肢冷、水肿"},{"q":"患者，女，39岁。突发高热，神昏，肢厥，神昏谵语，舌质红绛，其临床意义是","o":["上焦病之逆传心包","中焦病之阳明燥结","中焦病之太阴泻热","下焦病之肾阴亏虚","下焦病之肝风内动"],"a":0,"e":"突发高热、神昏谵语、肢厥、舌质红绛，为温病上焦邪热内陷心包之逆传心包。中焦阳明燥结项实为腑实，见腹满便秘、潮热谵语、苔黄燥；中焦太阴泻热项描述的是身热不扬、脘痞便溏、苔黄腻；下焦肾阴亏虚项见身热颧红、舌绛少苔；下焦肝风内动项见抽搐、痉厥"},{"q":"患者，女，43岁。2天前因受凉而出现眼睑水肿，后迅速波及颜面、全身，以上半身水肿更甚，伴有小便短少，恶寒发热，无汗，舌淡红，苔薄白，脉浮紧。辨证为","o":["寒痰阻肺证","风水搏肺证","脾肾阳虚证","心阳不足证","肾虚水泛证"],"a":1,"e":"眼睑水肿迅速波及颜面全身、上半身尤甚，伴小便短少、恶寒发热无汗、脉浮紧，为风邪袭表、肺失宣降、水溢肌肤之风水搏肺证。寒痰阻肺项实为寒痰蕴肺，见咳嗽痰多清稀、胸闷；脾肾阳虚项水肿起病缓、下半身甚、畏寒肢冷；心阳不足项见心悸唇紫；肾虚水泛项见腰以下肿甚、腰膝酸软"},{"q":"患者，男，52岁。面目一身俱黄，色黄晦暗如烟熏，为","o":["萎黄","黄胖","阴黄","阳黄","淡黄"],"a":2,"e":"面目一身俱黄而色黄晦暗如烟熏，为寒湿困脾、胆汁外溢之阴黄。萎黄项实为面色萎黄无华而目睛不黄；黄胖项描述的是面色黄而虚浮、目睛不黄；阳黄项色黄鲜明如橘皮，伴发热口渴、苔黄腻；淡黄项非规范辨证名，多属虚黄范畴"},{"q":"患者，女，30岁。恶寒发热3天，昨日伴轻微咳嗽，痰稀白，量不多，恶寒重发热轻，头痛，鼻塞流清涕，口不渴，舌淡红苔薄白，脉浮紧。其恶寒发热的临床意义是","o":["风热表证","风寒表证","伤风表证","里实寒证","寒邪客肺证"],"a":1,"e":"恶寒重发热轻、咳嗽痰稀白、鼻塞流清涕、口不渴、舌淡红苔薄白、脉浮紧，为风寒束表、肺气失宣之风寒表证。风热表证项实为风热在表，见发热重、咽痛、流浊涕、脉浮数；伤风表证项描述的是恶风汗出、脉浮缓；里实寒证项见腹痛拒按、便秘、脉沉；寒邪客肺项见咳喘痰稀但无恶寒发热"},{"q":"患者，男，6岁。发热、微恶风寒、少汗或无汗，舌边尖红，脉浮数，其辨证为","o":["风热犯卫","暑湿犯卫","风寒犯肺","燥热犯肺","湿热犯卫"],"a":0,"e":"发热、微恶风寒、少汗或无汗、舌边尖红、脉浮数，为风热之邪犯于卫分，卫气失宣，故属风热犯卫。暑湿犯卫项实为暑湿郁表，见身热不扬、头重胸闷、苔腻；风寒犯肺项描述的是恶寒重、痰稀白、脉浮紧；燥热犯肺项见干咳少痰、口鼻干燥；湿热犯卫项见身热不扬、苔黄腻、脉濡数"},{"q":"月经量少，面色萎黄，乏力身倦，食少腹胀，心悸失眠，舌淡。辨证应为","o":["气不摄血证","肝血虚证","脾不统血证","心脾两虚证","心血虚证"],"a":3,"e":"月经量少、面色萎黄、乏力身倦、食少腹胀为脾气虚弱、生化不足；心悸失眠为心血不足，心脾两虚则气血亏少、心神失养。气不摄血项实为气虚不统血，见出血伴气虚但无心悸失眠；肝血虚证项描述的是目涩、爪甲脆、月经量少但无食少腹胀；脾不统血项以出血为主；心血虚证项无脾虚食少"},{"q":"患者，女，67岁。近期胸闷脘痞，呕吐清水，肋间饱满，头晕目眩，苔滑，脉弦，辨证为","o":["亡阳证","水停证","饮证","痰证","津液亏虚"],"a":2,"e":"胸闷脘痞、呕吐清水、肋间饱满、头晕目眩、苔滑、脉弦，为水饮停积于内、气机阻滞之饮证。亡阳证项实为阳气暴脱，见大汗淋漓、四肢厥冷、脉微欲绝；水停证项描述的是水肿、小便不利；痰证项见痰多稠黏、苔腻、脉滑；津液亏虚项见口干咽燥、舌干少津"},{"q":"患者，男，65岁。眩晕，耳鸣如蝉，健忘失眠，胁痛，腰膝酸痛，盗汗，舌红少苔，脉细数。其证候是","o":["肾精不足","肾阴虚","肝阴虚","肝肾阴虚","肝阳上亢"],"a":3,"e":"眩晕耳鸣如蝉、健忘失眠、胁痛为肝阴不足，腰膝酸痛、盗汗、舌红少苔、脉细数为肾阴亏虚，肝肾同源，同病则阴虚火旺。肾精不足项实为精亏，见早衰、耳鸣、腰膝酸软而无胁痛盗汗；肾阴虚项描述的是腰膝酸软、潮热盗汗但无胁痛；肝阴虚项见目涩、胁痛但无腰膝酸软；肝阳上亢项见面红目赤、脉弦劲有力"},{"q":"病人恶寒，脉微细，但欲寐，四肢厥冷，下利清谷，呕不能食，其证属","o":["太阴病证","厥阴病证","少阴热化证","少阴寒化证","阳明病证"],"a":3,"e":"恶寒、脉微细、但欲寐为少阴总纲；四肢厥冷、下利清谷、呕不能食为阳虚阴盛、寒自内生，故属少阴寒化证。太阴病证项实为脾阳虚寒湿，见腹满而吐、食不下、时腹自痛、脉缓弱；厥阴病证项描述的是寒热交错、消渴、气上撞心；少阴热化证项见心烦不得眠、口燥咽干、舌红少苔；阳明病证项见身热汗出、腹满便秘"},{"q":"患者表现为心悸怔忡，喘息不得平卧，心下痞坚，面色黧黑，小便短少，舌质淡苔白滑，脉沉紧是","o":["饮停胸胁证","饮停心包证","饮停胃肠证","寒饮停肺证","饮邪客肺证"],"a":1,"e":"心悸怔忡、心下痞坚为水饮凌心，阳虚水停上逆则喘息不得平卧、面色黧黑、小便短少，舌淡苔白滑、脉沉紧为寒饮之象，属饮停心包证。饮停胸胁项实为悬饮，见胸胁胀满、咳唾引痛；饮停胃肠项描述的是脘腹痞满、水声辘辘、呕吐清水；寒饮停肺项见咳嗽气喘、痰多清稀；饮邪客肺项以咳喘痰鸣为主而无心下痞坚"},{"q":"钱某，男，35岁。平素嗜酒，近半月脘腹胀闷，纳呆，恶心欲呕，口苦，便溏不爽，舌红苔黄腻，脉濡数。诊为","o":["胃热炽盛证","肠热腑实证","湿热蕴脾证","肝胆湿热证","食滞胃脘证"],"a":2,"e":"平素嗜酒，湿热内生，蕴结脾胃则脘腹胀闷、纳呆恶心、口苦、便溏不爽，舌红苔黄腻、脉濡数，为湿热蕴脾证。胃热炽盛项实为胃中实热，见胃脘灼痛、口臭牙龈肿痛；肠热腑实证项描述的是腹满硬痛、潮热便秘；肝胆湿热项见胁痛、口苦、阴痒或黄疸；食滞胃脘项见嗳腐吞酸、泻后痛减"},{"q":"胃脘冷痛喜按，吐清水，口淡不渴，舌淡嫩，脉沉迟无力，应辨证为","o":["寒湿困脾证","脾阳虚证","胃阳虚证","寒滞胃脘证","胃气虚证"],"a":2,"e":"胃脘冷痛喜按、吐清水、口淡不渴、舌淡嫩、脉沉迟无力，为中阳虚衰、胃失温养之胃阳虚证。寒湿困脾项实为湿困中焦，见脘腹痞闷、口腻、苔白腻、脉濡缓；脾阳虚证项描述的是腹胀便溏、畏寒肢冷；寒滞胃脘项见冷痛剧烈、遇寒加重、脉弦紧，属实证；胃气虚证项见隐痛食少、嗳气、脉虚但寒象不显"},{"q":"哮与喘的鉴别要点为","o":["是否呼吸急迫","是否睡能平卧","是否张口抬肩","是否喉间痰鸣","是否发作急骤"],"a":3,"e":"哮以喉间痰鸣、呼吸急促、发作性为特征，喘以呼吸困难、张口抬肩、鼻翼煽动为主，二者鉴别要点在于是否喉间痰鸣，哮必兼喘、喘未必兼哮。呼吸急迫项实为喘的基本表现，哮亦可见；睡能平卧项描述的是病情轻重而非本质；张口抬肩为喘的表现；发作急骤为哮喘共有的发病特点"},{"q":"患者，女，55岁。主诉失眠，伴有胆怯易惊，时有心悸，或烦躁不安，胸胁闷痛，自觉口苦，舌红，苔黄腻，脉弦滑数。辨证属","o":["肝阴虚证","肝火炽盛证","肝胆湿热证","胆郁痰扰证","肝郁气滞证"],"a":3,"e":"胆气郁滞，痰热内生，上扰心神则失眠、胆怯易惊、心悸烦躁，胸胁闷痛、口苦、舌红苔黄腻、脉弦滑数，为胆郁痰扰证。肝阴虚证项实为阴亏内热，见目涩、潮热盗汗、舌红少苔；肝火炽盛项描述的是目赤口苦、便秘尿黄；肝胆湿热项见胁痛、阴痒、苔黄腻；肝郁气滞项见胁胀太息、脉弦但无痰热苔腻"},{"q":"患者，男，72岁。素有心脏病，突觉心胸憋闷疼痛而晕倒，就医时冷汗淋漓，面色苍白，四肢冰凉。其脉象应为","o":["动脉","微脉","革脉","濡脉","弱脉"],"a":1,"e":"心胸憋闷疼痛而晕倒、冷汗淋漓、面色苍白、四肢冰凉，为心阳暴脱、脉气将绝，脉当微细极软、按之欲绝。动脉项实为滑数有力、短如豆，主痛、惊；革脉项描述的是弦急搏指、中空外坚，主失血失精；濡脉项浮细无力，主虚湿；弱脉项沉细无力，主气血不足，皆非阳气暴脱之脉"},{"q":"下列除哪项以外，均是斑与疹的辨证要点","o":["色红或不红","形状的大小","摸之碍手与不碍手","平摊于皮肤下或稍隆起","点大成片与形小如粟"],"a":0,"e":"斑与疹的辨证要点在形态大小、平摊或隆起、摸之碍手与否、点大成片或形小如粟，斑平摊皮下、摸之不碍手，疹形小如粟、高出皮面、摸之碍手。色红或不红项实非辨证要点，因斑疹皆可为红色；其余四项均为斑疹鉴别的常规依据"},{"q":"患者鼻头及鼻翼部色红生有粉刺，常嗜酒，便秘，饮食不节，口干口渴，舌红，苔黄，脉滑。宜辨证为","o":["胃火亢盛","热毒壅盛","肺胃热盛","肺经风热","湿热蕴结"],"a":2,"e":"鼻头鼻翼色红生粉刺，伴嗜酒、便秘、口干口渴、舌红苔黄、脉滑，为肺胃热盛、上熏鼻窍。胃火亢盛项实为胃中实火，见牙龈肿痛、口臭、消谷善饥；热毒壅盛项描述的是局部红肿热痛、发热；肺经风热项见鼻塞流涕、发热咽痛；湿热蕴结项见皮肤油腻、苔黄腻"},{"q":"久病呃逆不止，声低气怯无力，多属","o":["胃气衰败","热邪客胃","寒邪犯胃","偶感风寒","宿食内停"],"a":0,"e":"久病呃逆不止而声低气怯无力，为胃气衰败、正气将绝之危象。热邪客胃项实为胃中实热，见呃逆声高、口渴、苔黄；寒邪犯胃项描述的是呃逆声沉缓、胃脘冷痛、苔白；偶感风寒项见呃逆声高、发作短暂、伴表证；宿食内停项见呃逆酸腐、脘胀、嗳腐吞酸"},{"q":"Page-Frame吕某，男，51岁，军人。2016年7月9日初诊。胸闷，心悸，阵发性心前区刺痛1年，加重3天。1年来反复出现胸闷、心悸，偶有心前区刺痛。3天前因出差返家，旅途乘车劳累，到家用热水洗澡后，胸闷、心悸加重，伴心前区刺痛，经休息后稍缓解。此后因进餐胸闷、心悸复加重，并有阵发性心前区刺痛，向颈肩、左上肢放射，伴有下牙及腹部作痛，舌感麻木，急请医生到家查心电图，提示心肌缺血。平时患有高脂血症。急收入院。查：体胖高大，舌淡胖苔白厚，脉弦滑，血压14/8kPa（105/60mmHg），心律整，心率60次/min……病案中的“1年来反复出现胸闷、心悸……舌感麻木”是","o":["一般情况","主诉","现病史","既往史","个人史"],"a":2,"e":"现病史记述本次疾病的发生、发展、演变与诊治经过，胸闷心悸反复一年、加重三天及发作诱因、放射痛均属之。一般情况项实为姓名、性别、年龄、职业等；主诉项描述的是主要症状及时间，即胸闷心悸、心前区刺痛一年加重三天；既往史项为既往高脂血症；个人史项为生活经历与习惯"},{"q":"下列哪项不属于水痘的痘形特点","o":["椭圆形，肤浅易破","顶部无脐，偶有脐凹","痘粒成对，大小齐等，一起出现","浆薄如水，晶莹明亮","不结厚痂，不留痘痕"],"a":2,"e":"水痘皮疹椭圆形、肤浅易破、顶部无脐或偶有脐凹、浆薄如水、晶莹明亮、不结厚痂、不留痘痕，且分批出现、大小不等。痘粒成对、大小齐等、一起出现项实为天花的痘形特点，非水痘所见；其余四项均为水痘痘形的常规描述"},{"q":"患者腹部膨隆，腹壁青筋暴露，四肢消瘦，面色晦暗，舌青紫，脉涩，多为","o":["水肿","鼓胀","积聚","悬饮","支饮"],"a":1,"e":"腹部膨隆、腹壁青筋暴露、四肢消瘦、面色晦暗、舌青紫、脉涩，为气滞血瘀水停、本虚标实之鼓胀。水肿项实为水湿泛溢肌肤，见全身水肿而腹壁无青筋；积聚项描述的是腹内结块、无腹部膨隆青筋暴露；悬饮项为饮停胸胁，见咳唾引痛；支饮项为饮停胸肺，见咳喘不得卧"},{"q":"患者，女，30岁。入秋后不慎感冒，症见干咳少痰，痰黏难咯，口干咽燥，伴发热恶风寒，舌红苔薄干，脉浮数。其辨证为","o":["肺阴虚证","风热表证","肺热炽盛证","痰热壅肺证","燥邪犯肺证"],"a":4,"e":"入秋感邪、干咳少痰、痰黏难咯、口干咽燥，伴发热恶风寒、舌红苔薄干、脉浮数，为燥邪犯肺、津伤肺燥。肺阴虚证项实为内伤阴虚，见潮热盗汗、舌红少苔但无表证；风热表证项描述的是咽痛、流浊涕、苔薄黄；肺热炽盛项见高热咳喘、口渴便秘；痰热壅肺项见痰黄稠、胸闷、苔黄腻"},{"q":"患者阳强易举，五心烦热，眩晕耳鸣，腰膝酸痛，舌红少苔，宜诊断为","o":["肾气不固证","肾阴虚证","肝肾阴虚证","心肾不交证","肾阳虚证"],"a":1,"e":"肾阴亏虚，相火妄动则阳强易举；五心烦热、眩晕耳鸣、腰膝酸痛、舌红少苔皆为肾阴虚火旺之象。肾气不固项实为肾气亏虚、封藏失职，见遗精滑精、夜尿多、舌淡；肝肾阴虚项描述的是兼见目涩、胁痛；心肾不交项见心烦失眠、心悸、腰膝酸软；肾阳虚项见阳痿、畏寒肢冷、舌淡"},{"q":"心悸怔忡与下列哪项并见，对诊断心肾阳虚证最有意义","o":["食少腹胀、肢肿","心胸憋闷、舌黯","肢体浮肿、形寒","畏寒肢冷","冷汗肢厥"],"a":2,"e":"心肾阳虚以心悸怔忡为本，兼肢体浮肿、形寒者，说明阳虚水泛、温运失职，最具诊断意义。食少腹胀、肢肿项实偏脾肾阳虚，心系症状不显；心胸憋闷、舌黯项描述的是瘀阻心脉；畏寒肢冷项为一般阳虚表现，缺乏特异性；冷汗肢厥项多为亡阳之兆"},{"q":"患者斑疹布点稠密，色现深红或紫黑，并且斑疹先从四肢出现，然后内延胸腹，同时大热不退，神识昏迷，舌红绛，脉数。其属于","o":["斑疹顺症","风疹","湿疹","疔毒走黄","斑疹逆症"],"a":4,"e":"斑疹布点稠密、色深红或紫黑、先从四肢内延胸腹，兼大热不退、神识昏迷、舌红绛、脉数，为热毒深重、内陷心包之斑疹逆症。斑疹顺症项实为分布均匀、色红活、热退神清、由胸腹外达四肢；风疹项描述的是疹色淡红稀疏、瘙痒、伴表证；湿疹项见皮疹多形、渗出、慢性；疔毒走黄项为疔疮毒邪扩散"},{"q":"患者素体阴虚火旺，复感风寒之邪，其舌象可表现为","o":["舌淡苔薄白","舌淡红苔薄白","舌淡苔薄黄","舌绛苔薄黄","舌绛苔薄白"],"a":4,"e":"素体阴虚火旺则舌体红绛，复感风寒之邪、邪在表则苔薄白，故舌象为舌绛苔薄白。舌淡苔薄白项实为正常舌或风寒表证；舌淡红苔薄白项描述的是常人或外感初起；舌淡苔薄黄项为风寒化热；舌绛苔薄黄项为阴虚火旺兼感风热"},{"q":"患者，女，29岁。患者平素喜食偏辣，日久引起口干、咽干、眼睛痒，因此患者除了有内热证以外，还兼有","o":["血瘀","血虚","津亏","血寒","气滞"],"a":2,"e":"平素喜食辛辣，辛热耗伤津液，故口干咽干、眼睛痒，内有热证之外更兼津亏。血瘀项实为血行不畅，见刺痛、舌紫暗、脉涩；血虚项描述的是面色淡白、头晕心悸、舌淡；血寒项见手足冷痛、月经色暗、脉沉迟；气滞项见胀痛、脉弦、太息"},{"q":"患者长期心悸怔忡，心胸憋闷，唇色青紫，气短自汗，畏寒肢冷，面色㿠白，舌淡胖，苔白滑，最不可能出现的脉象是","o":["弦紧","沉迟无力","细微","结代","脉弱"],"a":0,"e":"长期心悸怔忡、心胸憋闷、唇色青紫、气短自汗、畏寒肢冷、面㿠白、舌淡胖苔白滑，为心阳虚弱、水饮内停，可见沉迟无力、细微、结代、脉弱等虚象。弦紧项实为寒邪、痛证、气滞之实证脉，有力而紧张，与本例阳气亏虚、水饮不化之机相悖，最不可能出现"},{"q":"患者发热，其手心较手背热甚者，多为","o":["外感发热","内伤发热","实证发热","气郁发热","瘀血发热"],"a":1,"e":"手心较手背热甚为内伤发热之特征，多因阴阳气血亏虚或气郁、瘀血所致；外感发热则手背热甚于手心。实证发热项实为邪气实，见高热、烦渴、脉洪数；气郁发热项描述的是情志不畅、胸胁胀满、脉弦数；瘀血发热项见午后潮热、肌肤甲错、舌紫暗，均属内伤发热的具体类型"},{"q":"患者，男，40岁。发热，咳嗽，胸闷，心烦口渴，肌肤外发红疹，舌红，苔薄黄，脉数，其病变阶段是","o":["气分","卫分","气营两燔","营分","血分"],"a":2,"e":"发热、咳嗽、胸闷、心烦口渴为气分热盛，肌肤外发红疹、舌红脉数为热入营分，气分营分之热并见，属气营两燔。气分证项实为邪在气分，见大热大汗大渴、苔黄燥而无疹；卫分证项描述的是发热微恶寒、咳嗽、脉浮数；营分证项见身热夜甚、神昏谵语、舌红绛；血分证项见出血发斑、舌深绛"},{"q":"患者阴部湿疹日久，皮肤粗糙变厚，呈苔藓样变，瘙痒难忍，舌红少苔，脉细，多属","o":["阴虚血燥","肝经湿热","带脉失约","冲任虚损","中气下陷"],"a":0,"e":"阴部湿疹日久，阴血耗伤，肌肤失养则皮肤粗糙变厚、呈苔藓样变、瘙痒难忍，舌红少苔、脉细，属阴虚血燥。肝经湿热项实为湿热下注，见阴部瘙痒、渗出、苔黄腻、脉弦数；带脉失约项描述的是带下清稀、腰酸；冲任虚损项见月经不调、不孕；中气下陷项见脱垂、神疲乏力"},{"q":"患者李某，平素大便干燥，状如羊屎，数日一行，伴见口干、口臭，舌红少津，苔黄燥，脉细涩。其辨证为","o":["肺阴虚证","阳明腑实证","肠燥津亏证","虫积肠道证","肺热炽盛证"],"a":2,"e":"大便干燥状如羊屎、数日一行，口干口臭、舌红少津、苔黄燥、脉细涩，为津液亏少、大肠失润之肠燥津亏证。肺阴虚证项实为肺阴不足，见干咳、潮热盗汗；阳明腑实证项描述的是腹满硬痛、潮热谵语、脉沉实；虫积肠道证项见面黄体瘦、排虫；肺热炽盛证项见咳嗽气喘、发热口渴"},{"q":"病人腹满而吐，食不下，自利，时腹自痛，脉缓弱，其证属","o":["太阴病证","阳明腑证","少阳病证","阳明经证","太阳腑证"],"a":0,"e":"腹满而吐、食不下、自利、时腹自痛、脉缓弱，为脾阳不足、寒湿内生之太阴病证。阳明腑证项实为燥屎内结，见腹满硬痛、便秘、潮热；少阳病证项描述的是寒热往来、口苦咽干目眩；阳明经证项见大热大汗大渴、脉洪大；太阳腑证项见小便不利或少腹硬满"},{"q":"患者，男，60岁。主诉眩晕，伴有头不自主摇动，言语謇涩，手足麻木，肢体震颤，步履不正，舌红，脉弦细。辨证属","o":["肝阴虚证","肝火炽盛证","肝胆湿热证","肝阳上亢证","肝风内动证"],"a":4,"e":"眩晕、头不自主摇动、言语謇涩、手足麻木、肢体震颤、步履不正、舌红脉弦细，为肝阳或阴虚化风、筋脉失养之肝风内动证。肝阴虚证项实为阴亏，见目涩、潮热盗汗而无震颤摇动；肝火炽盛项描述的是目赤口苦、便秘尿黄；肝胆湿热项见口苦、胁痛、苔黄腻；肝阳上亢项见头目胀痛、面红目赤但风象不显"},{"q":"男，25岁。感冒3天，今出现壮热，烦渴，咳嗽，痰黄稠量多，息促胸痛，小便短赤，舌红苔黄腻，脉滑数。属于","o":["热痰","燥痰","湿痰","风痰","寒痰"],"a":0,"e":"壮热烦渴、咳嗽痰黄稠量多、息促胸痛、小便短赤、舌红苔黄腻、脉滑数，为痰与热结、壅滞于肺之热痰。燥痰项实为燥邪伤津，见痰少而黏、难咯、口鼻干燥；湿痰项描述的是痰多色白、胸闷、苔白腻；风痰项见痰多泡沫、伴表证、脉浮滑；寒痰项见痰稀白、畏寒、舌淡苔白"},{"q":"患者胸闷心悸，息促不得卧，身体、肢节疼重，咳吐清稀痰涎，喉间哮鸣有声，头目眩晕，舌苔白滑，脉弦。其临床意义是","o":["饮证","痰证","阴水证","阳水证","水停证"],"a":0,"e":"胸闷心悸、息促不得卧、咳吐清稀痰涎、喉间哮鸣、身体肢节疼重、头目眩晕、舌苔白滑、脉弦，为水饮泛溢、上逆犯心肺之饮证。痰证项实为痰稠、苔腻、脉滑；阴水证项描述的是水肿、按之没指、舌淡胖；阳水证项水肿起病急、上半身甚、脉浮；水停证项以水肿、小便不利为主"},{"q":"汗出腥膻，不属于","o":["风温","风湿久蕴","汗后衣物不洁","瘟疫","湿温"],"a":3,"e":"汗出腥膻多因风湿热邪久蕴肌肤，或汗后衣物不洁，湿温、风温等温病过程中亦可见，皆与湿郁化热有关。瘟疫项实为疫毒疠气所致，见高热、神昏、发斑、传染性强，不以汗出腥膻为特征；风湿久蕴项、汗后衣物不洁项、湿温项均为汗出腥膻的常见原因"},{"q":"患者出现舌质红绛，苔白滑腻，多属于","o":["邪热充斥，气营两燔","营分有热，气分有湿","热入营血，气阴俱伤","气阴两虚，痰湿内蕴","痰食停滞，郁久化热"],"a":1,"e":"舌质红绛提示营分有热，苔白滑腻提示气分有湿，合为营分有热、气分有湿。邪热充斥气营两燔项实为舌红绛而苔黄燥；热入营血气阴俱伤项描述的是舌红绛少苔或光剥；气阴两虚痰湿内蕴项见舌淡红少苔而苔腻；痰食停滞郁久化热项见舌红苔黄腻厚"},{"q":"病人下午潮热、便秘、腹满而痛、脉沉实，其证属","o":["阳明腑证","阳明经证","太阳腑证","少阳腑证","少阳经证"],"a":0,"e":"下午潮热、便秘、腹满而痛、脉沉实，为燥屎内结、腑气不通之阳明腑证。阳明经证项实为气分热盛，见大热大汗大渴、脉洪大而无腹满便秘；太阳腑证项描述的是小便不利或少腹硬满；少阳腑证项见口苦、胁痛、小便不利；少阳经证项见寒热往来、口苦咽干目眩"},{"q":"患者腹痛，时作时止，多食易饥，面色萎黄而虚浮，下肢水肿，多考虑","o":["肠道蛔虫病","胆道蛔虫病","蛔厥证","钩虫病","蛲虫病"],"a":3,"e":"腹痛时作时止、多食易饥而面色萎黄虚浮、下肢水肿，为钩虫吸食血液、气血亏虚、水湿泛溢之钩虫病，又称黄胖病。肠道蛔虫病项实为虫积肠中，见脐周痛、可触及虫团；胆道蛔虫病项描述的是剑突下钻顶样剧痛；蛔厥证项见腹痛剧烈、手足厥冷；蛲虫病项见肛门瘙痒、夜寐不安"},{"q":"久泄，畏寒肢冷，下腹冷痛，舌淡胖，苔白滑，脉沉细，宜诊断为","o":["寒湿困脾证","肾阳虚证","肾气不固证","脾肾阳虚证","脾阳虚证"],"a":3,"e":"久泄、畏寒肢冷、下腹冷痛、舌淡胖苔白滑、脉沉细，为脾肾阳虚、命门火衰、脾失温运。寒湿困脾证项实为寒湿中阻，见脘腹痞闷、口腻、苔白腻、脉濡缓；肾阳虚证项描述的是腰膝酸软、夜尿多、水肿而泄泻不著；肾气不固证项见遗尿滑精；脾阳虚证项见腹胀便溏而无明显下腹冷痛"},{"q":"患者出现恶寒发热，头痛，咳嗽，咽喉肿痛，大便溏泄，小便清长。证属","o":["上热下寒","真寒假热","表热里寒","表寒里热","真热假寒"],"a":2,"e":"恶寒发热、头痛、咳嗽、咽喉肿痛为表热；大便溏泄、小便清长为里寒，表里寒热错杂，属表热里寒证。上热下寒项实为上部热、下部寒但无表证发热恶寒；真寒假热项描述的是身热反欲盖衣、脉微欲绝；表寒里热项见恶寒重、无汗、口渴便秘；真热假寒项见手足厥冷、烦渴喜冷、脉洪数有力"},{"q":"患者早泄，耳鸣腰酸，烦热咽干，舌红少苔，宜诊断为","o":["肝肾阴虚证","心肾不交证","肾气不固证","肾精不足证","肾阴虚证"],"a":4,"e":"早泄、耳鸣腰酸、烦热咽干、舌红少苔，为肾阴亏虚、相火妄动、精关不固。肝肾阴虚证项实为兼见目涩、胁痛；心肾不交证项描述的是心烦失眠、心悸、腰膝酸软；肾气不固证项见遗精滑精、夜尿多、腰膝酸软但无烦热咽干、舌红少苔；肾精不足证项见早衰、耳鸣、舌淡"},{"q":"患者恶寒发热伴咳嗽3天，今起但发热不恶寒，咳嗽，痰多黄稠，面赤，舌红，脉滑数。从恶寒发热伴咳嗽3天，知其为新感，病在肺系；今发热不恶寒，面赤，舌红，脉滑数，知其表证已除，入里化热；同时痰多黄稠，脉滑数为痰热的表现，故本证为痰热壅肺。此例运用的中医诊断基本思维方法是","o":["类比法","分类法","归纳法","演绎法","反证法"],"a":3,"e":"本例由新感、病在肺系、表证入里化热、痰热内蕴等一般理论，逐步推出本证为痰热壅肺的个别结论，属由一般到个别的演绎法。类比法项实为同类证候相互比较推演；分类法项描述的是按属性归类；归纳法项为由个别事例概括一般规律；反证法项通过否定对立面以确立结论"},{"q":"患者，男，44岁。主诉睾丸冷痛，牵引少腹坠胀作痛，遇冷则阴器收缩引痛，得温痛减，平素畏寒喜暖，肢冷不温，舌淡苔白，脉弦紧。辨证属","o":["肝阴虚证","肝火炽盛证","肝胆湿热证","肝阳上亢证","寒滞肝脉证"],"a":4,"e":"睾丸冷痛、牵引少腹坠胀、遇冷则阴器收缩引痛、得温痛减，伴畏寒喜暖、肢冷、舌淡苔白、脉弦紧，为寒邪凝滞肝经之寒滞肝脉证。肝阴虚证项实为阴亏内热，见目涩、潮热盗汗、舌红少苔；肝火炽盛项描述的是目赤口苦、便秘尿黄；肝胆湿热项见阴部潮湿瘙痒、口苦、苔黄腻；肝阳上亢项见头目胀痛、面红目赤"},{"q":"口出酸腐气，伴脘腹胀满者，多属","o":["龋齿","胃热","伤食","胃病","牙疳"],"a":2,"e":"口出酸腐气、脘腹胀满，为食积胃肠、腐浊之气上泛之伤食。龋齿项实为牙齿蛀蚀缺损、牙痛；胃热项描述的是口臭、牙龈肿痛、口渴；胃病项见胃脘疼痛、嗳气、纳差而无酸腐口气；牙疳项为牙龈腐烂、口气臭秽难闻"},{"q":"患者咽喉疼痛剧烈2日，伴有吞咽困难，检查见咽部及喉核红肿，压痛。伴见高热，口干喜饮，头痛，咳痰黄稠，大便秘结，小便黄，舌红苔黄，脉数有力。此病多辨证为","o":["肺肾阴虚","痰火壅结","肺胃热盛","痰湿凝聚","风热袭肺"],"a":2,"e":"咽喉疼痛剧烈、吞咽困难、咽部及喉核红肿压痛，伴高热、口干喜饮、咳痰黄稠、便秘尿黄、舌红苔黄、脉数有力，为肺胃热盛、热毒上攻咽喉。肺肾阴虚项实为虚火上炎，见咽喉干痛、潮热盗汗、舌红少苔；痰火壅结项描述的是咽喉肿痛、痰多黄稠、胸闷、苔黄腻；痰湿凝聚项见咽中不利、痰白黏、苔白腻；风热袭肺项病情较轻、伴表证"},{"q":"患者突发耳鸣耳痛，耳内流脓，脓出耳痛减缓。伴见口苦咽干，小便黄赤，大便秘结，舌红苔黄，脉弦数。多辨证为","o":["肝胆火旺","邪热外侵","脾虚湿困","肾精亏损","痰火壅结"],"a":0,"e":"突发耳鸣耳痛、耳内流脓、脓出痛减，伴口苦咽干、小便黄赤、便秘、舌红苔黄、脉弦数，为肝胆火旺、循经上扰耳窍。邪热外侵项实为外感风热，见发热恶寒、耳痛、脉浮数；脾虚湿困项描述的是脓液清稀、乏力便溏、舌淡苔腻；肾精亏损项见耳鸣如蝉、腰膝酸软、舌淡；痰火壅结项见耳内流脓、胸闷、苔黄腻、脉滑数"},{"q":"患者，女，7岁。因患感冒后突然症状加重，发热，头痛，神昏谵语，西医诊断为病毒性脑膜炎，指纹透关射甲，舌淡红，苔白，脉细则提示","o":["邪气入络","邪气入经","邪入脏腑，病情较重","病情凶险，预后不良","风寒表证"],"a":3,"e":"小儿指纹由风关、气关、命关依次透达，透关射甲为指纹直达指甲端，提示邪热内陷、病情凶险、预后不良。邪气入络项实为指纹显于风关，病轻邪浅；邪气入经项描述的是指纹达气关，病邪深入；邪入脏腑项为指纹达命关，病情较重；风寒表证项见指纹浮红、多在风关"},{"q":"田某，女， 53岁，平素性情急躁易怒。自述近半个月来自觉口苦口干，烦躁失眠，胁痛灼热，小便短黄，大便干结，舌红苔黄，脉弦救。其口苦口干的病机为","o":["肝气郁结","肝胃不和","肝胆火旺","燥热伤津","肝胆湿热"],"a":2,"e":"平素急躁易怒，肝胆火旺，火热上炎则口苦口干、胁痛灼热；火扰心神则烦躁失眠，小便短黄、大便干结、舌红苔黄、脉弦数皆为实火之象。肝气郁结项实为气机郁滞，见胁胀太息、脉弦而无灼热、口苦、便秘；肝胃不和项描述的是胃脘胀痛、嗳气吞酸；燥热伤津项见口干咽燥、干咳、舌红少津而无胁痛；肝胆湿热项见苔黄腻、阴痒"},{"q":"病人咳嗽痰少，偶见痰中带血，腰膝酸软，遗精，五心烦热，盗汗颧红，舌红少苔，脉细数。宜辨证为","o":["肺阴亏虚证","肾阴虚证","肺肾气虚证","心阴虚证","肺肾阴虚证"],"a":4,"e":"咳嗽痰少、痰中带血为肺阴亏虚、虚火灼络；腰膝酸软、遗精、五心烦热、盗汗颧红、舌红少苔、脉细数为肾阴虚，金水相生，肺肾同病即肺肾阴虚证。肺阴亏虚证项实为仅有肺系阴虚，见干咳潮热而无腰酸遗精；肾阴虚证项描述的是腰膝酸软、潮热盗汗而无咳血；肺肾气虚证项见咳喘、呼多吸少；心阴虚证项见心悸失眠"},{"q":"患者，男，59岁。自述肠鸣腹泻2年。近1周来，站立行走或以手按抚，肠鸣辘辘下行，脘腹痞满，舌胖苔白腻，脉沉弦。属于","o":["胃肠虚寒","痰饮停胃","寒客胃肠","肝脾不调","肠道气滞"],"a":1,"e":"肠鸣腹泻两年，站立行走或按压时肠鸣辘辘下行、脘腹痞满、舌胖苔白腻、脉沉弦，为水饮停于胃肠、走于肠间之痰饮停胃。胃肠虚寒项实为脾胃虚寒，见腹痛喜温喜按、便溏、舌淡苔白；寒客胃肠项描述的是腹痛暴作、泻下清稀、苔白；肝脾不调项见腹痛即泻、泻后痛减、脉弦；肠道气滞项见腹胀、矢气则舒"},{"q":"呵欠频频不止，多属","o":["肝气郁结","体虚阳衰","风寒外束","阳气回复","宗气大虚"],"a":1,"e":"呵欠为肾气不足、阳气虚衰、精神疲惫之象，频频不止多属体虚阳衰。肝气郁结项实为气机郁滞，见胁胀、善太息；风寒外束项描述的是恶寒发热、无汗、头身痛；阳气回复项为病情向愈、精神渐振，非频频呵欠；宗气大虚项见气短不足以息、语言低微、心悸"},{"q":"患者素体痰盛，近来因情志不遂，出现头晕胀痛，面红目赤，口苦，耳内流脓，小便黄，大便不调，考虑为肝火夹痰，最可能出现的脉象是","o":["弦细涩脉","弦长细脉","弦滑数脉","弦紧实脉","弦细数脉"],"a":2,"e":"弦脉主肝，滑脉主痰，数脉主热，肝火夹痰则脉弦滑数。弦细涩脉项实为肝郁血瘀，见胁痛、舌暗；弦长细脉项描述的是肝气郁滞、气机不畅；弦紧实脉项为寒邪、痛证、实证；弦细数脉项为肝肾阴虚火旺或肝郁血虚，均非痰火并见之脉"},{"q":"患者脘腹疼痛，肠鸣腹泻，呕吐，舌淡苔白，脉沉紧，宜诊断为","o":["风淫证","寒淫证","暑淫证","燥淫证","湿淫证"],"a":1,"e":"脘腹疼痛、肠鸣腹泻、呕吐、舌淡苔白、脉沉紧，为寒邪直中脾胃、阳气受损、运化失常之寒淫证。风淫证项实为风邪袭表，见发热恶风、汗出、脉浮缓、肢体麻木；暑淫证项描述的是发热口渴、乏力、苔黄腻、脉濡数；燥淫证项见口鼻干燥、干咳少痰、舌干；湿淫证项见头重如裹、肢体困重、苔白腻、脉濡"},{"q":"患者胸胁胀闷疼痛，胸廓饱满，两肋叩击音实而浊，多为","o":["悬饮","支饮","痰饮","溢饮","水湿"],"a":0,"e":"胸胁胀闷疼痛、胸廓饱满、两肋叩击音实而浊，为饮邪停于胸胁、气机阻滞之悬饮。支饮项实为饮停胸肺，见咳喘倚息不得卧、痰多清稀；痰饮项描述的是饮停胃肠，见脘痞、水声辘辘；溢饮项为饮溢四肢，见肢体肿胀、无汗；水湿项泛指水湿内停，多见水肿、苔腻"},{"q":"患者，女，32岁。外出旅游途中突发腹痛泄泻，大便呈水样，日泻5～6次，泻前肠鸣辘辘，伴见形寒肢冷，口淡不渴，脘腹痞闷，纳呆，四肢酸困重。经补液及抗菌治疗，未见明显改善，舌体胖，苔白腻，脉沉细。其泄泻的病机为","o":["食滞胃肠","脾肾阳虚","寒湿困脾","脾胃虚寒","寒邪犯胃"],"a":2,"e":"水样泄泻、泻前肠鸣辘辘、形寒肢冷、口淡不渴、脘腹痞闷、纳呆、四肢酸困重、舌胖苔白腻、脉沉细，为寒湿困脾、运化失司。食滞胃肠项实为食积，见嗳腐吞酸、泻后痛减；脾肾阳虚项描述的是五更泄泻、腰膝酸软；脾胃虚寒项见腹痛喜温喜按、病程较长；寒邪犯胃项见胃脘冷痛、呕吐清水而无泄泻、肢重"},{"q":"语言粗鲁，狂妄叫骂，哭笑无常者属","o":["心气不足","心神大伤","痰浊闭窍","痰火扰心","痰蒙心神"],"a":3,"e":"语言粗鲁、狂妄叫骂、哭笑无常为痰郁化火、上扰心神之痰火扰心，属阳狂。心气不足项实为心气亏虚，见语言低微、气短乏力；心神大伤项描述的是精神恍惚、悲伤欲哭；痰浊闭窍项见神志昏迷、喉中痰鸣、静而少动；痰蒙心神项见神志痴呆、表情淡漠、喃喃自语"},{"q":"若患者舌质红绛而有裂纹，舌苔焦黄干燥，其病多主","o":["痰热内蕴","热极津伤","阴虚内热","湿浊化热","痰湿内停"],"a":1,"e":"舌质红绛而有裂纹、苔焦黄干燥，为里热炽盛、津液大伤之热极津伤。痰热内蕴项实为痰与热结，见舌红苔黄腻；阴虚内热项描述的是舌红少苔或裂纹但苔不焦黄；湿浊化热项见苔黄腻、舌红而无裂纹；痰湿内停项见舌淡胖、苔白腻"},{"q":"突然昏倒，口眼歪斜，半身不遂，语言不利，面赤，脉弦劲有力，应辨证为","o":["肝阳上亢证","热极生风证","肝阳化风证","阴虚动风证","痰热扰心证"],"a":2,"e":"突然昏倒、口眼歪斜、半身不遂、语言不利、面赤、脉弦劲有力，为肝阳上亢、化风上扰、风痰阻络之肝阳化风证。肝阳上亢项实为阳亢无风，见眩晕头胀、面红目赤但无昏倒偏瘫；热极生风项描述的是高热、抽搐、神昏、舌红绛；阴虚动风项见手足蠕动、潮热盗汗、舌红少苔；痰热扰心项见神昏谵语、痰多、苔黄腻"},{"q":"患者突感左胸前区刺痛，痛引左上臂内侧，面色略黯，脉弦涩。证属","o":["气滞证","气逆证","气闭证","血瘀证","血热证"],"a":3,"e":"左胸前区刺痛、痛引左上臂内侧、面色略黯、脉弦涩，为瘀血阻于心脉、不通则痛之血瘀证。气滞证项实为气机郁滞，见胀痛走窜、脉弦；气逆证项描述的是咳嗽喘息、呃逆呕吐；气闭证项见突然昏厥、牙关紧闭、二便不通；血热证项见出血、心烦、舌红绛、脉数"},{"q":"患者鼻涕黄浊黏稠如脓样，量多，有臭味。兼见头痛，发热，口苦咽干，急躁易怒，舌红苔黄，脉弦数。多辨证为","o":["肺经风热","胆腑郁热","脾胃湿热","肺气虚弱","脾气虚弱"],"a":1,"e":"鼻涕黄浊黏稠如脓、量多有臭味，伴头痛、发热、口苦咽干、急躁易怒、舌红苔黄、脉弦数，为胆腑郁热、上移于脑之鼻渊。肺经风热项实为外感风热，见鼻塞流黄涕、发热咽痛、脉浮数而无口苦急躁；脾胃湿热项描述的是鼻涕黄稠、脘痞、苔黄腻；肺气虚弱项见鼻塞清涕、气短自汗；脾气虚弱项见鼻塞、便溏、乏力、舌淡"},{"q":"干咳无痰或痰少而黏证属","o":["风热犯肺","燥邪犯肺","热邪犯肺","痰湿阻肺","肺气亏虚"],"a":1,"e":"燥邪伤肺，津液受损，肺气上逆则干咳无痰或痰少而黏，属燥邪犯肺。风热犯肺项实为风热袭肺，见咳嗽痰黄、咽痛、脉浮数；热邪犯肺项描述的是咳嗽气喘、痰黄稠、发热口渴；痰湿阻肺项见咳嗽痰多色白、胸闷、苔白腻；肺气亏虚项见咳喘无力、气短、痰清稀"},{"q":"患者头目胀痛，面红目赤，自觉气冲胸满，甚则呕逆吐血，宜诊断为","o":["喜伤证","怒伤证","思伤证","惊伤证","恐伤证"],"a":1,"e":"怒则气上，肝气上逆，血随气涌于上则头目胀痛、面红目赤、自觉气冲胸满，甚则呕逆吐血，属怒伤证。喜伤证项实为喜笑不休、心神涣散；思伤证项描述的是思虑过度、纳呆腹胀；惊伤证项见惊悸怔忡、坐卧不安；恐伤证项见恐惧怯懦、二便失禁"},{"q":"张某，女，63岁。两年来常感两目干涩不适，时痛时止，伴有口干夜甚，手足心热。查体：形体消瘦、两颧潮红，舌红少津，脉弦细数。该病人目涩的病机是","o":["肝经风热","肝血虚亏","肝阳上亢","肝火上炎","肝肾阴亏"],"a":4,"e":"两目干涩不适、时痛时止，伴口干夜甚、手足心热、形体消瘦、两颧潮红、舌红少津、脉弦细数，为肝肾阴亏、目失濡养。肝经风热项实为风热上扰，见目赤痒痛、流泪、脉浮数；肝血虚亏项描述的是目涩、视物模糊、面色淡白、舌淡；肝阳上亢项见头目胀痛、面红目赤；肝火上炎项见目赤肿痛、口苦便秘、脉弦数"},{"q":"患者因过服温燥药物所致火热耗津，舌象多为","o":["淡红舌","腻苔","腐苔","燥苔","润苔"],"a":3,"e":"过服温燥药物，火热内盛、耗伤津液，舌面失润则见燥苔，扪之粗糙少津。淡红舌项实为正常舌象；腻苔项描述的是湿浊、痰食内蕴，苔腻而滑；腐苔项为食积、痰浊，苔厚如豆腐渣；润苔项为津液未伤、舌面润泽"},{"q":"患者，女，36岁。因工作压力过大，不思饮食，胸脘痞闷，水声辘辘，纳呆，恶心，辨证为","o":["阴虚火旺证","水停证","痰证","饮证","血瘀证"],"a":3,"e":"不思饮食、胸脘痞闷、水声辘辘、纳呆、恶心，为水饮停于胃肠、胃气上逆之饮证。阴虚火旺证项实为阴虚内热，见潮热盗汗、舌红少苔而无漉漉水声；水停证项描述的是水肿、小便不利；痰证项见痰多稠黏、苔腻、脉滑；血瘀证项见刺痛、舌紫暗、脉涩"},{"q":"患者，女，35岁。症见恶寒，身热不扬，头重如裹，肢体困重，胸闷脘痞，口黏不渴，舌苔白腻，脉濡数，其辨证为","o":["湿热犯卫","暑湿犯卫","燥热犯肺","热郁胆经","风热犯卫"],"a":0,"e":"恶寒、身热不扬、头重如裹、肢体困重、胸闷脘痞、口黏不渴、苔白腻、脉濡数，为湿重于热、郁遏卫表之湿热犯卫证。暑湿犯卫项实为夏季暑湿，见身热心烦、口渴乏力、苔腻；燥热犯肺项描述的是干咳少痰、口鼻干燥；热郁胆经项见口苦、胁痛、寒热往来；风热犯卫项见发热重、咽痛、脉浮数、苔薄黄"},{"q":"患者，女，51岁。持续低热，暮热早凉，五心烦热，口干咽燥，舌干少苔，脉虚细，偶有手足蠕动，其辨证为","o":["血分虚热","血分实热","营阴受损","热入心包","热郁胆经"],"a":0,"e":"持续低热、暮热早凉、五心烦热、口干咽燥、舌干少苔、脉虚细，为温病后期阴液亏损、虚热内生；手足蠕动为虚风内动，属血分虚热。血分实热项实为热毒炽盛，见高热、神昏、发斑出血、舌深绛；营阴受损项描述的是身热夜甚、神昏谵语、舌红绛；热入心包项见神昏谵语、肢厥；热郁胆经项见口苦、胁痛、寒热往来"},{"q":"患者手足疼痛发凉、肤色紫黯，得温痛减，喜暖恶寒，月经愆期，经色紫黯，脉沉迟而涩，诊断为","o":["血瘀证","血寒证","气滞血瘀证","血虚证","气虚证"],"a":1,"e":"手足疼痛发凉、肤色紫黯、得温痛减、喜暖恶寒、月经愆期、经色紫黯、脉沉迟而涩，为寒邪客于血脉、血行不畅之血寒证。血瘀证项实为瘀血内停，见刺痛固定、肿块、舌紫暗但寒象不显；气滞血瘀项描述的是胀痛、情志相关；血虚证项见面色淡白、头晕心悸、舌淡；气虚证项见气短乏力、自汗、脉虚"},{"q":"患者，女，70岁。精神萎靡，意识模糊，目暗睛迷，面色晦暗无华，表情淡漠，可判断病人为","o":["得神","少神","失神","假神","神乱"],"a":2,"e":"精神萎靡、意识模糊、目暗睛迷、面色晦暗无华、表情淡漠，为精亏神衰、脏腑功能衰败之失神。得神项实为目光明亮、神志清楚、反应灵敏；少神项描述的是精神不振、倦怠乏力但意识清楚、目尚有光；假神项为久病突然精神转佳、面红如妆、欲进饮食；神乱项见神志错乱、哭笑无常、躁动不安"},{"q":"病人发热恶寒无汗、足冷、脉反沉，其证属","o":["少阴兼阳明病证","少阴兼太阳病证","少阳兼太阳病证","少阳病证","少阴病证"],"a":1,"e":"发热恶寒无汗为太阳表实证；足冷、脉反沉为少阴阳虚、寒邪内侵，表里同病，属少阴兼太阳病证。少阴兼阳明项实为阳虚兼腑实，见腹满便秘、发热、脉沉；少阳兼太阳项描述的是寒热往来、口苦、肢节疼痛；少阳病证项见寒热往来、口苦咽干目眩；单纯少阴病证项见脉微细、但欲寐而无发热恶寒无汗"},{"q":"患者，女，49岁。壮热烦渴，头痛如劈，烦躁不安，肌肤发斑，吐血衄血，舌绛苔黄，其病变属于","o":["气分证","营分证","血分证","气血两燔","气营血同病"],"a":4,"e":"壮热烦渴、头痛如劈为气分热盛；烦躁不安、肌肤发斑为热入营血；吐血衄血、舌绛苔黄为血分热盛，气营血三者同病。气分证项实为邪在气分，见大热大汗大渴、苔黄燥而无发斑出血；营分证项描述的是身热夜甚、神昏谵语、舌红绛；血分证项见发斑出血、舌深绛但无壮热烦渴、苔黄；气血两燔项无神昏、舌绛等营分表现"},{"q":"患者，女，40岁。1周前因情志不遂而出现胸胁胀痛，胃脘痞满，时欲太息，呃逆嗳气，纳食减少，舌苔薄白，脉弦。其脘痞的病机是","o":["肝气郁滞","肝火犯胃","寒凝胃脘","气滞胃脘","饮停胃脘"],"a":3,"e":"胸胁胀痛、胃脘痞满、时欲太息、呃逆嗳气、纳食减少、苔薄白、脉弦，为肝气郁结、横逆犯胃、胃气阻滞之的气滞胃脘。肝气郁滞项实为肝气郁于本经，见胁胀太息但无胃脘痞满、呃逆；肝火犯胃项描述的是胃脘灼痛、口苦、嘈杂吞酸、脉弦数；寒凝胃脘项见冷痛、遇寒加重、舌淡苔白；饮停胃脘项见水声辘辘、呕吐清水、苔滑"},{"q":"久病体虚之人出现嗳气的特点是","o":["嗳气频作兼见脘痛","嗳气频作声音响亮","嗳气低沉断续兼纳呆","嗳气酸腐兼脘胀","饱食之后偶尔嗳气"],"a":2,"e":"久病体虚，胃气虚弱，胃气上逆无力，故嗳气低沉断续并伴纳呆。嗳气频作兼脘痛项实为寒邪或食积犯胃；嗳气频作声音响亮项描述的是实证、气滞；嗳气酸腐兼脘胀项为食积胃肠，腐浊上泛；饱食之后偶尔嗳气项为正常生理现象，不属病态"},{"q":"患者，女，79岁。卧床多年，本不能食，突然食欲大增，精神好转，想见亲人，病机为","o":["气血不足","阴阳失调","虚阳外越","脏腑虚弱","阳气亏虚"],"a":2,"e":"卧床多年、本不能食，突然食欲大增、精神好转、想见亲人，为假神，是虚阳外越、残阳欲脱之回光返照。气血不足项实为气血亏虚，见面色淡白、乏力但无突然转佳；阴阳失调项泛指、不具特征；脏腑虚弱项为慢性虚损过程；阳气亏虚项见畏寒肢冷、精神萎靡而非突然兴奋"},{"q":"患者突发颜面、眼睑浮肿，继而全身出现水肿，宜诊断为","o":["伤风","风疹","风中经络","风痹","风水"],"a":4,"e":"突发颜面眼睑浮肿继而全身水肿，起病急、自上而下，为风邪袭表、肺失宣降、水溢肌肤之风水。伤风项实为风邪犯表，见鼻塞流涕、头痛、咳嗽；风疹项描述的是皮肤瘙痒、皮疹色淡红；风中经络项见口眼歪斜、半身不遂；风痹项见关节游走性疼痛"},{"q":"患者膝部关节肿大疼痛，股胫肌肉消瘦，步履艰难，舌淡苔白，脉沉称为","o":["“O”形腿","“X”形腿","膝内翻","膝外翻","鹤膝风"],"a":4,"e":"膝部关节肿大疼痛、股胫肌肉消瘦、步履艰难、舌淡苔白、脉沉，为寒湿痹阻、膝关节肿大如鹤之鹤膝风。O形腿项实为膝内翻、X形腿项为膝外翻，皆为骨骼畸形而无关节肿痛、肌肉消瘦；膝内翻项与膝外翻项仅描述下肢力线异常，不具鹤膝样肿胀"},{"q":"患者，男，68岁。患者在外出时突然昏倒，不省人事，喉中痰鸣，口眼歪斜，半身不遂，舌红苔腻，脉弦有力。辨证属","o":["肝阴虚证","肝火炽盛证","肝胆湿热证","肝阳上亢证","肝风内动证"],"a":4,"e":"突然昏倒、不省人事、喉中痰鸣、口眼歪斜、半身不遂、舌红苔腻、脉弦有力，为肝阳化风、风痰上扰、闭阻经络之肝风内动证。肝阴虚证项实为阴亏，见目涩、潮热盗汗、舌红少苔；肝火炽盛项描述的是目赤口苦、便秘尿黄；肝胆湿热项见口苦、胁痛、苔黄腻；肝阳上亢项见眩晕头胀、面红目赤但无昏倒偏瘫"},{"q":"患者情志抑郁，胸闷善太息，近来少腹及乳房胀痛，苔薄白，脉弦。证属","o":["气滞证","气逆证","气闭证","血瘀证","血热证"],"a":0,"e":"情志抑郁、胸闷善太息、少腹及乳房胀痛、苔薄白、脉弦，为肝气郁结、气机阻滞之气滞证。气逆证项实为气机上升太过，见咳嗽喘息、呃逆呕吐；气闭证项描述的是气机闭塞，见突然昏厥、牙关紧闭、二便不通；血瘀证项见刺痛固定、肿块、舌紫暗、脉涩；血热证项见出血、心烦、舌红绛、脉数"},{"q":"患者月经量少色淡，头晕眼花，夜寐不安，面色淡白无华，舌淡，脉弦细。证属","o":["气虚证","血虚证","血瘀证","阴虚证","血寒证"],"a":1,"e":"月经量少色淡、头晕眼花、夜寐不安、面色淡白无华、舌淡、脉弦细，为血液不足、濡养失职之血虚证。气虚证项实为气少乏力，见面色㿠白、气短自汗、脉虚；血瘀证项描述的是刺痛、肿块、舌紫暗、脉涩；阴虚证项见潮热盗汗、舌红少苔；血寒证项见手足冷痛、月经色暗、脉沉迟"},{"q":"患者一侧面肌弛缓、额纹消失、眼不闭合、鼻唇沟平坦、口角下垂，四肢活动自如，多见于","o":["面瘫","中风病","痿病","截瘫","痉病"],"a":0,"e":"一侧面肌弛缓、额纹消失、眼不闭合、鼻唇沟平坦、口角下垂而四肢活动自如，为风痰阻于面部经络之面瘫，病限于面部。中风病项实为风痰瘀阻脑络，见半身不遂、语言不利；痿病项描述的是肢体痿软无力、肌肉萎缩；截瘫项见双下肢瘫痪；痉病项见项背强急、四肢抽搐"},{"q":"患者近3个月来因工作压力过大，出现心悸怔忡，心烦失眠，多梦，五心烦热，潮热盗汗，颧红，咽干，舌红苔少，最有可能出现的脉象是","o":["细数脉","浮数脉","细弱脉","沉紧脉","滑数脉"],"a":0,"e":"心悸怔忡、心烦失眠、多梦、五心烦热、潮热盗汗、颧红、咽干、舌红苔少，为心阴虚、虚热内扰，阴虚则脉细、内热则脉数，故见细数脉。浮数脉项实为风热表证；细弱脉项描述的是气血俱虚；沉紧脉项为寒邪、痛证；滑数脉项为痰热或湿热"},{"q":"患者，男，80岁。胸胁饱满，胀痛，随呼吸、咳嗽、转身而疼痛加剧，辨证应属","o":["饮停胸胁","饮停于胃","饮停于肠","水饮凌心","痰湿阻肺"],"a":0,"e":"胸胁饱满胀痛，随呼吸、咳嗽、转身而加剧，为饮邪停于胸胁、气机阻滞之饮停胸胁，即悬饮。饮停于胃项实为痰饮，见脘痞、水声辘辘、呕吐清水；饮停于肠项描述的是肠鸣辘辘、腹泻；水饮凌心项见心悸喘息不得卧、心下痞坚；痰湿阻肺项见咳嗽痰多、胸闷、苔白腻"},{"q":"患者昨日眼睑边缘局部微有红肿痒痛，伴有头痛，发热，全身不适，舌苔薄白，脉浮数，宜诊断为","o":["风热外袭之针眼","风热邪毒之眼丹","热毒上攻之针眼","脾胃蕴热之眼丹","脾胃虚弱之针眼"],"a":0,"e":"眼睑边缘局部微有红肿痒痛，伴头痛、发热、全身不适、苔薄白、脉浮数，为风热外袭、上攻眼睑之针眼，病位局限、病情轻。风热邪毒之眼丹项实为眼睑弥漫性红肿热痛、病情较重；热毒上攻之针眼项描述的是局部红肿热痛明显、化脓、口渴便秘；脾胃蕴热之眼丹项见眼睑红肿、口臭、便秘、苔黄；脾胃虚弱之针眼项反复发作、乏力、舌淡"},{"q":"患者，女，60岁。心前区疼痛10年余，每逢秋冬季节加重，今年入冬后感心前区刺痛，放射至左肩背部，伴心悸、胸闷，舌质紫黯，脉沉涩。其证候是","o":["痰阻心脉证","气滞血瘀证","气郁心脉证","瘀阻心脉证","寒凝心脉证"],"a":3,"e":"心前区疼痛十年、入冬刺痛、放射至左肩背，伴心悸胸闷、舌质紫黯、脉沉涩，为瘀血阻于心脉、不通则痛之瘀阻心脉证。痰阻心脉项实为痰浊闭阻，见胸闷痛、体胖、苔白腻、脉滑；气滞血瘀项描述的是胀痛、情志相关、脉弦涩；气郁心脉项见胸闷、太息、脉弦；寒凝心脉项见遇寒痛剧、畏寒肢冷、脉沉紧"},{"q":"患者，男，56岁。浮肿、腰痛2年。初为面肿，后下肢亦肿，近3个月来，水肿向全身发展，伴食少腹胀，腰膝酸软，畏寒肢冷，小便短少，神疲乏力，舌质淡白，苔黑而滑，脉沉细无力。其腰痛的病机是","o":["寒湿痹病","肾阳亏虚","瘀血阻络","经络阻滞","带脉损伤"],"a":1,"e":"浮肿、腰痛两年，面肿后及下肢、全身，伴食少腹胀、腰膝酸软、畏寒肢冷、小便短少、舌淡白、苔黑而滑、脉沉细无力，为肾阳亏虚、阳虚水泛，腰为肾之府故腰痛。寒湿痹病项实为寒湿阻络，见关节冷痛重着、活动受限；瘀血阻络项描述的是腰痛如刺、固定不移、舌紫暗；经络阻滞项泛指；带脉损伤项见腰腹坠胀、带下清稀"},{"q":"患者脐周腹痛，时作时止，腹部可触及条索状虫团，多考虑","o":["肠道蛔虫病","胆道蛔虫病","蛔厥证","钩虫病","蛲虫病"],"a":0,"e":"脐周腹痛、时作时止、腹部可触及条索状虫团，为蛔虫等寄生肠道、气机阻滞之肠道蛔虫病。胆道蛔虫病项实为蛔虫入胆，见剑突下钻顶样剧痛、呕吐；蛔厥证项描述的是腹痛剧烈、手足厥冷；钩虫病项见面黄虚浮、乏力、多食易饥；蛲虫病项见肛门瘙痒、夜寐不安"},{"q":"患者左少腹作痛，按之累累有硬块者，应考虑","o":["肠痈","虫积","宿粪","疝气","瘕聚"],"a":2,"e":"左少腹作痛、按之累累有硬块，为燥屎内结、腑气不通之宿粪，左下腹为乙状结肠所在，故可触及条状硬结。肠痈项实为肠道痈肿，见右下腹疼痛拒按、发热、可触及包块；虫积项描述的是脐周疼痛、虫团、时作时止；疝气项见少腹坠痛、阴囊包块；瘕聚项为气聚，包块时聚时散、无固定形"},{"q":"患者，女，27岁。平素嗜食生冷食物，反复脘腹痞闷半月余，食少便溏，口腻纳呆，头身困重，舌淡胖苔白腻，脉濡缓。诊为","o":["湿热蕴脾证","寒湿困脾证","脾气虚证","寒滞胃脘证","脾阳虚证"],"a":1,"e":"平素嗜食生冷，寒湿内生，困阻脾胃则脘腹痞闷、食少便溏、口腻纳呆、头身困重，舌淡胖苔白腻、脉濡缓，为寒湿困脾证。湿热蕴脾项实为湿热中阻，见口苦、苔黄腻、脉濡数；脾气虚证项描述的是食少便溏、乏力、舌淡苔白而无口腻头重、苔腻；寒滞胃脘项见胃脘冷痛剧烈、脉弦紧；脾阳虚证项见腹痛喜温喜按、畏寒肢冷、苔白滑"},{"q":"患者脘腹冷痛，泛吐清涎，小便短黄，舌质红苔薄黄，脉沉弦。证属","o":["上热下寒证","真热假寒证","真寒假热证","表里实寒证","上寒下热证"],"a":4,"e":"脘腹冷痛、泛吐清涎为中焦有寒，小便短黄、舌质红苔薄黄为下焦有热，寒热错杂于上下，属上寒下热证。上热下寒项实为上部热、下部寒，见口苦咽痛、便溏尿清；真热假寒项描述的是手足厥冷、烦渴喜冷、脉洪数有力；真寒假热项见身热反欲盖衣、脉微欲绝；表里实寒项见恶寒、腹痛便溏、苔白、脉沉紧，无上下寒热之分化"},{"q":"泄泻半年余，伴有面白无华，形寒肢冷，腰膝及下腹冷痛，舌淡胖，苔白滑，脉沉细。应诊断为","o":["肾阳虚证","脾阳虚证","肾气不固证","脾肾阳虚证","寒湿困脾证"],"a":3,"e":"泄泻半年、面白无华、形寒肢冷、腰膝及下腹冷痛、舌淡胖苔白滑、脉沉细，为脾肾阳虚、火不暖土、运化失司。肾阳虚证项实为肾阳不足，见腰膝酸软、夜尿多、水肿而泄泻不著；脾阳虚证项描述的是腹胀便溏、畏寒肢冷但无腰膝及下腹冷痛；肾气不固证项见遗尿滑精；寒湿困脾证项见脘腹痞闷、口腻、苔白腻、脉濡"},{"q":"患者鼻塞清涕1日，鼻塞严重无法呼吸，喷嚏频作，流涕量多而清稀，头痛，恶寒，发热轻，舌淡，苔薄白，脉浮紧。最宜诊断为","o":["外感风寒","外感风热","肺气虚寒","肺胃郁热","寒痰阻肺"],"a":0,"e":"鼻塞清涕、喷嚏频作、流涕量多清稀、头痛、恶寒发热轻、舌淡苔薄白、脉浮紧，为风寒束表、肺气失宣之外感风寒。外感风热项实为风热犯表，见流浊涕、咽痛、发热重、脉浮数；肺气虚寒项描述的是鼻塞清涕、气短乏力、舌淡苔白但无表证；肺胃郁热项见鼻涕黄稠、口臭便秘；寒痰阻肺项见咳嗽痰多清稀、胸闷、舌淡苔白"},{"q":"患者，女。近2个月来经常咳血，潮热骨蒸，盗汗音哑，喘息气短，形寒肢冷，恶风自汗，食少便溏，舌淡红有裂纹少津，脉沉细。证属","o":["阳虚证","阴虚证","阴阳两虚证","真实假虚证","真虚假实证"],"a":2,"e":"咳血、潮热骨蒸、盗汗音哑为阴虚火旺；喘息气短、形寒肢冷、恶风自汗、食少便溏为阳气亏虚，舌淡红有裂纹少津、脉沉细，阴阳俱损，属阴阳两虚证。单纯阳虚证项实为阳虚阴盛，见畏寒便溏、舌淡而无潮热盗汗、咳血；阴虚证项描述的是潮热盗汗、舌红少苔而无形寒肢冷、便溏；真实假虚项与真虚假实项皆为虚实真假之辨，非阴阳俱虚"},{"q":"患者身热不扬，倦怠懒言，便溏不爽，舌红苔黄腻，脉沉滑，证属","o":["真实假虚","虚实夹杂","真虚假实","表虚里实","表实里虚"],"a":1,"e":"身热不扬、倦怠懒言为脾气虚弱，便溏不爽、舌红苔黄腻、脉沉滑为湿热内蕴，正气虚与湿热实并见，属虚实夹杂。真实假虚项实为本质属实、外现虚象；真虚假实项描述的是本质属虚、外现真实之象；表虚里实项为表虚证兼里实证；表实里虚项为表实证兼里虚证，均非本例虚实并见之机"},{"q":"患者，女，68岁。素有头晕、头痛反复发作已历3年，刻下头部右侧后痛如锥刺，伴失眠，心悸，记忆力下降。此属下列何证","o":["心阳虚证","痰火扰心证","瘀阻脑络证","胆郁痰扰证","痰蒙心神证"],"a":2,"e":"头部右侧后痛如锥刺、部位固定，伴失眠、心悸、记忆力下降，为瘀血阻于脑络、不通则痛之瘀阻脑络证。心阳虚证项实为心阳不足，见心悸胸闷、畏寒肢冷；痰火扰心项描述的是神昏谵语、狂躁不安、苔黄腻；胆郁痰扰项见失眠惊悸、口苦、苔黄腻；痰蒙心神项见神志痴呆、表情淡漠、喉中痰鸣"},{"q":"患者右胁下肿块，质地坚硬，按之表面凹凸不平，应考虑","o":["气滞","肝癌","血瘀","肝虚","肝痈"],"a":1,"e":"右胁下肿块、质地坚硬、按之表面凹凸不平，为癥积日久、瘀毒互结之肝癌。气滞项实为气机郁滞，见胁胀走窜、无形质硬块；血瘀项描述的是刺痛、肿块但表面较光滑、舌紫暗；肝虚项见胁痛隐隐、头晕目涩、舌淡；肝痈项为肝脏化脓性病变，见右胁疼痛拒按、高热寒战"},{"q":"患者，女，45岁。胃脘嘈杂，时作腹痛2个月余，腹痛以脐周为甚，伴面黄体痩，面部出现白斑，大便排虫，舌淡苔薄白，脉弦细。辨证为","o":["胃气虚证","脾气虚证","肠热腑实证","大肠湿热证","虫积肠道证"],"a":4,"e":"胃脘嘈杂、腹痛以脐周为甚，伴面黄体瘦、面部白斑、大便排虫、脉弦细，为蛔虫等寄生肠道、耗伤气血之虫积肠道证。胃气虚证项实为胃气不足，见胃脘隐痛、食少、嗳气、脉虚；脾气虚证项描述的是食少便溏、乏力、舌淡；肠热腑实证项见腹满硬痛、便秘、潮热；大肠湿热证项见腹痛下痢脓血、里急后重、苔黄腻"},{"q":"带下清稀，伴腥臭者，多属","o":["湿热","寒湿","癌病","湿毒","血瘀"],"a":1,"e":"带下清稀色白量多，因寒湿内侵、任脉不固、带脉失约，兼腥臭为寒湿郁久之物。湿热项带下黄稠臭秽，质黏量多，与清稀相反。湿毒项多为黄绿如脓或五色夹杂、臭秽难闻，常伴阴痒。癌病项带下五色混杂、臭秽如米泔，非单纯清稀"},{"q":"患者，女，22岁。发热恶寒，汗出，口渴头痛，舌红苔黄，尿赤，脉滑数，属于","o":["卫分证","卫气同病","气分证","气营同病","气营两燔"],"a":1,"e":"发热恶寒并见头痛，为邪在卫分；口渴、舌红苔黄、尿赤、脉滑数为气分热盛，表里同病故属卫气同病。卫分证项但见恶寒发热、苔薄白，无里热。气分证项但热不寒、不恶寒。气营两燔项兼神昏谵语、舌绛发斑"},{"q":"患者，男，25岁。腹痛、腹泻2日，一日数次，泻下物色黄味臭，伴肛门灼热，小便黄，舌红苔黄腻，脉滑数。最宜辨证为","o":["大肠湿热证","肠热腑实证","下焦湿热证","虫积肠道证","食积肠道证"],"a":0,"e":"泻下黄糜味臭、肛门灼热、小便黄、舌红苔黄腻、脉滑数，为湿热蕴结大肠、传导失司。肠热腑实项见大便硬结、腹满硬痛拒按、潮热谵语。虫积肠道项见腹痛时作、面黄体瘦、粪便见虫体。食积肠道项泻下酸腐、矢气臭秽、脘腹胀满"},{"q":"患者，女，21岁，学生。2005年7月14日初诊。胃脘胀痛5年，加重伴恶心3天。初诊：患者因住校就餐，饥饱不均，出现胃脘胀痛，在本地医院经胃镜检查诊断为慢性胃炎，用药不详，疗效不明显……病案中的“胃脘胀痛5年，加重3天，伴恶心”是","o":["主症","主诉","主证","主病","现在症状"],"a":1,"e":"主诉为患者就诊时最主要的症状及其持续时间，胃脘胀痛5年、加重3天、伴恶心正属此列。主症项指本病主要证候表现，不强调就诊时限。现在症状项指刻下全部症状，含兼症与舌脉。主病项指中医病名诊断，非症状描述"},{"q":"患者，男，55岁。近半年来多食易饥，口渴多饮，小便量多，体重下降，日渐消瘦，伴见疲乏，动辄汗出，舌淡泛青，隐现瘀斑，苔薄白，脉虚细涩。中医诊断为","o":["燥热伤津","里热炽盛","痰火内扰","消渴病","瘀热互结"],"a":3,"e":"多食易饥、口渴多饮、小便量多、体重下降，为消渴三多一少，属阴亏燥热、气阴两伤，兼见疲乏汗出、舌淡泛青瘀斑为气阴两虚夹瘀。燥热伤津项仅见口渴咽干、舌红少津，无多尿消瘦。里热炽盛项但见壮热烦渴、脉洪大。痰火内扰项见胸闷痰多、心烦失眠"},{"q":"患者，男，63岁。病发时狂躁妄动，胡言乱语，少寐多梦，打骂他人，不避亲疏，见于","o":["癫病","狂病","痫病","中风","郁病"],"a":1,"e":"狂躁妄动、胡言乱语、打骂他人、不避亲疏，为痰火扰心、神明失常的狂病，属阳证。癫病项见表情淡漠、喃喃自语、静而少动，属阴证。痫病项见突然昏仆、四肢抽搐、口吐涎沫、醒后如常。郁病项见情志抑郁、胸闷太息，无狂乱"},{"q":"顿咳最常见于","o":["小儿","老年人","青年人","男性","女性"],"a":0,"e":"顿咳即百日咳，为外感时行疫毒犯肺，小儿稚阴稚阳、卫外不固，故最常见于小儿，咳声短促、咳后鸡啼样回声为特征。老年人项正气亏虚，多见咳喘虚证。青年人、男性、女性项均无年龄或性别特异性"},{"q":"患者，女，15岁。2天前吃路边烧烤后出现腹痛腹泻，每日大便10余次，有黏冻脓血，伴发热，里急后重，口干饮水不多，腹软，左下腹压痛，舌红苔黄，脉濡数。其病证机理为","o":["食滞胃肠","脾胃虚弱","寒湿困脾","大肠湿热","寒滞胃肠"],"a":3,"e":"黏冻脓血便、里急后重、发热、舌红苔黄、脉濡数，为湿热壅滞大肠、气血瘀滞、传导失司。食滞胃肠项泻下酸腐、脘腹胀满、嗳腐吞酸。寒湿困脾项泻下清稀、腹部冷痛、舌淡苔白腻。寒滞胃肠项见胃脘冷痛、喜温喜按、脉紧"},{"q":"患者，男，10岁。3日前开始发热，体温持续38～39℃不退，就诊前突然出现四肢抽搐，颈项强直，角弓反张，神昏谵语，舌质红绛，苔黄燥，脉弦数。辨证属","o":["肝阳化风证","热极生风证","肝胆湿热证","肝阴虚证","阴虚动风正"],"a":1,"e":"高热持续、抽搐、颈项强直、角弓反张、神昏谵语、舌红绛苔黄燥，为邪热炽盛、燔灼肝经、筋脉失养的热极生风。肝阳化风项见眩晕欲仆、肢麻震颤、脉弦长有力，无高热。肝阴虚项见虚热、手足蠕动，非急骤抽搐"},{"q":"胸胁胀闷，善太息，脘部胀痛，苔薄白，脉弦。宜诊断为","o":["胃肠气滞证","肝气郁滞证","肝火犯胃证","饮停胸胁证","肝胃不和证"],"a":4,"e":"胸胁胀闷、善太息为肝气郁结，脘部胀痛为肝气犯胃、胃失和降，脉弦为肝病，故属肝胃不和。肝气郁滞项仅有胁胀太息，无脘痛胃逆。肝火犯胃项见胁痛口苦、吞酸嘈杂、舌红苔黄。饮停胸胁项见胸胁胀满、咳唾引痛"},{"q":"患者，女，40岁。近半年来经常腰膝酸痛，头晕耳鸣，月经量少，口燥咽干，潮热盗汗，舌红少津，脉细数。其腰痛的病机是","o":["寒湿阻滞","肾阳亏虚","肾精亏虚","肾阴亏虚","带脉损伤"],"a":3,"e":"腰膝酸痛、头晕耳鸣、月经量少、潮热盗汗、舌红少津、脉细数，为肾阴亏虚、虚火内扰、腰府失养。肾阳亏虚项见腰膝冷痛、畏寒肢冷、脉沉迟。肾精亏虚项见早衰、发脱齿摇、小儿五迟。寒湿阻滞项腰部冷痛重着、苔白腻"},{"q":"患者，男，55岁。头痛、眩晕2年余，未系统治疗，近2周症状加重，现症见眩晕耳鸣，头目胀痛，急躁易怒，腰膝酸软，头重脚轻，舌质红，脉弦细数。其头痛的病机是","o":["肝风内动","肝火上炎","肝肾阴亏","肝阳上亢","肝胆湿热"],"a":3,"e":"眩晕耳鸣、头目胀痛、急躁易怒、腰膝酸软、头重脚轻、脉弦细数，为肝肾阴亏于下、肝阳亢扰于上，上实下虚。肝风内动项见肢体麻木、震颤或抽搐。肝火上炎项见目赤口苦、便秘尿黄、脉弦数有力，无腰膝酸软。肝胆湿热项见胁痛口苦、苔黄腻"},{"q":"患者，女，56岁。头晕、头痛反复发作已历1年，痛发则如锥刺难忍、痛处多在左侧，近半年来易健忘，时有失眠、心悸。刻下：面色晦暗，舌质紫黯或有斑点，脉细涩。此属下列何证","o":["心脉痹阻证","痰火扰神证","心火亢盛证","瘀阻脑络证","肝阳化风证"],"a":3,"e":"头痛如锥刺、痛处固定、面色晦暗、舌紫黯有斑点、脉细涩，为瘀血阻于脑络、不通则痛，兼健忘失眠心悸。心脉痹阻项以心悸怔忡、胸前区闷痛为主。痰火扰神项见神昏谵语、喉中痰鸣、苔黄腻。肝阳化风项见眩晕欲仆、肢麻震颤"},{"q":"患者平素食少纳呆，腹胀便溏，近日心悸怔忡，头晕健忘，神疲乏力，月经淋漓不断，色淡量少，舌淡嫩，脉细弱。辨证为","o":["脾气虚证","心血虚证","脾不统血证","心脾两虚证","脾虚气陷证"],"a":3,"e":"心悸怔忡、头晕健忘、神疲乏力、月经淋漓色淡，兼食少腹胀便溏，为心血不足、脾气虚弱、气血生化乏源。脾气虚证项仅有纳呆便溏、乏力，无心悸失眠。脾不统血项以出血为主，无心悸怔忡。脾虚气陷项见脱肛、久泻、内脏下垂"},{"q":"患者平素月经过多，面色无华，神疲乏力，心悸失眠，舌淡，脉弱无力","o":["气虚血瘀证","气滞血瘀证","气血两虚证","气不摄血证","气随血脱证"],"a":3,"e":"月经过多、面色无华、神疲乏力、心悸失眠、舌淡脉弱，为气虚不能统摄血液、血溢脉外，属气血两虚之象。气血两虚项虽有面白乏力，但无明确出血倾向。气虚血瘀项见疲乏兼刺痛、舌淡紫。气随血脱项见大出血后冷汗、脉微欲绝"},{"q":"患者，女，27岁，干部。2016年3月11日初诊。胃脘胀痛3年，加重4天，伴恶心、呕吐。初诊：患者因饮食不调，出现胃脘胀痛，在本地医院经胃镜检查诊断为慢性胃炎，用药不详，疗效不明显。近4天来胃脘胀痛，饥饿时明显，伴恶心、呃逆、呕吐，无反酸，腹胀，头晕，纳呆，二便调，睡眠佳。2007年做胃镜检查报告：慢性浅表性胃炎，反流性食管炎，Hp(-)。舌质淡红，苔薄白，脉平缓……病案中的“2007年做胃镜检查报告：慢性浅表性胃炎，反流性食管炎，Hp(-)”是","o":["一般情况","主诉","现病史","既往史","个人史"],"a":3,"e":"既往史记载患者既往疾病史、手术外伤史及既往检查诊断，2007年胃镜报告距就诊已多年，属既往史。主诉项为就诊主要痛苦及时间。现病史项为本次发病全过程。一般情况项指姓名、年龄、职业等基本信息。个人史项指生活习惯、居处环境"},{"q":"男，36岁。患胃病10年，近1周来干呕时作，口渴心烦，胃脘隐痛，知饥而不欲饮食，便结溲黄，舌红少苔，脉弦细偏数。属于","o":["食滞胃脘","胃火炽盛","胃阴亏虚","肝气犯胃","脾胃虚弱"],"a":2,"e":"胃脘隐痛、知饥不欲食、干呕、口渴心烦、便结溲黄、舌红少苔、脉弦细数，为胃阴不足、虚热内扰、胃失濡降。胃火炽盛项见胃脘灼痛、消谷善饥、口臭龈肿、苔黄。食滞胃脘项见胀痛嗳腐、苔厚腻。肝气犯胃项见胁胀、胃痛走窜、脉弦"},{"q":"患者，女，40岁。半年来时感入睡困难，心急易怒，伴头晕耳鸣，五心烦热，潮热盗汗，腰膝酸软，舌红少苔，脉细数。其失眠的病机为","o":["肝肾阴虚","心脾两虚","心肾不交","胆郁痰扰","肝火上炎"],"a":2,"e":"入睡困难、心烦、头晕耳鸣、五心烦热、潮热盗汗、腰膝酸软、舌红少苔脉细数，为肾阴亏于下、心火亢于上、水火不济。心脾两虚项见心悸健忘、纳差便溏、面白。肝肾阴虚项以目涩胁痛、腰酸为主，无失眠心烦。胆郁痰扰项见惊悸不寐、口苦苔腻"},{"q":"患者，男，28岁。身热不扬，头身重痛，胸脘痞闷，恶心欲吐，舌红苔黄腻，脉濡数，应属","o":["上焦病","太阴湿热证","燥热内结证","下焦病","大肠湿热证"],"a":1,"e":"身热不扬、头身重痛、胸脘痞闷、恶心欲吐、苔黄腻、脉濡数，为湿热郁阻太阴脾胃、气机不利。上焦病项见发热恶寒、咳嗽头痛。下焦病项见身热颧红、手足心热、舌绛。大肠湿热项以腹痛泻痢、里急后重为主"},{"q":"患者，男，32岁。患肺结核多年，形体消瘦，2天前因受凉后感冒，咳嗽，痰少，恶寒，发热，脉浮数。证属阴虚火旺，复感风寒之邪。可见到的舌象是","o":["红绛舌，黄燥苔","红瘦舌，薄白苔","绛舌，黄白苔","红舌，苍老滑苔","淡白舌，黄裂苔"],"a":1,"e":"形体消瘦、干咳痰少、五心烦热、盗汗示阴虚火旺，舌体失养故红瘦；新感风寒邪在表，故苔薄白。红绛舌黄燥苔为里热炽盛、津伤。绛舌黄白苔为营分兼气分。淡白舌黄裂苔为气血不足兼热盛伤津，与本例不符"},{"q":"患者前胸高突，叩之膨膨然有如鼓音，多为","o":["肺痨","肺痿","肺痈","肺胀","肺热"],"a":3,"e":"前胸高突、叩之膨膨然如鼓音，为肺气胀满、气道壅滞、胸廓膨隆的肺胀，多因久咳喘促、肺气壅滞。肺痨项见咳嗽咯血、潮热盗汗、消瘦。肺痿项见咳吐浊唾涎沫、气短。肺痈项见发热胸痛、咳吐腥臭脓血。肺热项但见咳喘痰黄、发热"},{"q":"患者，男，48岁。患胃病若干年，近半月病情加重，出现胃脘胀痛，腹胀疼痛，部位走窜不定，按诊检查腹部较软，左侧腹部有一肿块，质地柔软，表面光滑，按之可移，舌淡红，苔白，脉弦，属于","o":["痰凝","血瘀","积饮","气滞","伤食"],"a":3,"e":"胃脘腹胀痛、部位走窜不定、腹部柔软、肿块柔软光滑、按之可移、脉弦，为气机郁滞、聚散无常。血瘀项肿块坚硬、痛如针刺、固定不移、舌紫暗。痰凝项肿块质韧、按之不移、苔腻。积饮项见腹中振水音、呕吐清水。伤食项见嗳腐吞酸、脘腹胀满拒按"},{"q":"患者，女，20岁，大学生。半年前正值经期第3天，参加院篮球比赛，之后月经量突然增多，且持续10余日方止。此后，每月月经均量多，时间长，经色淡红，并伴有神疲，倦怠乏力，食少便溏，面白无华，舌淡苔白，脉细无力。其月经过多的病机为","o":["气虚冲任不固","血热迫血妄行","瘀阻冲任，血不归经","肝郁脾虚失固","脾肾阳虚不固"],"a":0,"e":"月经量多色淡、神疲乏力、食少便溏、面白无华、舌淡脉细无力，为脾气虚弱、冲任不固、血失统摄。血热迫血妄行项经色深红稠黏、心烦口渴、脉数。瘀阻冲任项经色暗红有块、小腹刺痛。脾肾阳虚项见畏寒肢冷、腰膝酸冷"},{"q":"病人身大热，汗大出，口大渴，面赤，气粗似喘，心烦躁扰，舌苔黄燥，脉洪大，其证属","o":["阳明腑证","阳明经证","太阳腑证","少阳腑证","少阳经证"],"a":1,"e":"身大热、汗大出、口大渴、面赤气粗、心烦、苔黄燥、脉洪大，为邪入阳明之经、里热蒸腾、津伤，腑实未成。阳明腑证项见潮热谵语、腹满硬痛拒按、大便不通、脉沉实。太阳腑证项见发热恶寒、小便不利或蓄血。少阳病项见寒热往来、胸胁苦满、脉弦"},{"q":"患者近日来饮食不节，出现胃脘胀痛，嗳气，食滞胃脘，其脉多为","o":["弦脉","滑脉","数脉","缓脉","濡脉"],"a":1,"e":"食滞胃脘、胃脘胀痛、嗳气，为宿食内停、气机阻滞，滑脉主痰饮、食滞、实热，故多见滑脉。弦脉主肝胆病、疼痛、痰饮，非食滞主脉。数脉主热证。缓脉主湿证、脾胃虚弱。濡脉主虚证、湿证，均非食滞典型脉"},{"q":"患者，20岁。初起恶寒发热，咽喉疼痛，继之眼睑头面浮肿，小便量少的临床意义是","o":["痰饮","悬饮","支饮","阳水","阴水"],"a":3,"e":"初起恶寒发热、咽喉疼痛，继则眼睑头面浮肿、小便量少，起病急、肿自上而下达，属风邪犯肺、水道不利的阳水。阴水项起病缓、肿自下而上、腰以下甚、反复难愈。痰饮项见脘腹痞满、呕吐清水、肠鸣。悬饮项见胸胁胀痛、咳唾引痛。支饮项见咳逆倚息、短气不得卧"},{"q":"患者两眦赤脉粗大鲜红，痒涩刺痛，头痛烦热，口干咽燥，或口舌生疮，大便燥结，小便黄赤，舌尖红，舌苔黄，脉数。此病最宜诊断为","o":["肝火上炎","肺经风热","心火上炎","胃火炽盛","肝经风热"],"a":2,"e":"两眦赤脉粗大鲜红、痒涩刺痛，兼口舌生疮、心烦、小便黄赤、舌尖红，为心火亢盛、循经上炎于目。肝火上炎项见目赤肿痛、胁痛口苦、脉弦数。肺经风热项见白睛红赤、流泪、咽痛咳嗽。胃火炽盛项见牙龈肿痛、口臭、消谷善饥。肝经风热项见目痒流泪、头胀"},{"q":"患者牙龈红肿，出血，出脓，口臭，烦渴多饮，大便秘结，舌红，苔黄厚，脉滑数。此病最宜诊断为","o":["肺热炽盛","肾阴亏损","胃火亢盛","心脾积热","心火上炎"],"a":2,"e":"牙龈红肿出血出脓、口臭、烦渴多饮、大便秘结、舌红苔黄厚、脉滑数，为胃火循经上蒸龈络、腐肉伤络。心脾积热项以口舌生疮、舌尖红赤为主。肾阴亏损项见牙龈微肿、齿摇不坚、手足心热、舌红少苔。肺热炽盛项见发热咳喘、鼻煽。心火上炎项见心烦失眠、小便短赤"},{"q":"患者，男，50岁。大便3日未解，腹部硬满疼痛、拒按，舌红苔黄燥，脉沉数有力，辨为肠热腑实证。其可导致的神志异常为","o":["闷闷不乐","突然昏仆","哭笑无常","神昏谵语","神昏郑声"],"a":3,"e":"大便硬结、腹硬满疼痛拒按、舌红苔黄燥、脉沉数有力，为肠热腑实、燥屎内结、腑气不通，浊热上扰心神则神昏谵语。神昏郑声为虚证、心气大伤、精神散乱，声音低微重复。突然昏仆为中风、痫病。哭笑无常为癫病、痰迷心窍。闷闷不乐为郁病、肝气郁结"},{"q":"患者，女，32岁。因1年前考公务员意外落选，一直郁郁寡欢，表情淡漠，神志痴呆，喃喃自语，哭笑无常，悲观失望，舌红，苔白，脉弦，其病机是","o":["气郁化火，痰火扰心","阳明热盛，扰乱神明","肝风夹痰，蒙蔽心神","痰迷心窍","温病邪热入于心包"],"a":3,"e":"郁郁寡欢、表情淡漠、神志痴呆、喃喃自语、哭笑无常、苔白脉弦，为情志不遂、肝气郁结、痰浊内生、蒙蔽心窍的癫病。气郁化火痰火扰心项见躁狂打骂、面赤苔黄腻。肝风夹痰项见眩晕欲仆、肢麻震颤。阳明热盛项见壮热谵语、腹满便秘。温病热入心包项见身热夜甚、神昏谵语、舌绛"},{"q":"患者胸闷脘痞，纳呆呕吐，肠鸣腹泻，舌淡胖苔白腻，脉濡缓，宜诊断为","o":["风淫证","寒淫证","暑淫证","湿淫证","火淫证"],"a":3,"e":"胸闷脘痞、纳呆呕吐、肠鸣腹泻、舌淡胖苔白腻、脉濡缓，为湿邪困阻脾胃、气机升降失常。风淫证项见恶风汗出、脉浮缓。寒淫证项见恶寒甚、无汗、脉紧。暑淫证项见发热烦渴、汗多、脉虚数。火淫证项见高热烦渴、舌红苔黄、脉数"},{"q":"患者发热，午后热甚，身热不扬，属于","o":["骨蒸劳热","湿温潮热","阴虚内热","阳明潮热","气虚发热"],"a":1,"e":"发热、午后热甚、身热不扬，为湿温病湿热蕴结、湿郁热蒸，热势不扬、午后加重。阴虚潮热项见午后或夜间潮热、颧红盗汗、舌红少苔。阳明潮热项见日晡潮热、腹满硬痛、大便燥结。骨蒸劳热项见骨蒸潮热、盗汗遗精、消瘦。气虚发热项见劳累后热甚、少气懒言"},{"q":"患者，男，52岁。病人1年前在疲劳后出现心悸、胸闷气短，未经诊治，近两个月上症明显加重。现症见胸闷，心悸，气短，时有胸痛，畏寒肢冷，面色淡白，舌淡苔白滑，脉弱。其胸闷的病机是","o":["痰湿内阻","心阳亏虚","阳气暴脱","心血瘀阻","心气亏虚"],"a":1,"e":"胸闷心悸气短、胸痛、畏寒肢冷、面色淡白、舌淡苔白滑、脉弱，为心阳不足、胸阳不振、温运无力。心气亏虚项见心悸气短、乏力自汗，无畏寒肢冷。痰湿内阻项见胸闷脘痞、苔腻、脉滑。心血瘀阻项见心前区刺痛、舌紫暗、脉涩。阳气暴脱项见冷汗淋漓、脉微欲绝"},{"q":"患者，男，65岁。长期腰膝酸冷，泄泻日久，完谷不化，便质清冷，面色㿠白，舌淡胖，苔白滑，最有可能出现的脉象是","o":["细数无力","洪大","弦数","沉迟无力","浮大无根"],"a":3,"e":"腰膝酸冷、久泻完谷不化、便质清冷、面色㿠白、舌淡胖苔白滑，为脾肾阳虚、里寒证，沉脉主里，迟脉主寒，无力主虚。细数无力为阴虚内热。洪大主热盛。弦数主肝胆热。浮大无根为虚阳外越、阳气将脱"},{"q":"下列不属于实喘特征的是","o":["发作急骤","息粗声高","动则喘甚","呼吸深长","以呼出为快"],"a":2,"e":"实喘发作急骤、息粗声高、呼吸深长、以呼出为快，因邪气壅肺、肺气不宣。动则喘甚为虚喘特征，肺肾亏虚、摄纳无权，活动后耗气而加重。其余选项所述气息粗长有力、发作急骤均为实喘特征，非虚喘所有"},{"q":"患者，女，52岁。主诉咽部异物感，似有痰，咳之不出，咽之不下，伴有月经不调，痛经，舌苔薄白，脉弦，辨证属","o":["肝血虚证","肝郁气滞证","肝胆湿热证","热极生风证","胆郁痰扰证"],"a":1,"e":"咽部异物感、咯之不出咽之不下为梅核气，兼月经不调、痛经、脉弦，为肝气郁结、气机阻滞、津液不布聚而成痰。肝血虚证项见目涩爪甲不荣、月经量少色淡。肝胆湿热项见口苦胁痛、苔黄腻。胆郁痰扰项见惊悸不寐、口苦呕恶。热极生风项见高热抽搐"},{"q":"似喘不抬肩，喉中无痰鸣者称","o":["哮证","上气","短气","热咳","少气"],"a":2,"e":"似喘不抬肩、喉中无痰鸣，呼吸短促而急促，为短气，因气虚或痰饮阻滞、气机不利。哮证项喉中痰鸣、呼吸急促、反复发作。上气项见呼吸急促、肩背抬高。少气项见气短声低、气息微弱、言语无力。热咳项以咳嗽黄痰为主"},{"q":"患者，男，37岁。身体灼热，神昏谵语，四肢抽搐，角弓反张，其病变属于","o":["气分证","卫气同病","营分证","血分证","气血两燔"],"a":3,"e":"身体灼热、神昏谵语、四肢抽搐、角弓反张，为热入血分、耗血动血、热极生风，兼神明扰乱。气分证项见壮热烦渴、苔黄燥，无神昏抽搐。营分证项见身热夜甚、口干不欲饮、斑疹隐隐、舌绛。气血两燔项见壮热、发斑、神昏并见。卫气同病项见发热恶寒并见口渴苔黄"},{"q":"患者下肢水肿，面白神疲，腰膝酸冷，舌淡苔白滑，脉沉迟无力，宜诊断为","o":["肾虚水泛证","肾阳虚证","肾不纳气证","肾阴虚证","心阳虚证"],"a":0,"e":"下肢水肿、面白神疲、腰膝酸冷、舌淡苔白滑、脉沉迟无力，为肾阳亏虚、气化失常、水液泛溢肌肤。肾阳虚证项以腰膝酸冷、畏寒肢冷、五更泄泻为主，水肿不突出。肾不纳气项见呼多吸少、气不归元。心阳虚项见心悸胸闷、唇甲青紫。肾阴虚项见潮热盗汗、舌红少苔"},{"q":"患者，男，50岁。服用抗结核药1年余，现干咳，痰少带血丝，消瘦，五心烦热，盗汗，舌红少苔，脉细数。辨证为","o":["燥邪犯肺证","肝肾阴虚证","肺阴虚证","肺热炽盛证","风热犯肺证"],"a":2,"e":"干咳痰少带血丝、消瘦、五心烦热、盗汗、舌红少苔、脉细数，为肺阴亏虚、虚热内灼、肺络受损。燥邪犯肺项见干咳少痰、口鼻干燥，病程短、无潮热盗汗。肺热炽盛项见发热咳喘、痰黄、苔黄。风热犯肺项见咳嗽咽痛、发热恶寒、脉浮数。肝肾阴虚项以腰膝酸软、头晕目涩为主"},{"q":"患者身目发黄，黄色鲜明，腹部痞满，肢体困重，便溏尿黄，身热不扬，舌红苔黄腻，脉濡数。其证候是","o":["肝胆湿热","大肠湿热","肝火上炎","湿热蕴脾","寒湿困脾"],"a":3,"e":"身目发黄鲜明、腹部痞满、肢体困重、便溏尿黄、身热不扬、苔黄腻、脉濡数，为湿热蕴结脾胃、胆汁外溢、运化失司。肝胆湿热项以右胁胀痛、口苦、寒热往来为主。大肠湿热项见腹痛泻痢、里急后重。寒湿困脾项见身目发黄晦暗、苔白腻、脉沉迟。肝火上炎项目赤头痛、脉弦数"},{"q":"患者，女，17岁。因高考将至，过度紧张，而致心情烦躁，入夜难眠，口干多饮，舌红苔黄干，脉数。其证候是","o":["心阴虚证","肝阴虚证","心血虚证","心火上亢证","肝火上炎证"],"a":3,"e":"心情烦躁、入夜难眠、口干多饮、舌红苔黄干、脉数，为心火亢盛、热扰心神、津液受损。心阴虚证项见心烦失眠、盗汗、舌红少苔、脉细数，无苔黄干。心血虚证项见心悸健忘、面白舌淡。肝阴虚证项见目涩胁痛、头晕。肝火上炎证项见目赤口苦、急躁易怒、脉弦数"},{"q":"患者，男，42岁。小便混浊如米泔2个月余，自觉脘腹重坠作胀，食后尤甚，神疲乏力，肢体倦怠，声低懒言，头晕目眩，舌淡苔白，脉弱。诊为","o":["脾气虚证","脾阳虚证","脾虚气陷证","脾不统血证","寒湿困脾证"],"a":2,"e":"小便混浊如米泔、脘腹重坠作胀、食后尤甚、神疲乏力、声低懒言、头晕目眩、舌淡脉弱，为脾气虚弱、清阳不升、中气下陷。脾气虚证项仅有乏力纳差便溏，无下坠感。脾阳虚证项见腹痛喜温喜按、畏寒肢冷。脾不统血项以出血为主。寒湿困脾项见脘腹痞闷、苔白腻、脉濡缓"},{"q":"患者腹痛腹泻，恶心呕吐，纳呆食少，夜间肛门瘙痒，多考虑","o":["肠道蛔虫病","胆道蛔虫病","蛔厥证","钩虫病","蛲虫病"],"a":4,"e":"夜间肛门瘙痒为蛲虫夜间爬出产卵刺激肛周所致，兼腹痛腹泻、恶心纳呆，属蛲虫病。肠道蛔虫病项见脐周疼痛、面色萎黄、寐中磨牙。胆道蛔虫病项见右上腹阵发性绞痛、剧烈呕吐。蛔厥证项见腹痛、四肢厥冷、呕吐蛔虫。钩虫病项见面黄浮肿、乏力、异嗜"},{"q":"患者，女，58岁。近半月来记忆力下降明显，自觉夜间眠浅梦多，白天头晕眼花，时有心悸。刻下：面色淡白、饮食一般，大便偏干，小便正常，唇、舌色淡，脉细弱。此属下列何证","o":["心阴虚证","心血虚证","心气虚证","心阳虚证","瘀阻脑络证"],"a":1,"e":"眠浅梦多、头晕眼花、心悸、面色淡白、唇舌色淡、脉细弱，为心血不足、心失所养、神不守舍。心阴虚证项见心烦潮热盗汗、舌红少苔。心气虚证项见心悸气短、乏力自汗，无面色唇舌淡白。心阳虚证项见胸闷畏寒肢冷。瘀阻脑络项见头痛如刺、舌紫暗"},{"q":"患者全身水肿，腰以下肿甚，腰膝酸冷，心悸气短，喉中痰鸣，小便短少，舌淡胖，苔白滑，脉沉涩无力，应诊断为","o":["肾阳虚","心阳虚","肺肾气虚证","肾虚水泛证","脾肾阳虚证"],"a":3,"e":"全身水肿腰以下甚、腰膝酸冷、心悸气短、喉中痰鸣、小便短少、舌淡胖苔白滑、脉沉涩无力，为肾阳亏虚、水液泛溢、上凌心肺。肾阳虚项以畏寒肢冷、腰膝酸冷、五更泄泻为主，水肿较轻。心阳虚项见心悸胸闷、唇甲青紫。肺肾气虚项见呼多吸少、动则喘甚。脾肾阳虚项见久泻便溏、腹部冷痛"},{"q":"患者，男，48岁。反复泄泻1个月余，自觉便意频数，肛门重坠，脘腹重坠作胀，食后尤甚，少气懒言，面色萎黄，形体消瘦，舌淡苔白，脉弱。可诊断为","o":["湿热蕴脾证","脾虚气陷证","胃阴虚证","寒滞胃脘证","胃肠气滞证"],"a":1,"e":"泄泻日久、便意频数、肛门重坠、脘腹重坠作胀、食后尤甚、少气懒言、面色萎黄、舌淡脉弱，为脾气虚弱、中气下陷、清阳不升。湿热蕴脾项见泻下黄糜、肛门灼热、苔黄腻。胃阴虚项见饥不欲食、舌红少津。寒滞胃脘项见胃脘冷痛、脉紧。胃肠气滞项见脘腹胀痛、走窜不定"},{"q":"患者，女，55岁。发热3周，午后及夜间热甚，伴见颧红盗汗，舌红少苔，脉细数，其发热类型属于","o":["湿温潮热","阴虚潮热","阳明潮热","气郁发热","气虚发热"],"a":1,"e":"发热3周、午后及夜间热甚、颧红盗汗、舌红少苔、脉细数，为阴液亏虚、虚火内扰、午后夜间阳气入阴而潮热。湿温潮热项见身热不扬、午后热甚、苔腻。阳明潮热项见日晡潮热、腹满硬痛、大便燥结。气郁发热项见情志抑郁、胸胁胀满、脉弦。气虚发热项见劳累后加重、少气自汗"},{"q":"患者，男，35岁。平素喜冷饮，夏夜在家中空调下睡觉，入睡时腹部未盖衣被，第二天晨起时见：胃脘冷痛，痛势急剧，恶心，纳差，舌淡苔白润，脉弦紧。诊为","o":["胃气虚证","胃阳虚证","寒滞胃脘证","胃阴虚证","食滞胃脘证"],"a":2,"e":"胃脘冷痛、痛势急剧、恶心纳差、舌淡苔白润、脉弦紧，因贪凉饮冷、寒邪直中胃脘、气机凝滞。胃气虚证项见胃脘隐痛、喜按、食少乏力，无明显冷痛。胃阳虚证项见胃脘冷痛绵绵、喜温喜按、病程长。食滞胃脘项见胀痛嗳腐、苔厚腻。胃阴虚证项见胃脘灼痛、舌红少苔"},{"q":"患者，男，52岁。嗜食肥甘厚味，平素爱逸少动，形体肥胖，2周前出现头重眩晕，胸脘痞闷，食欲欠佳，其舌苔可见","o":["黄燥","黄滑","薄白","淡黄","白腻"],"a":4,"e":"嗜食肥甘、形体肥胖、头重眩晕、胸脘痞闷、食欲欠佳，为痰湿内盛、困阻中焦，白腻苔主湿浊、痰饮、食积。黄燥苔主热盛伤津。黄滑苔主湿热或痰热。薄白苔为正常或表证。淡黄苔主里热轻证，均与痰湿内盛不符"},{"q":"患者，男，74岁。由于邪气亢盛，热扰神明，邪陷心包而出现失神，最可能表现为","o":["反应迟钝","手撒遗尿","骨枯肉脱","形体瘦弱","牙关紧急"],"a":4,"e":"邪气亢盛、热扰神明、邪陷心包所致失神属邪盛神乱，见神昏谵语、躁扰不宁、两手握固、牙关紧急。反应迟钝为精亏神衰之轻者。手撒遗尿为元气暴脱、脱证。骨枯肉脱、形体瘦弱为久病精气衰竭、虚证失神，均非邪盛表现"},{"q":"本已神志不清、不得言语的患者突然神志清醒，语言不休者属","o":["神志异常","无神","假神","有神","神气不足"],"a":2,"e":"久病神志不清、不能言语者突然神志清醒、语言不休，为精气衰竭、虚阳外越、回光返照的假神，是病情危重之象。无神项见精神萎靡、言语低微、反应迟钝。有神项见目光明亮、反应灵敏、语言清亮。神气不足项见精神不振、倦怠懒言，但不出现突然清醒。神志异常项泛指癫狂痫等表现"},{"q":"患者，女，32岁。平素嗜食辛辣，反复胃脘灼痛3个月余，渴喜冷饮，消谷善饥，大便秘结，小便短赤，舌红苔黄，脉滑数。诊为","o":["胃热炽盛证","寒滞胃脘证","肠燥津亏证","胃阴虚证","食滞胃脘证"],"a":0,"e":"胃脘灼痛、渴喜冷饮、消谷善饥、大便秘结、小便短赤、舌红苔黄、脉滑数，为胃中热盛、腐熟太过、津伤化燥。寒滞胃脘项见胃脘冷痛、脉紧。肠燥津亏项见大便干结、口干，无消谷善饥、胃脘灼痛。食滞胃脘项见胀痛嗳腐、苔厚腻。胃阴虚项见饥不欲食、舌红少苔"},{"q":"患者，男。1年前中风后左半身上下肢运动不便。现大便秘结，三日一行，临而努挣乏力，挣则汗出气短，便后疲乏，舌淡脉虚无力。证属","o":["表证","热证","亡阳证","虚证","寒证"],"a":3,"e":"大便秘结、努挣乏力、挣则汗出气短、便后疲乏、舌淡脉虚无力，为中气不足、大肠传导无力的虚秘，故属虚证。表证项见恶寒发热、脉浮。热证项见口渴喜冷、舌红苔黄、脉数。亡阳证项见冷汗淋漓、四肢厥冷、脉微。寒证项见畏寒肢冷、腹痛喜温、脉迟"},{"q":"患者2个月来时常发热，波动于37、3～38℃，午后发作，劳累后加重，少气懒言，常自汗出，易感冒，舌质淡白，苔薄白，脉弱。证属","o":["表证、热证、虚证","里证、热证、虚证","表证、寒证、虚证","里证、寒证、虚证","里证、热证、实证"],"a":1,"e":"发热、午后发作、劳累后加重、少气懒言、自汗易感冒、舌淡白苔薄白、脉弱，为气虚发热，病在里、性属热、本为虚。表证项应有恶寒发热并见、脉浮。寒证项应见畏寒喜温、脉迟。实证项见发热较高、脉实有力，与本例脉弱、劳累加重相反"},{"q":"患儿，男，2岁1个月。望诊眉间、鼻柱、唇周发青，辨证为","o":["阴虚","惊风","血瘀","肾虚","阳虚"],"a":1,"e":"小儿眉间、鼻柱、唇周发青，为肝风内动、惊风先兆，因小儿肝常有余、易受惊恐、筋脉拘急。阴虚项见潮热盗汗、舌红少苔、无青色。血瘀项见面色晦暗、舌紫暗、痛如针刺。肾虚项见囟门迟闭、发育迟缓、面色㿠白。阳虚项见面色㿠白、畏寒肢冷、舌淡胖"},{"q":"患者，男，67岁。身热不甚，口干咽燥，神倦耳聋，手足心热甚于手足背，舌绛干燥，其病机为","o":["肺胃阴伤","阴虚火炽","热伤心肾","燥干清窍","肾阴耗损"],"a":4,"e":"身热不甚、口干咽燥、神倦耳聋、手足心热甚于手足背、舌绛干燥，为热邪深入下焦、耗损肾阴、虚热内扰。肺胃阴伤项见口干咽燥、干咳、舌红少津，无耳聋、手足心热甚于背。阴虚火炽项见心烦不寐、口舌生疮、脉细数。热伤心肾项见神昏、惊悸。燥干清窍项见目赤咽痛、头胀"},{"q":"患者发热，其手心热甚于额上，多为","o":["表热","里热","实热","虚热","郁热"],"a":1,"e":"手心热甚于额上，为热自内发、里热炽盛、阳气内郁；额上热甚于手心则为外感表热。表热项见发热恶寒、头痛、脉浮。实热项见壮热烦渴、脉洪数有力，为里热实证，但非手心额上之辨。虚热项见潮热盗汗、五心烦热、脉细数。郁热项见胸胁胀满、情志抑郁、脉弦数"},{"q":"患者平素性急易怒，时有胁胀，近日胁胀加重，伴食欲不振，食后腹胀，便溏，舌淡苔薄白，脉弦。其证候是","o":["脾气虚","脾阳虚","脾肾阳虚","肝脾不调","肝胃不和"],"a":3,"e":"性急易怒、胁胀为肝气郁结，食欲不振、食后腹胀、便溏、舌淡苔薄白、脉弦为脾虚失运，肝郁脾虚故属肝脾不调。脾气虚项仅有纳差便溏乏力，无胁胀脉弦。肝胃不和项见胃脘胀痛、嗳气吞酸，无便溏。脾阳虚项见腹痛喜温喜按、畏寒肢冷。脾肾阳虚项见五更泄泻、腰膝酸冷"},{"q":"患者平素畏寒肢冷，腹痛喜温喜按，小便清长，今起恶寒重发热轻，头痛无汗，流清涕，舌淡胖，脉濡缓，是","o":["表实寒里虚热","表实热里虚寒","表实寒里虚寒","表实热里虚热","表实里实寒证"],"a":2,"e":"恶寒重发热轻、头痛无汗、流清涕为外感风寒、腠理闭塞的表实寒证；平素畏寒肢冷、腹痛喜温喜按、小便清长、舌淡胖为脾肾阳虚里虚寒。表实热项见发热重恶寒轻、口渴咽痛。里虚热项见潮热盗汗、舌红少苔。表实里实寒项里证亦为实，无喜温喜按、脉虚之象"},{"q":"患者，女，23岁。心烦失眠1个月。患者因最近与同事发生矛盾，心情烦躁，入夜难以入睡，自觉手足心发热，口干欲饮，但所饮不多，舌红苔薄而干，脉细数。其证候是","o":["心阴虚证","肝阴虚证","心火上炎证","肝火上炎证","肝气郁结证"],"a":0,"e":"心烦失眠、手足心热、口干欲饮不多、舌红苔薄而干、脉细数，为心阴亏虚、虚热内扰、心神不宁。肝阴虚证项见头晕目涩、胁痛、脉弦细数。心火上炎证项见口舌生疮、小便短赤、舌尖红赤、脉数有力。肝火上炎证项见目赤口苦、急躁易怒、脉弦数。肝气郁结证项见胁胀太息、脉弦，无虚热"},{"q":"患者，男，46岁。腹痛腹泻2天，日泻10余次水便，经治已缓，目前口渴心烦，皮肤干瘪，眼窝凹陷，舌淡白苔薄黄，脉细无力。其证候是","o":["津亏","阴虚","亡阳","外燥","实热"],"a":0,"e":"暴泻之后口渴心烦、皮肤干瘪、眼窝凹陷、舌淡白苔薄黄、脉细无力，为剧烈吐泻、津液大量丢失的津亏证。阴虚项见潮热盗汗、舌红少苔，起病缓。亡阳项见冷汗淋漓、四肢厥冷、脉微。外燥项见口鼻干燥、干咳少痰、发病与季节相关。实热项见壮热烦渴、脉洪数有力"},{"q":"患者，男，45岁。突发耳鸣，声大如潮，按之不减，舌红苔黄，脉弦数，病机为","o":["阴虚火旺","肝胆火盛","肝肾阴虚","肾精亏损","心火亢盛"],"a":1,"e":"突发耳鸣、声大如潮、按之不减、舌红苔黄、脉弦数，为肝胆火旺、循经上扰耳窍，属实证。阴虚火旺项见耳鸣日渐、声细、夜间加重、腰膝酸软。肝肾阴虚项见头晕目涩、耳鸣如蝉、舌红少苔。肾精亏损项见耳鸣耳聋、发脱齿摇、小儿五迟。心火亢盛项见心烦失眠、口舌生疮，无耳鸣"},{"q":"患者，男，65岁。突然昏倒，口吐涎沫，两目上视，四肢抽搐，醒后如常，辨证为","o":["癫证","狂证","痫证","中风","中暑"],"a":2,"e":"突然昏倒、口吐涎沫、两目上视、四肢抽搐、醒后如常，为风痰上扰、蒙蔽心窍的痫证，发作性、反复性为特点。癫证项见表情淡漠、喃喃自语、静而少动。狂证项见狂躁妄动、打骂他人。中风项见突然昏仆、口眼歪斜、半身不遂，醒后不能如常。中暑项有高温环境、发热汗多"},{"q":"患者，女，38岁。近1个月来失眠反复发作，自觉眠浅、梦多，入睡尤难，时有心悸，甚则头晕眼花，自购“枣仁胶囊”服用，无明显好转。刻下：纳可，二便尚调，面色萎黄，唇、舌色淡，脉细无力。此属下列何证","o":["心阴虚证","心阳虚证","心气虚证","心血虚证","心火上炎证"],"a":3,"e":"眠浅梦多、入睡难、心悸、头晕眼花、面色萎黄、唇舌色淡、脉细无力，为心血不足、神失所养。心阴虚证项见心烦潮热、盗汗、舌红少苔。心阳虚证项见心悸胸闷、畏寒肢冷、舌淡胖。心气虚证项见心悸气短、自汗乏力。心火上炎证项见口舌生疮、舌尖红、脉数"},{"q":"最易导致太息的是","o":["肝风内动","肝气虚弱","肝气郁结","肝阳上亢","脾气虚弱"],"a":2,"e":"太息即善太息，为肝气郁结、气机不畅、胸中闷胀，叹气后稍舒。肝风内动项见眩晕欲仆、肢麻震颤、抽搐。肝气虚弱项见胁肋隐痛、乏力、目糊，无太息。肝阳上亢项见头胀痛、面红目赤、腰膝酸软。脾气虚弱项见纳差便溏、乏力，无太息、脉弦"},{"q":"患者肢沉身困，关节酸胀重着，舌淡边有齿痕，脉濡，宜诊断为","o":["伤湿","冒湿","湿痹","湿温","湿疹"],"a":2,"e":"肢沉身困、关节酸胀重着、舌淡边有齿痕、脉濡，为湿邪痹阻关节、气血运行不畅的湿痹，以重着酸痛、固定不移为特点。伤湿项见头身困重、胸闷脘痞，无关节痹痛。冒湿项见头重如裹、首如蒙物。湿温项见身热不扬、午后热甚。湿疹项见皮肤瘙痒、皮疹渗出"},{"q":"患者咯痰少而黏难出，口干舌燥，属","o":["热痰","燥痰","风痰","湿痰","寒痰"],"a":1,"e":"咯痰少而黏难出、口干舌燥，为燥邪伤肺、津液亏耗、炼液成痰的燥痰。热痰项痰黄稠、面红口渴、脉数。风痰项痰白泡沫、伴眩晕肢麻或外风表证。湿痰项痰白量多易咯、胸闷脘痞、苔白腻。寒痰项痰白清稀、畏寒肢冷、舌淡苔白"},{"q":"患者，男，45岁。突然四肢浮肿，按之凹陷，小便短少不利，周身困重，舌淡胖，苔白滑，脉缓，辨证为","o":["亡阳证","水停证","饮证","痰证","津液亏虚证"],"a":1,"e":"四肢浮肿、按之凹陷、小便短少不利、周身困重、舌淡胖苔白滑、脉缓，为水液代谢障碍、水湿泛溢肌肤的水停证。亡阳证项见冷汗淋漓、四肢厥冷、脉微。饮证项见脘腹痞满、呕吐清涎、肠鸣沥沥、咳唾引痛。痰证项见咳痰量多、胸闷、苔腻、脉滑。津液亏虚项见口干咽燥、皮肤干瘪、舌红少津"},{"q":"心悸怔忡，面色萎黄，神疲乏力，纳少便溏，脉象细弱，辨证应为","o":["心气不足证","心血不足证","脾气血证","心肝血虚证","心脾两虚证"],"a":4,"e":"心悸怔忡、面色萎黄、神疲乏力，兼纳少便溏、脉细弱，为心血不足、脾气虚弱、气血生化不足、心失所养。心气不足证项见心悸气短、自汗乏力，无便溏、面色萎黄。心血不足证项见心悸失眠、面白舌淡，无脾虚纳呆便溏。心肝血虚证项见目涩爪甲不荣、肢体麻木。脾气血证表述不规范，非标准证型"},{"q":"患者恶寒发热，头身疼痛，无汗，鼻塞流涕，脉浮紧，其舌苔对应是","o":["白厚","薄白","黄腻","花剥","白腻"],"a":1,"e":"恶寒发热、头身疼痛、无汗、鼻塞流涕、脉浮紧，为外感风寒表实证，邪在表、寒邪未化热，舌苔薄白。白厚苔主里寒湿或食积。黄腻苔主湿热内蕴。花剥苔主胃气阴两伤。白腻苔主寒湿、痰饮内停，均非风寒表证之苔"},{"q":"患者，女，55岁。身体灼热，烦躁不安，斑疹显露，甚或吐血、衄血，舌质红绛，脉弦数，其临床意义是","o":["血分实热","热扰心神","热郁胆经","热灼营阴","血分虚热"],"a":0,"e":"身体灼热、烦躁不安、斑疹显露、吐血衄血、舌质红绛、脉弦数，为热入血分、迫血妄行、血分实热。热扰心神项见神昏谵语、烦躁，无斑疹出血。热灼营阴项见身热夜甚、口干不欲饮、斑疹隐隐、舌绛。血分虚热项见潮热、出血量少、脉细数。热郁胆经项见口苦胁痛、寒热往来、脉弦"},{"q":"患者恶风，汗出，色淡苔白，脉浮缓，宜诊断为","o":["风淫证","暑淫证","燥淫证","火淫证","湿淫证"],"a":0,"e":"恶风、汗出、舌淡苔白、脉浮缓，为风邪袭表、卫气不固、营卫不和的风淫证（表虚）。暑淫证项见发热烦渴、汗多、气短乏力、脉虚。燥淫证项见口鼻干燥、干咳少痰、苔薄黄。火淫证项见高热烦渴、舌红苔黄、脉数。湿淫证项见头身困重、胸闷脘痞、苔腻、脉濡"},{"q":"患者，男，25岁。咳喘，胸痛，痰黄黏稠，胸痛，舌红苔黄，脉数，其辨证为","o":["热扰心神","风热犯肺","热郁胆经","热邪壅肺","燥热犯肺"],"a":3,"e":"咳喘、胸痛、痰黄黏稠、舌红苔黄、脉数，为热邪壅滞于肺、肺气上逆、炼液成痰。风热犯肺项见咳嗽咽痛、发热恶寒、脉浮数，表证明显。热扰心神项见神昏谵语、烦躁不安。热郁胆经项见口苦胁痛、寒热往来。燥热犯肺项见干咳少痰、口鼻干燥，痰不黄稠"},{"q":"患者，女，31岁。3年来怀孕3次，均不足3个月而流产，听力减退，带下清稀，腰部酸痛，舌淡苔白，脉弱。其证候是","o":["肾气不固","肾精不足","肾阳虚","脾气下陷","脾肾阳虚"],"a":0,"e":"三次流产、听力减退、带下清稀、腰部酸痛、舌淡苔白、脉弱，为肾气亏虚、封藏失职、冲任不固、胎元不固。肾精不足项见小儿五迟、成人早衰、发脱齿摇，无滑胎带下清稀。脾气下陷项见久泻脱肛、内脏下垂。肾阳虚项见畏寒肢冷、腰膝冷痛、五更泄泻。脾肾阳虚项见畏寒、久泻、完谷不化"},{"q":"患者咳嗽，咯痰黄稠，口干咽痛，发热微恶寒，舌红苔薄黄，脉数，应辨证为","o":["风热表证","风热犯肺证","肺热炽盛证","痰热壅肺证","燥邪犯肺"],"a":1,"e":"咳嗽、痰黄稠、口干咽痛、发热微恶寒、舌红苔薄黄、脉数，为风热犯肺、肺气上逆、热邪伤津，表证较轻。风热表证项以发热重、微恶寒、咽痛、脉浮数为主，咳嗽不突出。肺热炽盛项见高热咳喘、痰黄量多、苔黄。痰热壅肺项见痰黄稠量多、胸闷、喉间痰鸣、苔黄腻。燥邪犯肺项见干咳少痰、口鼻干燥"},{"q":"患者咳嗽反复发作5年，气短胸闷，吐痰量多白黏，神疲食少，舌淡胖，苔白腻，脉弱，证属","o":["表邪入里","表里同病","虚实夹杂","实证转虚","虚证转实"],"a":2,"e":"咳喘5年、气短胸闷、神疲食少、舌淡胖脉弱为肺脾气虚；吐痰量多白黏、苔白腻为痰湿内停，正虚邪实并见，属虚实夹杂。表邪入里项应有表证入里的传变过程。表里同病项须同时见表证与里证。实证转虚项为先实后虚、邪退正虚。虚证转实项为正虚基础上邪实加重"},{"q":"心悸怔忡，畏寒，尿少肢肿，唇甲青紫，舌淡紫，脉弱，宜诊断为","o":["瘀阻心脉证","肾阳虚证","心肾阳虚证","心脉痹阻证","心阳虚证"],"a":2,"e":"心悸怔忡、畏寒、尿少肢肿、唇甲青紫、舌淡紫、脉弱，为心肾阳气亏虚、水液代谢失常、水气凌心、血脉瘀滞。瘀阻心脉证项见心前区刺痛、痛引肩背、舌紫暗、脉涩，无尿少肢肿、畏寒。肾阳虚证项见腰膝酸冷、五更泄泻，无心悸。心阳虚证项见心悸胸闷、畏寒肢冷，水肿不显。心脉痹阻项痛如针刺、固定不移"},{"q":"寒热往来，胸胁苦满，心烦喜呕，默默不欲饮食，口苦咽干，证属半表半里，最常见的脉象是","o":["浮脉","滑脉","弦脉","沉脉","涩脉"],"a":2,"e":"寒热往来、胸胁苦满、心烦喜呕、口苦咽干，为邪郁少阳、枢机不利，弦脉主肝胆病、少阳证、疼痛、痰饮，故最常见弦脉。浮脉主表证。滑脉主痰饮、食滞、妊娠。沉脉主里证。涩脉主气滞血瘀、精伤血少，均非少阳主脉"},{"q":"患者，男，65岁。自诉头胀头痛，伴有眩晕，自觉腰酸膝软，头重脚轻，步履不稳，面红目赤，平素性情急躁易怒，舌红少津，脉弦细而数。辨证属","o":["肝阴虚证","肝火炽盛证","肝胆湿热证","肝阳上亢证","肝风内动证"],"a":4,"e":"头胀头痛、眩晕、面红目赤、急躁易怒、腰膝酸软、头重脚轻，兼步履不稳、舌红少津、脉弦细数，为肝肾阴亏、肝阳化风、上实下虚，属肝风内动。肝阳上亢项见头晕胀痛、面红目赤、腰膝酸软，但无步履不稳等动风之象。肝火炽盛项见目赤口苦、便秘尿黄、脉弦数有力。肝胆湿热项见胁痛口苦、苔黄腻。肝阴虚项见目涩、胁痛、潮热，无上亢动风"},{"q":"患者，女，20岁。发热恶寒，鼻塞，胸闷，咳嗽，头痛，舌边尖红，属","o":["上焦病变","中焦阳明燥热","下焦病变","上焦逆传心包","中焦太阴湿热"],"a":0,"e":"发热恶寒、鼻塞、胸闷、咳嗽、头痛、舌边尖红，为风热犯肺、肺气失宣，病位在上焦肺卫。中焦阳明燥热项见壮热烦渴、腹满便秘、苔黄燥。下焦病变项见身热颧红、手足心热、舌绛。上焦逆传心包项见神昏谵语、舌绛、肢厥。中焦太阴湿热项见身热不扬、脘痞、苔黄腻"},{"q":"患者咳嗽气喘，胸闷痛，喉间痰鸣，痰黄稠量多，身热烦躁，口渴，尿黄便秘，舌红苔黄腻，考虑痰热壅肺，最可能的脉象是","o":["洪大脉","滑数脉","浮数脉","浮紧脉","沉数脉"],"a":1,"e":"痰热壅肺见咳嗽气喘、喉间痰鸣、痰黄稠量多、苔黄腻，滑脉主痰饮，数脉主热，故为滑数脉。洪大脉主阳明经热、气分热盛。浮数脉主风热表证。浮紧脉主风寒表实。沉数脉主里热，均不若滑数之痰热特征"},{"q":"患儿，3岁。面黄肌瘦，肚腹膨胀，毛发稀疏，发结如穗，易烦躁激动，睡眠不宁，多食多便，舌淡，苔薄腻，脉沉细。宜诊断为","o":["疳气","疳积","干疳","慢脾风","佝偻病"],"a":1,"e":"面黄肌瘦、肚腹膨胀、毛发稀疏、发结如穗、烦躁易怒、睡眠不宁、多食多便，为疳证日久、脾胃受损、积滞内停、气血亏虚的疳积。疳气项见形体略瘦、面色少华、食欲不振，症状较轻。干疳项见极度消瘦、皮肤干皱、精神萎靡、大肉尽脱。慢脾风项见沉睡、肢冷、抽搐。佝偻病见骨骼改变、囟门迟闭"},{"q":"患者，女，37岁。3年来经常疲乏无力，腹胀便溏，月经提前量多，每至10余日方止。近1年来经常心悸失眠，头晕健忘，面色萎黄，形体消瘦，舌淡苔白，脉弱。其心悸的病机是","o":["肝血亏虚","心肾不交","脾不统血","心血亏虚","心胆气虚"],"a":3,"e":"心悸失眠、头晕健忘、面色萎黄、形体消瘦、舌淡苔白脉弱，为心血不足、心失所养，故心悸病机为心血亏虚。肝血亏虚项见目涩爪甲不荣、月经量少。心肾不交项见心烦失眠、腰酸潮热、舌红少苔。脾不统血项以月经量多、出血为主，为心悸之因而非心悸本身病机。心胆气虚项见惊悸善恐、气短自汗"},{"q":"患者左侧乳房有形如鸡卵的硬结肿块，边界清楚，表面光滑，推之活动而不痛者，多为","o":["乳核","乳痨","乳癖","乳癌","乳疬"],"a":0,"e":"乳房鸡卵形硬结、边界清楚、表面光滑、推之活动、不痛，为乳核，多见于青年女性。乳癖项见乳房肿块随月经周期变化、经前胀痛。乳癌项肿块质硬、边界不清、固定不移、无痛、腋窝淋巴结肿大。乳痨项见乳房结块、溃后脓液稀薄如痰、病程长。乳疬项见于儿童或老年男性乳晕下结节"},{"q":"心悸健忘，失眠多梦，头晕目眩，两目干涩，肢体麻木，月经量少，色淡，甚则经闭，面白无华，爪甲不荣，舌淡脉细。宜诊断为","o":["心血虚证","肝血虚证","心肝血虚证","血虚证","心脾两虚证"],"a":2,"e":"心悸健忘失眠、头晕目眩，兼两目干涩、肢体麻木、月经量少色淡、爪甲不荣、面白无华、舌淡脉细，为心血与肝血俱虚。心血虚证项仅有心悸失眠、面白，无目涩、肢麻、月经量少。肝血虚证项见目涩、爪甲不荣、月经量少，无心悸健忘。血虚证项范围笼统，未定位心肝。心脾两虚证项见心悸健忘、纳差便溏"},{"q":"患者，男，31岁。几天前突发恶寒、寒战，继而又出现高热，每天下午3点左右反复发作，此症状多见于","o":["少阳病","湿温","疟疾","瘟疫","肺痈"],"a":2,"e":"恶寒寒战与高热交替、每日下午3时左右定时发作、反复往来，为疟邪伏于半表半里、正邪交争的疟疾，寒热定时反复为特征。少阳病项见寒热往来、胸胁苦满、口苦咽干，发作无定时。湿温项见身热不扬、午后热甚、缠绵难愈。瘟疫项起病急骤、传染性强。肺痈项见发热胸痛、咳吐腥臭脓血"},{"q":"患者，女，20岁。发热恶风寒，头痛少汗，口干不渴，心烦谵语，舌红绛少苔，脉浮细数，其病变属于","o":["卫分证","气分证","营分证","气营同病","卫营同病"],"a":4,"e":"发热微恶寒、头痛、脉浮为邪在卫分；口干不渴、心烦谵语、舌红绛少苔为热入营分，卫分与营分同时并见，属卫营同病。卫分证项仅见发热恶寒、头痛、苔薄白，无谵语舌绛。气分证项见壮热烦渴、苔黄燥。气营同病项见壮热烦渴、神昏谵语、舌绛。营分证项见身热夜甚、斑疹隐隐，无恶寒头痛"},{"q":"患者，男，36岁。患胃病多年，今晚突然大量吐血，面唇俱白，冷汗淋漓，呼吸微弱，神志欠清，舌淡，脉浮大而散。临床诊断最可能是","o":["气不摄血证","气血两虚证","气随血脱证","亡阳证","亡阴证"],"a":2,"e":"大量吐血后面唇俱白、冷汗淋漓、呼吸微弱、神志欠清、舌淡、脉浮大而散，为血脱气亦随脱、气欲暴脱的危候。气不摄血证项见慢性出血、神疲乏力、舌淡脉弱，无冷汗、脉散。气血两虚证项见面色萎黄、乏力心悸，起病缓。亡阳证项见冷汗淋漓、四肢厥冷、脉微欲绝。亡阴证项见汗热味咸、烦躁、脉疾无力"},{"q":"患者，男，45岁。失眠反复发作3个月。平素时有心烦，口干，饮水较多；近来口舌糜烂，灼热疼痛，便秘，尿黄，舌尖红绛，苔黄，脉数有力。此属下列何证","o":["心阴虚证","胃阴虚证","心肾不交证","胃火炽盛证","心火亢盛证"],"a":4,"e":"心烦失眠、口舌糜烂灼痛、便秘尿黄、舌尖红绛、苔黄、脉数有力，为心火内盛、循经上炎、灼伤津液。心阴虚证项见心烦失眠、盗汗、舌红少苔、脉细数，无口舌糜烂、脉数有力。胃火炽盛项见牙龈肿痛、口臭、消谷善饥。心肾不交项见心烦失眠、腰酸潮热、舌红少苔。胃阴虚项见饥不欲食、舌红少津"},{"q":"患者，女，36岁，已婚，面色萎黄，神疲乏力，气短懒言，食少便溏，月经淋漓不断，经血色淡，舌淡无苔，脉沉细无力。其病机","o":["脾不统血","脾肾阳虚","气血两虚","脾肺气虚","肝血不足"],"a":0,"e":"面色萎黄、神疲乏力、气短懒言、食少便溏、月经淋漓不断色淡、舌淡无苔、脉沉细无力，为脾气虚弱、不能统摄血液、血溢脉外。脾肾阳虚项见畏寒肢冷、腰膝酸冷、五更泄泻。气血两虚项见面白乏力、心悸头晕，无明确出血。脾肺气虚项见咳嗽气短、痰多清稀。肝血不足项见目涩、肢体麻木、月经量少"},{"q":"患者右侧乳房触及无痛性肿块，质硬，形状不规则，边界不清，不易推动，腋窝多可扪及肿块，应考虑","o":["乳核","乳痨","乳癖","乳癌","乳疬"],"a":3,"e":"乳房无痛性肿块、质硬、形状不规则、边界不清、不易推动、腋窝淋巴结肿大，为乳癌，属痰瘀互结、毒邪内蕴。乳核项肿块边界清楚、表面光滑、推之活动、不痛。乳癖项肿块随月经周期变化、经前胀痛。乳痨项见结块、溃后稀薄如痰脓、病程长。乳疬项见乳晕下小肿块、推之可移，多见于儿童或老年男性"},{"q":"患者眩晕耳鸣，头目胀痛，面红目赤，急躁易怒，腰膝酸软，头重足轻，舌红，脉弦细数。其证候是","o":["肝火上炎","肝阳上亢","肝阴不足","肝气郁结","肝阳化风"],"a":1,"e":"眩晕耳鸣、头目胀痛、面红目赤、急躁易怒、腰膝酸软、头重足轻、舌红脉弦细数，为肝肾阴虚于下、肝阳亢逆于上的肝阳上亢。肝火上炎项见目赤口苦、便秘尿黄、脉弦数有力，无腰膝酸软、头重足轻。肝阴不足项见目涩胁痛、潮热盗汗，无头目胀痛、面红目赤。肝气郁结项见胁胀太息、脉弦。肝阳化风项见眩晕欲仆、肢麻震颤"},{"q":"患者齿龈微肿出血，伴龈肉萎缩，牙根宣露，齿摇不坚，伴有头晕，耳鸣，手足心热，腰酸，舌质微红，少苔，脉细数，最宜辨证为","o":["胃火炽盛","脾虚失摄","痰湿凝聚","肝胆火旺","肾阴亏损"],"a":4,"e":"齿龈微肿出血、龈肉萎缩、牙根宣露、齿摇不坚，兼头晕耳鸣、手足心热、腰酸、舌微红少苔、脉细数，为肾阴亏虚、虚火上炎、齿失所养。胃火炽盛项见牙龈红肿疼痛、口臭、消谷善饥、苔黄厚。脾虚失摄项见齿龈出血、面色萎黄、乏力、舌淡。痰湿凝聚项见龈肿、苔腻、脉滑。肝胆火旺项见口苦胁痛、脉弦数"},{"q":"咳嗽痰少带血，体瘦，咽干，颧红，遗精，耳鸣，舌红少苔。宜诊断为","o":["肺燥津亏证","肺胃阴虚证","血热证","肝火犯肺证","肺肾阴虚证"],"a":4,"e":"咳嗽痰少带血、体瘦咽干、颧红、遗精耳鸣、舌红少苔，为肺肾阴液亏虚、虚火上炎、肺络受损、肾失封藏。肺燥津亏项见干咳少痰、口鼻干燥，无颧红、遗精、耳鸣。肺胃阴虚项见干咳、饥不欲食、舌红少津。血热证项见咳血鲜红、心烦、脉数。肝火犯肺项见咳血、胁肋灼痛、脉弦数"},{"q":"患者恶寒发热3日，今日起恶寒消失，高热恶热，口渴喜饮，舌红苔黄，脉洪数，证属","o":["表寒里热","风热犯肺","表热里寒","热证化寒","表邪入里"],"a":4,"e":"初起恶寒发热为表证，今日恶寒消失、高热恶热、口渴喜饮、舌红苔黄、脉洪数，为表邪入里化热、里热炽盛。表寒里热项见恶寒发热与口渴烦躁并见，表证未罢。风热犯肺项见发热恶寒、咳嗽咽痛、脉浮数。表热里寒项见表热与里寒并见。热证化寒项见热象消退、寒象显现，与本题相反"},{"q":"患者，男，48岁。症见身热，心烦，口苦，咽干，胸胁满痛，时有干呕，舌红，脉弦数，其临床意义是","o":["热结肠腑","热扰心神","热郁胆经","热扰胸膈","热邪壅肺"],"a":2,"e":"身热心烦、口苦咽干、胸胁满痛、时有干呕、舌红脉弦数，为邪热郁于胆经、胆气上逆、经气不利。热结肠腑项见潮热谵语、腹满硬痛、大便不通。热扰心神项见神昏谵语、烦躁不安。热扰胸膈项见心烦懊憹、胸膈痞闷。热邪壅肺项见咳喘、痰黄稠、胸痛"},{"q":"患者1周来泻下黄糜，排便不爽，气味臭秽，肛门灼热，病机为","o":["食滞肠胃","肝胆湿热","大肠湿热","脾胃虚弱","肾阳虚衰"],"a":2,"e":"过食辛辣肥甘后腹痛、泻下急迫不爽、粪色黄褐臭秽、肛门灼热、小便短黄、舌红苔黄腻、脉濡数，为湿热蕴结大肠、传导失司。肝胃不和项见胃脘胀痛、胁胀、嗳气。胃火炽盛项见胃脘灼痛、口臭、消谷善饥。湿客胃肠项见脘腹痞闷、恶心、便溏，热象不显。肝脾不调项见胁胀、腹痛即泻、泻后痛减"},{"q":"患者头项强痛、恶寒发热、四肢关节微痛、呕吐、胸胁苦闷，其证属","o":["少阴兼阳明病证","太阳兼少阳病证","太阳兼阳明病证","太阳病证","阳明病证"],"a":1,"e":"头项强痛、恶寒发热、四肢关节微痛为太阳表证；呕吐、胸胁苦闷为少阳枢机不利、胆气犯胃，两经并病属太阳兼少阳。少阴兼阳明项见脉微细、但欲寐与腹满便秘并见。太阳兼阳明项见恶寒发热与口渴、腹满硬痛、大便不通。单纯太阳病项无呕吐、胸胁苦满。阳明病项见但热不寒、大汗、脉洪大"},{"q":"患者，45岁。近1个月口渴多饮，小便量多，多食易饥，体渐消瘦，属","o":["阳明经证","痰饮内停","温病营分证","消渴病","里热炽盛"],"a":3,"e":"口渴多饮、小便量多、多食易饥、体渐消瘦，为消渴三多一少，因阴津亏损、燥热偏盛。阳明经证项见身大热、大汗、口大渴、脉洪大，无多尿消瘦。痰饮内停项见胸闷脘痞、呕吐清涎、苔白腻。温病营分证项见身热夜甚、神昏谵语、舌绛。里热炽盛项见壮热烦渴、苔黄燥、脉数，无多食消瘦"},{"q":"患者语无伦次，举止失常，甚则精神狂乱，哭笑无常，宜诊断为","o":["喜伤证","忧伤证","思伤证","悲伤证","恐伤证"],"a":0,"e":"语无伦次、举止失常、甚则精神狂乱、哭笑无常，为喜乐过度、心气涣散、神明失守的喜伤证，喜伤心、喜则气缓。忧伤证项见愁眉苦脸、叹息、气短。悲伤证项见面色惨淡、时时流泪、气短乏力。思伤证项见神情呆滞、纳差、失眠。恐伤证项见心悸胆怯、坐卧不安、二便失禁"},{"q":"患者昨夜起发热微恶寒，口干微渴，咳嗽，咽喉红肿疼痛，舌边尖红，脉浮数。证属","o":["表热证","表虚证","半表半里证","风寒束肺","表寒证"],"a":0,"e":"发热微恶寒、口干微渴、咳嗽、咽喉红肿疼痛、舌边尖红、脉浮数，为风热犯表、卫气失宣的表热证。表虚证项见恶风汗出、脉浮缓。半表半里证项见寒热往来、胸胁苦满、口苦咽干。风寒束肺项见咳嗽痰白清稀、恶寒重、无汗、脉浮紧。表寒证项见恶寒重发热轻、无汗、脉浮紧、苔薄白"},{"q":"患者，女，35岁。反复胃脘隐痛10年，现症见：胃脘隐隐灼痛，饥不欲食，口燥咽干，大便干结，舌红少津，脉细数。诊为","o":["寒滞胃脘证","胃阴虚证","胃热炽盛证","肠燥津亏证","食滞胃脘证"],"a":1,"e":"胃脘隐隐灼痛、饥不欲食、口燥咽干、大便干结、舌红少津、脉细数，为胃阴亏虚、虚热内生、胃失濡养。寒滞胃脘项见胃脘冷痛、喜温、脉紧。胃热炽盛项见胃脘灼痛、消谷善饥、口臭、苔黄。肠燥津亏项见大便干结、口干，无胃脘灼痛、饥不欲食。食滞胃脘项见胀痛嗳腐、苔厚腻"},{"q":"张某，女，41岁。近２个月来双目干涩不适，视物昏花，头晕，面白无华，月经量少，眼睑色淡，舌淡苔白，脉细弱。其目涩的病机为","o":["肝肾阴虚","肝血不足","肝阴不足","心血不足","肾精不足"],"a":1,"e":"双目干涩、视物昏花、头晕、面白无华、月经量少、眼睑色淡、舌淡脉细弱，为肝血亏虚、目失所养，肝开窍于目、肝藏血。肝肾阴虚项见目涩、腰膝酸软、潮热盗汗、舌红少苔。肝阴不足项见目涩、胁痛、舌红少津，无面白、月经量少。心血不足项见心悸失眠、面白。肾精不足项见早衰、发脱齿摇、小儿五迟"},{"q":"患者恶热，汗出口渴，疲乏，尿黄，舌红苔白，脉虚，宜诊断为","o":["风淫证","暑淫证","燥淫证","火淫证","湿淫证"],"a":1,"e":"恶热、汗出、口渴、疲乏、尿黄、舌红苔白、脉虚，为暑热伤气耗津、暑性升散、腠理开泄的暑淫证。风淫证项见恶风汗出、脉浮缓。燥淫证项见口鼻干燥、干咳少痰。火淫证项见高热烦渴、舌红苔黄、脉数有力。湿淫证项见头身困重、胸闷脘痞、苔腻、脉濡"},{"q":"患者带下清稀量多，腰膝酸软，尿频，神疲乏力，舌淡脉弱，宜诊断为","o":["肾气不固证","脾肾阳虚证","肾阳虚证","寒湿困脾证","脾阳虚证"],"a":0,"e":"带下清稀量多、腰膝酸软、尿频、神疲乏力、舌淡脉弱，为肾气不足、封藏失职、冲任不固、膀胱失约。脾肾阳虚项见畏寒肢冷、久泻便溏、完谷不化。肾阳虚项见腰膝冷痛、畏寒肢冷、五更泄泻。寒湿困脾项见带下量多色白、脘腹痞闷、苔白腻。脾阳虚项见食少便溏、腹痛喜温喜按"},{"q":"患者，男，40岁。平素体壮，2日前出现咳嗽、气喘，咽喉红肿疼痛，口渴，小便短赤，大便秘结，舌红苔黄，脉数。辨证为","o":["燥邪犯肺证","痰热壅肺证","风热犯肺证","肺热炽盛证","肺阴虚证"],"a":3,"e":"咳嗽气喘、咽喉红肿疼痛、口渴、小便短赤、大便秘结、舌红苔黄、脉数，为肺中热盛、气机上逆、津伤化燥。燥邪犯肺项见干咳少痰、口鼻干燥，无咽痛便秘。痰热壅肺项见痰黄稠量多、胸闷、喉间痰鸣、苔黄腻。风热犯肺项见发热恶寒、咽痛、脉浮数，表证明显。肺阴虚项见干咳少痰、潮热盗汗、舌红少苔"},{"q":"患者神疲懒言，嗜睡体倦，气短乏力，多考虑","o":["劳力过度","劳神过度","房劳过度","过逸少动","情志损伤"],"a":0,"e":"神疲懒言、嗜睡体倦、气短乏力，为劳力过度、耗伤气血、脾气虚弱、清阳不升。劳神过度项见心悸健忘、失眠多梦、思虑伤脾。房劳过度项见腰膝酸软、头晕耳鸣、遗精、月经不调。过逸少动项见形体虚胖、气血运行不畅、乏力困倦，多无气短懒言。情志损伤项见胸闷胁胀、情志抑郁、脉弦"},{"q":"患者反复咳喘10年，叩诊肺下界上移，应考虑","o":["肺痨","肺痿","肺痈","肺胀","肺热"],"a":1,"e":"反复咳喘10年、肺下界上移，为久咳耗伤肺气、肺叶痿弱不用、肺体萎缩的肺痿。肺痨项见咳嗽咯血、潮热盗汗、消瘦。肺痈项见发热胸痛、咳吐腥臭脓血。肺胀项见胸部膨隆、肺下界下移、桶状胸，与上移相反。肺热项见咳喘痰黄、发热，无肺界改变"},{"q":"热扰神明引起的呕吐多表现为","o":["呕声微弱，吐势较徐缓","呕声壮厉，吐势较猛","呈喷射状呕吐","吐利，腹痛并作","朝食暮吐或暮食朝吐"],"a":2,"e":"热扰神明、颅内压增高，呕吐多呈喷射状、吐势急促。吐势较缓多属脾胃虚弱；吐利并作多属霍乱或胃肠湿热；朝食暮吐为胃反；呕吐脓血为热毒伤络或痈疡"},{"q":"患者项强，伴高热神昏，抽搐，舌红绛，脉弦数，多属","o":["风寒侵袭","热极生风","肾精亏损","阳亢化风","精气衰竭"],"a":1,"e":"项强、高热神昏、抽搐、舌红绛、脉弦数，为邪热炽盛、燔灼肝经、筋脉失养、热极生风。风寒侵袭项见项强、恶寒发热、无汗、脉浮紧，无高热神昏抽搐。肾精亏损项见小儿五迟、成人早衰、骨弱无力。阳亢化风项见眩晕欲仆、肢麻震颤、脉弦长有力，无高热。精气衰竭项见形体消瘦、精神萎靡、脉微弱"},{"q":"患者，女，49岁。心悸，胸闷，气短3年，近日心前区刺痛，痛引左肩部、舌紫黯，脉涩。临床诊断最可能是","o":["气滞血瘀证","气虚血瘀证","气虚证","血瘀证","气血两虚证"],"a":1,"e":"心悸胸闷气短3年、心前区刺痛、痛引左肩、舌紫黯、脉涩，为心气亏虚、推动无力、血行瘀滞、心脉不畅的气虚血瘀。气滞血瘀项见胀痛、情志相关、脉弦涩，无气短乏力。气虚证项见心悸气短、乏力自汗，无刺痛、舌紫暗。血瘀证项见刺痛固定、舌紫暗、脉涩，无气虚表现。气血两虚项见面白心悸、头晕乏力，无刺痛、舌紫暗"},{"q":"患者久病，面色苍白，却时而泛红如妆，属于","o":["心炎上炎","阳明经热","阴虚火旺","虚阳浮越","肝阳上亢"],"a":3,"e":"久病面色苍白却时而泛红如妆、游移不定，为阳气虚衰、虚阳被格于上的虚阳浮越，属危候。选项心炎上炎见舌尖红赤、口舌生疮、心烦，红非如妆。阳明经热项见满面通红、蒸蒸发热、大汗、脉洪大。阴虚火旺项见两颧潮红、午后热甚、盗汗、舌红少苔。肝阳上亢项见面红目赤、头胀痛、脉弦有力"},{"q":"患者，女，57岁。患者平素眼睛干涩，口干，无其他不适症状，舌红少津，脉细无力，辨证为","o":["津液亏虚证","阴虚火旺证","津枯血燥证","津停气阻证","气阴两亏证"],"a":0,"e":"眼睛干涩、口干、舌红少津、脉细无力，无明显热象，为津液不足、濡润失职的津液亏虚证。阴虚火旺证项见潮热盗汗、五心烦热、舌红少苔、脉细数，有虚火。津枯血燥证项见皮肤干燥、毛发枯槁、舌淡、脉细涩，血虚象明显。津停气阻证项见水肿、痰饮、脘痞，与水液停聚有关。气阴两亏证项见气短乏力、口干、脉细数无力"},{"q":"患者，男，28岁。3天前在外吃夜宵后，出现腹痛腹泻，下利黄糜味臭，肛门灼热，脉濡数，其所对应的舌象为","o":["舌红绛，苔黄燥","舌红瘦，苔薄白","舌淡白，苔黄裂","舌红，苔黄腻","舌淡白，苔白腻"],"a":3,"e":"腹痛腹泻、下利黄糜味臭、肛门灼热、脉濡数，为大肠湿热，舌红主热、苔黄腻主湿热，故见舌红苔黄腻。舌红绛苔黄燥为热入营血、津液大伤。舌红瘦苔薄白为阴虚或气阴两虚。舌淡白苔黄裂为气血不足兼津伤。舌淡白苔白腻为寒湿内盛，均非大肠湿热之舌"},{"q":"患者，男，30岁。昨日过食辛辣肥甘之品，今晨腹痛，泻下急迫不爽，粪色黄褐，气味臭秽，肛门灼热，小便短黄，舌红苔黄腻，脉濡数。属于","o":["肝胃不和","胃火炽盛","湿客胃肠","肝脾不调","大肠湿热"],"a":4,"e":"过食辛辣肥甘后腹痛、泻下急迫不爽、粪色黄褐臭秽、肛门灼热、小便短黄、舌红苔黄腻、脉濡数，为湿热蕴结大肠、传导失司。肝胃不和项见胃脘胀痛、胁胀、嗳气。胃火炽盛项见胃脘灼痛、口臭、消谷善饥。湿客胃肠项见脘腹痞闷、恶心、便溏，热象不显。肝脾不调项见胁胀、腹痛即泻、泻后痛减"},{"q":"小便黄赤浑浊，伴臊臭味者，证属","o":["消渴病","膀胱虚寒","膀胱湿热","肾气不固","胃肠郁热"],"a":2,"e":"小便黄赤浑浊、伴臊臭味，为湿热蕴结膀胱、气化不利、尿液受湿热煎熬。膀胱虚寒项见小便清长、夜尿多、畏寒肢冷。肾气不固项见小便频数清长、余沥不尽、滑精带下。消渴病项见口渴多饮、小便量多而清，无臊臭。胃肠郁热项见口臭、牙龈肿痛、大便秘结，病在胃肠"},{"q":"咳痰带血，面红目赤，烦热，胁肋灼痛，脉弦数。宜诊断为","o":["肺热炽盛证","燥邪犯肺证","肺阴虚证","肝火犯肺证","肝火炽盛证"],"a":3,"e":"咳痰带血、面红目赤、烦热、胁肋灼痛、脉弦数，为肝经火盛、上逆犯肺、肺络受损的肝火犯肺。肺热炽盛证项见发热咳喘、痰黄稠、胸痛，无胁肋灼痛、脉弦。燥邪犯肺证项见干咳少痰、口鼻干燥。肺阴虚证项见干咳少痰、潮热盗汗、舌红少苔。肝火炽盛证项见目赤口苦、急躁易怒、便秘尿黄，无咳血"},{"q":"咳嗽，喘促，呼多吸少，动则尤甚，声低气怯，自汗遗尿，肢冷，面色、口唇青紫，舌淡，脉浮大无根。应诊断为","o":["肺气虚证","肺肾气虚证（肾不纳气证）","肾气虚证","心肺气虚证","肾阳虚证"],"a":1,"e":"咳嗽喘促、呼多吸少、动则尤甚、声低气怯、自汗遗尿、肢冷、面唇青紫、脉浮大无根，为肺肾两虚、肾不纳气、气不归元。肺气虚证项见咳喘气短、自汗、乏力，无呼多吸少、遗尿、脉无根。肾气虚证项见腰膝酸软、尿频、耳鸣，无喘促、呼多吸少。心肺气虚证项见心悸气短、咳嗽，无呼多吸少、肢冷。肾阳虚证项见腰膝冷痛、畏寒肢冷、五更泄泻"},{"q":"患者右胁胀痛1个月，厌食油腻厚味，舌红苔黄腻，脉弦数，属","o":["脾胃湿热","肝胆湿热","痰湿内蕴","胃火炽盛","肝胃不和"],"a":1,"e":"右胁胀痛、厌食油腻厚味、舌红苔黄腻、脉弦数，为湿热蕴结肝胆、疏泄失常、胆汁外溢。脾胃湿热项见脘腹痞满、口黏、便溏不爽、苔黄腻，无右胁胀痛。痰湿内蕴项见形体肥胖、胸闷脘痞、苔白腻、脉滑。肝胃不和项见胃脘胀痛、胁胀、嗳气，无苔黄腻、脉数。胃火炽盛项见胃脘灼痛、口臭、消谷善饥"},{"q":"患者，女，30岁。月经过多，甚则崩漏，面色无华，少气懒言，食少便溏，舌淡苔白，最有可能出现的脉象是","o":["弦滑脉","浮滑脉","洪数脉","沉涩脉","细弱脉"],"a":4,"e":"月经过多甚则崩漏、面色无华、少气懒言、食少便溏、舌淡苔白，为脾虚气弱、统血失职、气血两虚，细脉主血虚、弱脉主气虚。弦滑脉主痰饮、肝胆病。浮滑脉主风痰、妊娠。洪数脉主热盛。沉涩脉主气滞血瘀或阳虚寒凝，均与气血亏虚不符"},{"q":"患者肌肤热，渴喜冷饮，汗出如油，热而味咸，烦躁不安，脉疾而无力，此属","o":["阴虚证","阳虚证","里实热证","亡阴证","亡阳证"],"a":3,"e":"肌肤热、渴喜冷饮、汗出如油、热而味咸、烦躁不安、脉疾而无力，为阴液暴脱、虚阳外越、阴不敛阳的亡阴证。阴虚证项见潮热盗汗、舌红少苔、脉细数，病势缓。阳虚证项见畏寒肢冷、小便清长、脉沉迟。里实热证项见壮热烦渴、大汗、脉洪数有力。亡阳证项见汗冷味淡、四肢厥冷、脉微欲绝，与亡阴相反"},{"q":"患者胸闷气短，呕恶腹痛，甚则神志不清，猝然昏倒，脉伏，宜诊断为","o":["风淫证","寒淫证","暑淫证","湿淫证","火淫证"],"a":2,"e":"胸闷气短、呕恶腹痛、甚则神志不清、猝然昏倒、脉伏，为暑邪卒中、蒙蔽清窍、气机闭塞的中暑，属暑淫证。风淫证项见恶风汗出、脉浮缓。寒淫证项见恶寒无汗、脉紧。湿淫证项见头身困重、脘痞、苔腻、脉濡。火淫证项见高热烦渴、神昏谵语、舌红苔黄、脉数，无猝然昏倒、脉伏之闭证"},{"q":"下列属于湿疹表现的是","o":["疱疹色白，点细，形如粟粒","水疱破裂、渗液，出现红色湿润之糜烂","皮肤出现密集的红色尖粒，瘙痒刺痛，干燥后成细小鳞屑","水疱如针头至绿豆大小，伴瘙痒和烧灼感","皮肤灼热刺痛，出现成簇水疱，围以红晕"],"a":1,"e":"水疱破裂、渗液、出现红色湿润糜烂，为湿疹急性期湿热蕴肤、皮疹多形、渗出倾向的特点。疱疹色白点细如粟粒为白痱，因汗液排泄不畅。密集红色尖粒、瘙痒刺痛、干燥后细小鳞屑为风热或瘾疹表现。水疱如针头至绿豆大小伴瘙痒烧灼感多见于湿热疮疡。皮肤灼热刺痛、成簇水疱围以红晕为蛇串疮，沿神经分布"},{"q":"下列何病多表现为咳声短促，咳后有鸡啼样回声","o":["顿咳","白喉","肺痨","肺痿","肺痈"],"a":0,"e":"咳声短促、咳后鸡啼样回声，为顿咳，因痰浊阻肺、肺气上逆、气道挛急，多见于小儿。白喉项见咳声犬吠样、咽部灰白假膜、不易擦去。肺痨项见咳嗽咯血、潮热盗汗、消瘦。肺痿项见咳吐浊唾涎沫、气短声低。肺痈项见发热胸痛、咳吐腥臭脓血痰"},{"q":"Page-FrameX年X月X日X时 XX科别记录以下内容：（1）前次诊疗后的病情变化，简要的辨证分析，补充诊断、更正诊断。（2）各种诊治措施的改变及其原因。（3）同一医师守方超过3次后要重新誊写处方。（4）3次没有确诊或疗效不佳者必须有上级医师的会诊意见。上级医师的诊疗意见应详细记录，并经上级医师签字负责。医师签名：以上病历书写格式是","o":["门诊病历的初诊记录","门诊病历的复诊记录","住院病历的初诊记录","住院病历的复诊记录","住院病历的病程记录"],"a":1,"e":"记录前次诊疗后病情变化、辨证分析、补充或更正诊断、诊治措施改变及原因，且守方超过3次需重誊处方、3次未确诊须上级医师会诊，为门诊病历复诊记录。门诊初诊记录项记载主诉、现病史、查体、诊断及治则处方，无前次诊疗对比。住院病程记录项按日记录住院期间病情与诊疗变化，格式不同"},{"q":"患者，男，43岁。干咳3年余。近1个月来，因过于劳累，咳嗽加剧，痰中带血丝，自觉手足心热，入睡后出汗，醒后汗止，尿少便干，两颧潮红，舌红苔少而干，脉细数。其证候是","o":["燥邪犯肺证","肝火犯肺证","邪热壅肺证","肺阴虚证","肺气虚证"],"a":3,"e":"干咳3年、劳累后加剧、痰中带血丝、手足心热、入睡后出汗醒后汗止、尿少便干、两颧潮红、舌红苔少而干、脉细数，为肺阴亏虚、虚火灼肺、肺络受损。燥邪犯肺证项见干咳少痰、口鼻干燥，病程短。肝火犯肺证项见咳血、胁肋灼痛、脉弦数。邪热壅肺证项见发热、痰黄稠、苔黄。肺气虚证项见咳喘无力、痰白清稀、气短自汗"},{"q":"病人发热1天，伴有恶寒，头痛，项强，脉浮，其证属","o":["太阳病证","阳明病证","少阳病证","少阴病证","太阴病证"],"a":0,"e":"发热、恶寒、头痛、项强、脉浮，为外感风寒邪在太阳之表、卫阳被遏、营卫不和的太阳病证。阳明病证项见身热、汗出、口渴、便秘、脉洪大或沉实。少阳病证项见寒热往来、胸胁苦满、口苦咽干、脉弦。少阴病证项见脉微细、但欲寐、畏寒肢冷。太阴病证项见腹满而吐、食不下、自利、口不渴"},{"q":"王某，男，40岁。3年来，每日早晨5时左右即感腹痛欲便，泻后痛减，便质清稀，夹杂有较多的不消化食物，并伴有怕冷，腰腿困痛，头晕耳鸣等症。查体：面色淡白，舌淡苔白而润，脉沉细而弱。此人所患病证是","o":["脾虚泄泻","肝郁泄泻","湿热泄泻","食积泄泻","脾肾阳虚泄泻"],"a":4,"e":"每日清晨5时左右腹痛欲便、泻后痛减、便质清稀夹不消化食物，兼怕冷、腰腿困痛、头晕耳鸣、面色淡白、舌淡苔白润、脉沉细弱，为脾肾阳虚、命火不足、腐熟无力的五更泄泻。脾虚泄泻项见食后腹胀、便溏、神疲乏力，无五更定时、腰膝酸冷。肝郁泄泻项见腹痛即泻、泻后痛减、脉弦。湿热泄泻项见泻下黄糜、肛门灼热。食积泄泻项见泻下酸腐、脘腹胀满"},{"q":"患者，女，49岁。失眠3个月。自觉眠浅梦多，入睡较难，平素自觉面红发热，心烦，口渴，时有胸闷气粗，偶有喉间痰鸣，咯吐黄痰，小便黄，大便干，舌质红苔黄腻，脉滑数。此属下列何证","o":["心阴虚证","痰火扰神证","胆郁痰扰证","肺热炽盛证","痰蒙心神证"],"a":1,"e":"眠浅梦多、面红发热、心烦、胸闷气粗、喉间痰鸣、咯吐黄痰、小便黄、大便干、舌红苔黄腻、脉滑数，为痰郁化火、上扰心神、神不守舍的痰火扰神证。心阴虚证项见心烦失眠、盗汗、舌红少苔、脉细数，无黄痰、苔黄腻。胆郁痰扰证项见惊悸不寐、口苦呕恶、苔黄腻，热象较轻。肺热炽盛证项见咳喘、痰黄、发热。痰蒙心神证项见神志痴呆、喃喃自语、苔白腻，无火热之象"},{"q":"患者，男，68岁。近3个月来时感心悸心慌，左侧胸前区憋闷疼痛，肩背部及上臂内侧亦有不适感；平素体形肥胖，痰多色白，身重困倦，舌苔白腻，脉沉滑。此属下列何证","o":["寒痰阻肺证","痰阻心脉证","气滞心脉证","寒凝心脉证","瘀阻心脉证"],"a":1,"e":"左侧胸前区憋闷疼痛、肩背及上臂内侧不适、形肥胖、痰多色白、身重困倦、苔白腻、脉沉滑，为痰浊内阻、心脉不畅、胸阳不振的痰阻心脉证。寒痰阻肺证项见咳嗽痰白、胸闷、畏寒，病在肺。气滞心脉证项见心前区胀痛、情志相关、脉弦。寒凝心脉证项见猝然心痛、遇寒加重、肢冷、脉紧。瘀阻心脉证项见刺痛固定、舌紫暗、脉涩"},{"q":"患者，女，60岁。近1年来经常心悸、胸闷气短、畏寒肢冷，未经系统诊治。半小时前因劳累过度突然心痛剧烈，胸闷持续不解，冷汗淋漓，呼吸微弱，四肢厥冷，唇色青紫，脉微欲绝。其胸痛的病机是","o":["心气亏虚","心阳亏虚","心血不足","心脉痹阻","痰蒙心神"],"a":3,"e":"心痛剧烈、胸闷持续不解、冷汗淋漓、呼吸微弱、四肢厥冷、唇色青紫、脉微欲绝，为心阳亏虚、温运无力、血行瘀滞、心脉闭塞的真心痛，病机属心脉痹阻。心气亏虚项见心悸气短、乏力自汗，无痛剧烈、肢厥。心血不足项见心悸失眠、面白舌淡。心阳亏虚项见心悸胸闷、畏寒肢冷，无剧烈心痛、脉微欲绝。痰蒙心神项见神志痴呆、苔腻"},{"q":"患者，男，68岁。腹部膨隆，小便量少，周身困重，舌胖，苔白滑，脉缓，考虑为","o":["亡阴证","津液亏虚证","痰证","饮证","水停证"],"a":4,"e":"腹部膨隆、小便量少、周身困重、舌胖苔白滑、脉缓，为水液代谢失常、水湿内停、泛溢腹中的水停证。亡阴证项见汗热味咸、烦躁、脉疾无力。津液亏虚证项见口干咽燥、皮肤干瘪、舌红少津。痰证项见咳痰量多、胸闷、苔腻、脉滑。饮证项见脘腹痞满、呕吐清涎、肠鸣沥沥、咳唾引痛，水停局部"},{"q":"患者，男，20岁。高考两度失利，情绪不佳，近1个月来逐渐躁动不宁，时常胡言乱语，乱摔书本，毁坏家具，父母阻之不得，甚则被其殴打。刻下：情绪躁急，面赤，舌质红，苔黄腻，脉滑数。此属下列何证","o":["肝阳上亢证","痰火扰神证","心火亢盛证","痰蒙心神证","胆郁痰扰证"],"a":1,"e":"躁动不宁、胡言乱语、乱摔物品、殴打他人、面赤、舌红苔黄腻、脉滑数，为情志不遂、气郁化火、炼液成痰、痰火上扰心神的狂病，属痰火扰神证。肝阳上亢证项见头胀痛、眩晕、腰膝酸软，无神昏狂乱。心火亢盛证项见心烦失眠、口舌生疮、舌尖红，无明显痰象。痰蒙心神证项见表情淡漠、喃喃自语、苔白腻，属阴癫。胆郁痰扰证项见惊悸不寐、口苦、脉弦滑，无狂躁打骂"},{"q":"患者小便频数清长，腰膝酸软，神疲乏力，形寒肢冷，舌淡脉弱，宜诊断为","o":["肾气不固证","脾肾阳虚证","肾阳虚证","脾虚气陷证","心肾阳虚证"],"a":2,"e":"小便频数清长、腰膝酸软、神疲乏力、形寒肢冷、舌淡脉弱，为肾阳不足、温煦失职、气化无权的肾阳虚证。肾气不固证项见小便频数清长、带下清稀、滑精、腰膝酸软，无明显形寒肢冷。脾肾阳虚证项见久泻便溏、完谷不化、腹部冷痛。脾虚气陷证项见久泻脱肛、脘腹重坠、食后尤甚。心肾阳虚证项见心悸怔忡、畏寒、尿少肢肿、唇甲青紫"},{"q":"Page-Frame刘某，女，21岁，学生。2005年7月14日初诊。主诉：胃脘胀痛5年，加重3天，伴恶心。初诊：患者因住校就餐，饥饱不均，出现胃脘胀痛，在本地医院经胃镜检查诊断为慢性胃炎，用药不详，疗效不明显。近3天来胃脘胀痛，饥饿时明显，伴恶心、呃逆、呕吐，无反酸，腹胀，头晕，纳呆，二便调，睡眠佳。2002年做胃镜检查报告：慢性浅表性胃炎，反流性食管炎，Hp(-)。舌质淡红，苔薄白，脉平缓。诊为胃脘痛(慢性浅表性胃炎)：胃虚气滞证。治以补中和胃法。方拟香砂六君子汤加减。处方：党参10g，茯苓10g，炒白术10g，炙甘草6g，陈皮10g，法半夏6g，砂仁(后下)5g，焦曲6g，莱菔子5g，炒枳壳6g，淡干姜2g，大腹皮5g，干藿香5g，炒谷芽15g，大枣4g。4剂，水煎服，日1剂。嘱饮食宜软、烂、熟、温为佳。二诊：服药4剂后，胃脘胀痛好转，已不恶心，仍感腹胀，纳、便可；舌质淡红，苔薄白，脉平缓。前方奏效，效不更方。上方加佩兰6g，继服7剂。饮食宜忌同前。三诊：服药7剂后，胃脘胀痛消失，仍感腹胀，口干，纳少，便可。治以理气和胃。加郁金6g，香附6g，木香3g。7剂，水煎服，日1剂。饮食宜忌同前。按：患者长期饮食不节，造成脾胃虚弱，运化、受纳功能减退，气机不畅，则胃脘胀痛不适、腹胀、纳呆；胃气以降为顺，胃气不降反而上逆则恶心、呃逆、呕吐；清阳不升，则头晕。故病位在脾胃，病性为虚实夹杂。用香砂六君子汤健脾益气和胃，补后天之本，滋气血生化之源。本案在香砂六君子汤的基础上，加枳壳行气宽中除胀；莱菔子消食降气；炒谷芽、焦曲消食和中、健脾开胃；大腹皮下气宽中；干姜温胃止呕，藿香解暑化湿；大枣补脾和药。二诊时考虑到正值暑季，患者常有暑温夹湿的现象，因此加入佩兰以芳香化湿。三诊时胃痛已愈，仍腹胀、口干，说明气机仍然不畅，遂加郁金、香附疏肝理气；木香行气调中。香砂六君子汤出自《医方集解》，治疗脾胃气虚、寒湿滞于中焦之脘腹胀满疼痛等。本案准确运用经方，根据季节特点，灵活加减用药，而获此良效。以上案例记录属于","o":["中医医案","住院病历","病程记录","门诊病历复诊记录","住院病历复诊记录"],"a":0,"e":"全文含初诊、二诊、三诊的辨证、处方、用药加减及按语分析，并援引方剂出处、阐明辨治思路，为典型中医医案。住院病历项应有入院记录、病程记录、出院小结等规范格式。病程记录项按日记载住院病情变化。门诊病历复诊记录项仅记录复诊病情变化、诊断调整及处方，无症状分析与按语详论"},{"q":"患者时有左胸前区刺痛，常于夜间发作，面色略黯，舌尖有紫色斑点，脉弦涩。证属","o":["气滞证","气逆证","气闭证","血热证","血瘀证"],"a":4,"e":"左胸前区刺痛、夜间发作、面色略黯、舌尖紫色斑点、脉弦涩，为瘀血内阻、心脉不畅、不通则痛的血瘀证，刺痛固定、夜间加重、舌瘀点、脉涩为要点。气滞证项见胀痛、走窜不定、脉弦。气逆证项见咳喘、呕吐、呃逆等气机上逆。气闭证项见突然昏厥、牙关紧闭、脉沉实。血热证项见出血鲜红、心烦、舌红绛、脉数"},{"q":"患者，男。腹中肿块时聚时散，按之无形，痛无定处，诊断为","o":["癥积","瘕聚","虫积","水鼓","痞证"],"a":1,"e":"腹中肿块时聚时散、按之无形、痛无定处，为气机郁滞、聚散无常的瘕聚，属气病、无形、痛无定处。癥积项见肿块坚硬有形、固定不移、痛有定处，属血病。虫积项见腹痛时作、面黄体瘦、寐中磨牙、粪便见虫。水鼓项见腹部膨隆、按之凹陷、小便短少、周身困重。痞证项见心下痞满、按之柔软不痛，无形无块"},{"q":"患者，女，23岁。右臀部溃疡5天，红肿高起，根盘紧束，灼热疼痛，舌淡红，苔黄，脉数，属","o":["痈","疽","疔","疖","丹毒"],"a":0,"e":"臀部溃疡红肿高起、根盘紧束、灼热疼痛、苔黄脉数，为湿热火毒蕴结、气血壅滞、肉腐成脓的痈，范围较大、红肿热痛明显。疽项见漫肿无头、皮色不变、不热少痛，属阴证。疔项见形小根深、坚硬如钉、麻木疼痛，多发于颜面手足。疖项见小而局限、红肿热痛、根脚浅、易溃易敛。丹毒项见皮肤鲜红成片、边界清楚、灼热，不化脓溃破"},{"q":"若患者胃气不足，胃阴亏虚或气血两虚，则多见","o":["燥苔","腐苔","剥落苔","腻苔","滑苔"],"a":2,"e":"胃气不足、胃阴亏虚或气血两虚，舌苔失去胃气胃阴充养而剥落，见剥落苔，主胃气阴两伤、气血亏虚。燥苔主津液亏耗、热盛伤津，苔干不剥。腐苔主食积、痰浊、阳热有余，苔厚如豆腐渣。腻苔主湿浊、痰饮、食积，苔质致密。滑苔主寒湿、阳虚水停，苔湿润多津"},{"q":"若患者感受寒湿之邪，或阳虚不能运化水液，则可出现","o":["燥苔","腻苔","滑苔","腐苔","剥落苔"],"a":2,"e":"感受寒湿之邪或阳虚不能运化水液，水湿内停、上泛于舌，故见滑苔，苔面水分过多、扪之湿滑。燥苔主津液亏耗，苔干少津。腻苔主湿浊、痰饮、食积，苔质致密如油。腐苔主食积、痰浊、阳热有余，苔厚松腐。剥落苔主胃气阴两伤、气血亏虚，苔剥脱不全"},{"q":"患者面部肌肉消瘦，两颧高耸，眼窝、面颊凹陷，伴全身骨瘦如柴，多见于","o":["气血亏虚","脏腑精血耗竭","吐泻伤津","肾精亏损","胃气衰败"],"a":1,"e":"面部肌肉消瘦、两颧高耸、眼窝面颊凹陷、全身骨瘦如柴，为久病重病、脏腑精血耗竭、形体失养的恶病质表现。气血亏虚项见面白乏力、头晕心悸，消瘦不若此甚。吐泻伤津项见皮肤干燥、眼窝凹陷、口渴尿少，起病急。肾精亏损项见发脱齿摇、腰膝酸软、小儿五迟。胃气衰败项见食欲全无、舌苔剥落、脉弱"},{"q":"患者项强，伴头痛，恶寒，脉浮，多属","o":["风寒侵袭","热极生风","肾精亏损","颈部肌肉劳损","精气衰竭"],"a":0,"e":"项强伴头痛、恶寒、脉浮，为风寒侵袭太阳经、经气不利、卫阳被遏，筋脉拘急故项强。热极生风项见项强、高热神昏、抽搐、舌红绛、脉弦数。肾精亏损项见项软无力、腰膝酸软、早衰，非项强。颈部肌肉劳损项见颈项酸痛、活动受限、劳累加重，无恶寒、脉浮。精气衰竭项见项软、形体消瘦、精神萎靡、脉微弱"},{"q":"患者，女，65岁。体胖，平素怕冷。咳嗽10余天，痰多色白，气喘，形寒肢冷，舌淡，苔白滑，脉濡缓。辨证为","o":["饮停胸胁证","寒痰阻肺证","风寒犯肺证","风寒表证","风水搏肺证"],"a":1,"e":"咳嗽10余天、痰多色白、气喘、形寒肢冷、舌淡苔白滑、脉濡缓，为寒邪犯肺、津液不化、聚而成痰、寒痰阻肺。饮停胸胁证项见胸胁胀满、咳唾引痛、气急，痰少。风寒犯肺证项见咳嗽痰白清稀、鼻塞流涕、恶寒发热、脉浮紧，病程短。风水搏肺证项见眼睑头面浮肿、小便不利、恶风。风寒表证项以恶寒发热、头痛、脉浮为主，咳痰不突出"},{"q":"病室有烂苹果气，可见于","o":["水肿病晚期","消渴病危重期","脱血夺气","脏腑败坏","瘟疫病"],"a":1,"e":"病室有烂苹果气，为消渴病危重期阴液耗竭、燥热炽盛，脂肪分解产生酮体所致，提示酮症酸中毒。水肿病晚期项见尿少、水肿、面色㿠白，无特殊气味。脱血夺气项见面白、气息微弱、脉微，无气味。脏腑败坏项见气息臭秽、神昏、苔腐，气味不似烂苹果。瘟疫病项见发热、传染性强，无此特异性气味"},{"q":"患者新起恶寒重，微发热，无汗咳嗽气喘，舌红苔黄白相间，脉浮数。此属","o":["表热证","表寒证","表寒里热证","表热里寒证","里实热证"],"a":2,"e":"新起恶寒重、微发热、无汗为外感风寒束表；咳嗽气喘、舌红苔黄白相间、脉浮数为里有郁热，表寒里热并见。表热证项见发热重、微恶寒、咽痛、脉浮数。表寒证项见恶寒重发热轻、无汗、苔薄白、脉浮紧，无里热。表热里寒项见表热与里寒并见，与本例相反。里实热证项见壮热、大汗、口渴、便秘、脉洪数，无恶寒、无汗"},{"q":"患者，男，45岁。心烦不寐，眩晕耳鸣健忘，腰酸梦遗，舌红少津，脉细数。其病变所在脏腑为","o":["心","肾","肝","心、肾","肝、胃"],"a":3,"e":"心烦不寐为心火扰神，眩晕耳鸣健忘为肾精不足、髓海失养，腰酸梦遗为肾虚封藏失职，舌红少津、脉细数为阴虚火旺，病位在心与肾，属心肾不交。单纯心项仅有心悸失眠、口舌生疮。单纯肾项仅有腰酸耳鸣、遗精，无失眠心烦。肝项见胁痛、目赤、脉弦。肝、胃项见胁胀、胃脘不适、嗳气吞酸"},{"q":"患者腹泻反复发作2年，伴腹部坠胀，神疲乏力，头晕眼花，舌淡脉弱，证属","o":["气虚证","气血两虚证","气陷证","气不固证","血虚证"],"a":2,"e":"腹泻反复2年、腹部坠胀、神疲乏力、头晕眼花、舌淡脉弱，为脾气虚弱、清阳不升、中气下陷的气陷证，以坠胀、久泻为要点。气虚证项见乏力、气短、自汗，无下坠感。气血两虚证项见面白心悸、头晕、舌淡，无腹部坠胀。气不固证项见自汗、遗尿、滑精、带下清稀、出血，无下坠。血虚证项见面白、爪甲不荣、月经量少、舌淡"},{"q":"患者，女，47岁。反复胃脘隐痛3年，痛时喜按，胃脘痞满，纳少，嗳气，神疲乏力，少气懒言，舌淡苔薄白，脉弱。诊为","o":["胃气虚证","胃阳虚证","胃阴虚证","寒湿困脾证","食滞胃脘证"],"a":0,"e":"胃脘隐痛3年、痛时喜按、胃脘痞满、纳少、嗳气、神疲乏力、少气懒言、舌淡苔薄白、脉弱，为胃气不足、受纳失常、胃失和降的胃气虚证。胃阳虚证项见胃脘冷痛、喜温喜按、畏寒肢冷、舌淡胖。胃阴虚证项见胃脘灼痛、饥不欲食、舌红少津、脉细数。寒湿困脾证项见脘腹痞闷、口黏、便溏、苔白腻。食滞胃脘证项见胀痛嗳腐、苔厚腻、脉滑"},{"q":"患者急躁冲动，眩晕耳鸣，纳呆食少，腹胀腹泻，泻后痛减，宜诊断为","o":["喜伤证","怒伤证","思伤证","惊伤证","恐伤证"],"a":1,"e":"急躁冲动、眩晕耳鸣为怒伤肝、肝气上逆、肝阳上亢；纳呆食少、腹胀腹泻、泻后痛减为肝气犯脾、脾失健运，故属怒伤证。喜伤证项见心情涣散、语无伦次、哭笑无常。思伤证项见神情呆滞、纳差、失眠、健忘。惊伤证项见心悸胆怯、坐卧不安、神态慌张。恐伤证项见恐惧、二便失禁、腰膝酸软"},{"q":"患者，女，61岁。症见身热夜甚，口干不欲饮，或斑疹隐隐，心烦，或时有谵语，舌绛，脉细数，其辨证为","o":["卫分证","气分证","营分证","血分证","气血两燔证"],"a":2,"e":"身热夜甚、口干不欲饮、斑疹隐隐、心烦、时有谵语、舌绛、脉细数，为邪热入营、耗伤营阴、热扰心神的营分证。卫分证项见发热恶寒、头痛、苔薄白、脉浮数。气分证项见壮热烦渴、苔黄燥、脉洪数。血分证项见斑疹显露、吐血衄血、舌深绛、脉数。气血两燔证项见壮热、发斑、神昏并见，气分营分同病"},{"q":"患者，男，42岁。症见发热，恶寒，头痛，身重，胃脘部痞满，心烦，口渴，舌红苔白腻，脉濡数，其辨证为","o":["湿热犯卫","暑湿犯卫","热郁胆经","燥热犯肺","风热犯卫"],"a":1,"e":"暑湿犯卫多见于夏月，暑兼湿邪郁遏卫表，故发热恶寒、头痛身重、胃脘痞满、心烦口渴，舌红苔白腻、脉濡数正是湿中蕴热之象。湿热犯卫虽亦身重苔腻，但热象偏重、苔多黄腻；风热犯卫以发热重、咽痛、脉浮数为特点，无身重痞满；燥热犯肺则见干咳鼻燥，均无暑湿困阻中焦之候"},{"q":"患者胃脘冷痛，呕吐清涎，面色㿠白，舌苔白润，脉沉紧。证属","o":["表实寒证","表实热证","里实寒证","里虚寒证","里虚热证"],"a":2,"e":"寒邪直中胃腑，胃脘冷痛、呕吐清涎，脉沉紧主里寒且邪盛，病位在里而正气未虚，故为里实寒证。表实寒证必见恶寒发热、头身痛、脉浮紧，病位在表；里虚寒证虽有冷痛但喜温喜按、脉沉迟无力，无明显邪实；里虚热证则见五心烦热、盗汗、舌红少苔，与本例寒象脉紧迥异"},{"q":"古人所称的“噫”是指","o":["呃逆","嗳气","少气","呵欠","矢气"],"a":1,"e":"噫即嗳气，为胃中气体上逆出于咽喉所发出的声响，多因胃气上逆或食积所致。呃逆为膈肌痉挛、喉间呃呃连声，古称“哕”；少气指气短不足以息、语言无力；呵欠为张口深吸、倦乏之象；矢气为肠中气体自肛门排出，俗称“放屁”，均与噫义不同"},{"q":"患者，男，39岁。因丧失亲人而情志抑郁，胸胁满闷不舒，舌有紫斑紫点，脉弦。患者的病机是","o":["气血两虚","气虚血瘀","气滞血瘀","气随血脱","气滞血燥"],"a":2,"e":"情志抑郁致肝气郁结，气机阻滞则胸胁满闷、脉弦；气滞日久血行不畅，故舌见紫斑紫点，属气滞血瘀。气血两虚见面白乏力、舌淡脉细弱；气虚血瘀以神疲乏力、舌淡胖有瘀斑、脉细涩为主，本例无明显气虚；气随血脱见于大出血之后；气滞血燥少见，均无情志抑郁致瘀之过程"},{"q":"患者，男，55岁。身热颧红，手足心热于手足背，口舌干燥，耳聋，舌红少苔，脉虚大，其临床意义是","o":["虚风内动证","肾阴亏虚证","肾气虚证","肝阴亏虚","肾阳虚证"],"a":1,"e":"肾阴亏虚，虚火内扰，故身热颧红、口舌干燥、舌红少苔；肾开窍于耳，肾阴不足则耳聋；脉虚大为阴虚阳浮之象。肾气虚以腰膝酸软、神疲耳鸣、脉细弱为主，无明显虚热；肾阳虚见畏寒肢冷、面色㿠白、脉沉迟；肝阴亏虚多见目涩、胁痛、爪甲不荣；虚风内动当有手足蠕动、瘛疭等动风表现"},{"q":"患者，男，40岁。咳嗽半年，干咳少痰，痰中有血丝，口干咽燥，声音嘶哑，腰膝酸软，形瘦，骨蒸潮热，颧红，时有遗精，舌红少苔，最有可能出现的脉象是","o":["脉洪大","脉细数","脉弦数","脉缓弱","脉结代"],"a":1,"e":"本例久咳耗伤肺阴，复及肾阴，虚火内扰，阴虚则脉细，火旺则脉数，故最可能出现脉细数。脉洪大主气分实热；脉弦数主肝胆郁热或痛证；脉缓弱主脾虚湿盛；脉结代主气血虚弱、心脉瘀阻，均非肺肾阴虚、虚火内扰之脉象"},{"q":"患者鼻塞浊涕2日，鼻塞时轻时重，鼻痒气热，喷嚏，流黄稠浊涕，发热恶风，头痛，咽痛，口干喜饮。舌红，苔白，脉浮数。此病最宜辨证为","o":["外感风寒","外感风热","肺热壅盛","肺胃郁热","痰热壅肺"],"a":1,"e":"风热犯肺，肺气失宣，故鼻塞、流黄稠浊涕、咽痛；风热上扰则发热恶风、头痛，脉浮数为风热在表，舌红、口干喜饮为热盛伤津。外感风寒见恶寒重、流清涕、脉浮紧；肺热壅盛以高热、咳喘痰黄、无表证为特点；肺胃郁热、痰热壅肺均有里热痰盛之象，非外感初起之表证"},{"q":"患者，男，62岁。近半年来记忆力逐渐降低，时有举止失常，神情痴呆，甚则意识模糊。刻下：面色晦暗，时有胸闷，恶心欲呕，肢沉欲眠，舌苔白腻，脉滑。此属下列何证","o":["痰蒙心神证","痰火扰神证","胆郁痰扰证","瘀阻脑络证","肝阳化风证"],"a":0,"e":"痰浊内蕴，蒙蔽心窍，故神情痴呆、意识模糊、举止失常；胸闷恶心、肢沉欲眠、苔白腻、脉滑皆为痰湿内盛之象。痰火扰神见神昏谵语、躁狂、苔黄腻、脉滑数，热象明显；胆郁痰扰以惊悸失眠、口苦、脉弦滑为主；瘀阻脑络有刺痛、舌紫暗、脉涩；肝阳化风见眩晕震颤、脉弦有力"},{"q":"患者，女，29岁。经常手足心汗出量多，伴有午后自觉发热，舌红苔黄腻，其手足心汗出，属","o":["阳气内郁","阴虚内热","中焦湿热","阳明热盛","气虚不固"],"a":2,"e":"脾胃湿热内蕴，迫津外泄，故手足心汗出量多；午后自觉发热、舌红苔黄腻为湿热内盛之象。阴虚内热见手足心热、盗汗、舌红少苔，绝无黄腻苔；阳气内郁见手足厥冷而非汗多；阳明热盛见大汗、大渴、脉洪大；气虚不固见自汗、神疲乏力、舌淡苔白，均非中焦湿热"},{"q":"患者自幼双睑下垂，无力抬举，伴疲乏无力，畏寒肢冷，小便清长，舌淡胖苔白，脉沉迟无力，多为","o":["命门火衰，脾阳不足","脾虚失运，中气不足","先天不足，肾精亏损","气血亏虚","脏腑精气衰竭"],"a":0,"e":"自幼睑垂、疲乏无力为脾虚气弱，畏寒肢冷、小便清长、舌淡胖苔白、脉沉迟无力为阳虚内寒；脾阳根于命门之火，火衰则脾阳失于温运，故为命门火衰、脾阳不足。脾虚失运、中气不足仅有乏力纳差、脉虚无力，无畏寒肢冷；先天肾精亏损以发育迟缓、骨软为主；气血亏虚见面白心悸、舌淡脉细；脏腑精气衰竭为病危之象"},{"q":"患者进食油腻食物后出现右胁下绞痛伴阵发性加剧，恶心欲吐，面色淡青，脉弦紧。证属","o":["气滞证","气逆证","血瘀证","气脱证","气闭证"],"a":4,"e":"油腻饮食损伤脾胃，痰浊内生，气机闭塞不通，胆道失于疏泄，故右胁绞痛阵发加剧、恶心欲吐；脉弦紧为气闭疼痛之象，面色淡青亦因气机郁闭。气滞证以胀痛走窜、脉弦为主，无剧烈绞痛；气逆证以咳喘、呃逆、呕吐等气机上逆为特点；血瘀证刺痛固定、舌紫暗、脉涩；气脱证见气息微弱、脉微欲绝"},{"q":"患者，男，45岁。平日急躁易怒，今日因事与人争吵时突感头晕，站立不住，面赤如醉，舌体颤动，脉弦。其证候是","o":["肝火上炎","肝阳上亢","热极生风","肝阳化风","肝气郁结"],"a":3,"e":"素体肝阳偏亢，情绪激动引动肝风，风阳上扰清窍，故突发头晕、站立不住、面赤如醉；舌体颤动为风动之象，脉弦为肝阳亢盛。肝阳上亢以眩晕头胀、烦躁易怒、脉弦有力为主，无卒然动风；肝火上炎见目赤口苦、便秘尿黄、脉弦数；热极生风多伴高热神昏、抽搐；肝气郁结以胸胁胀满、善太息为主"},{"q":"患者，女。主诉胸胁、少腹胀满疼痛，走窜不定，症状轻重与情绪变化有关，平素多情志抑郁不乐，善太息，舌苔薄白，脉弦。辨证属","o":["肝胆湿热证","肝郁气滞证","肝血虚证","肝风内动证","寒滞肝脉证"],"a":1,"e":"肝失疏泄，气机郁滞，故胸胁少腹胀满疼痛、走窜不定，症状随情绪波动而增减；善太息、脉弦为肝郁气滞之征。肝胆湿热见口苦、胁痛、苔黄腻、脉弦数；肝血虚见目涩、爪甲不荣、舌淡脉细；肝风内动有震颤、抽搐、眩晕；寒滞肝脉以少腹冷痛、阴囊收缩、脉沉弦为主"},{"q":"患者，男，73岁。患者平素血脂较高，频繁早搏，平素性情抑郁，善太息。近3月来时有心悸，甚则心胸疼痛，痛引肩背内臂，时作时止。昨日因与邻居争执而诱发，舌淡红苔薄白，脉弦。此属下列何证","o":["肝郁气滞证","痰阻心脉证","气滞心脉证","寒凝心脉证","瘀阻心脉证"],"a":2,"e":"情志抑郁、善太息、脉弦为气滞之象，气滞心脉、血行不畅，故心胸疼痛引肩背内臂、时作时止，因争执而诱发。痰阻心脉见胸闷痛、体胖痰多、苔白腻、脉沉滑；寒凝心脉以遇寒痛甚、脉沉迟为主；瘀阻心脉为刺痛固定、舌紫暗、脉涩；肝郁气滞虽有情志症状，但无心脉瘀阻之胸痛"},{"q":"太阳蓄血证，少腹急结，硬满，小便自利，人若发狂，大便色黑如漆，脉","o":["浮数","沉涩","浮缓","浮紧","洪大"],"a":1,"e":"太阳蓄血为瘀热互结于下焦，血行瘀滞故脉沉涩；少腹急结硬满、大便色黑如漆、发狂皆为瘀热蓄血之象，小便自利说明病在血分而非气分。浮数主表热；浮缓为太阳中风；浮紧为太阳伤寒；洪大主气分大热，均非蓄血内停之脉"},{"q":"患者，男，34岁。身热，心烦懊憹，坐卧不安，舌苔微黄，脉数，其临床意义是","o":["热灼营阴","热扰心神","热郁胆经","热扰胸膈","热邪壅肺"],"a":3,"e":"热郁胸膈，扰乱心神，故身热、心烦懊憹、坐卧不安；苔微黄、脉数为热象初盛，尚未入里成实。热灼营阴见身热夜甚、神昏谵语、舌红绛；热扰心神多伴神昏且病位较深；热郁胆经见口苦、胁痛、寒热往来；热邪壅肺以咳喘痰黄为主，均无胸膈懊憹之特征"},{"q":"患儿，2岁4个月大。口角流涎清稀，面色萎黄，消瘦乏力，纳差，大便稀薄，舌淡红，苔薄白，指纹淡红。宜诊断为","o":["气血亏虚","脾阳虚","肾阳虚","脾气亏虚","脾胃湿热"],"a":3,"e":"脾气亏虚，运化失职，气血生化不足，故面色萎黄、消瘦乏力、纳差便溏；脾不主液则口角流涎清稀，指纹淡红为虚证之象。脾阳虚见畏寒肢冷、大便清稀完谷不化；肾阳虚见发育迟缓、畏寒、五更泻；气血亏虚以面白、心悸、脉细为主；脾胃湿热见口臭、苔黄腻、大便黏滞"},{"q":"患者近日外感风邪，发热轻，恶风，头痛，自汗出，最可能的脉象是","o":["浮数","浮紧","浮缓","浮滑","弦数"],"a":2,"e":"风邪袭表，卫气不固则自汗出，营卫不和故发热轻、恶风、头痛，脉浮缓为风邪在表、营卫失调之象。浮数主风热表证；浮紧为风寒表实、无汗；浮滑主风痰或表证夹痰；弦数主肝胆郁热，均与自汗恶风之中风脉不符"},{"q":"患者。男，56岁。头晕、头痛5年。前天头痛加重，并见口眼歪斜，语言不畅，时感四肢麻木，左半身不能活动，舌红，苔黄腻，脉弦滑。属于","o":["错语","言謇","谵语","郑声","狂言"],"a":1,"e":"言謇指语言謇涩不利、吐字不清，多因风痰阻络、舌体失养所致；本例见口眼歪斜、半身不遂、苔黄腻、脉弦滑，风痰阻络故语言不畅。谵语为神昏时胡言乱语、声高有力；郑声为神疲时语言重复、声音低弱；错语为语言错乱而能自知；狂言为狂躁妄言、语无伦次，均非单纯言语不利"},{"q":"患者，男，40岁。突见面色青灰，口唇青紫，肢凉脉微，辨证为","o":["心阳暴脱","阳虚水泛","阴虚火旺","脾虚湿蕴","气血不足"],"a":0,"e":"心阳暴脱，阳气骤亡，血行瘀滞，故突见面色青灰、口唇青紫、四肢厥冷、脉微欲绝，属危重证候。阳虚水泛见水肿、心悸、咳喘、脉沉细；阴虚火旺见潮热盗汗、舌红少苔、脉细数；脾虚湿蕴见纳差腹胀、便溏苔腻；气血不足见面白乏力、脉细弱，均无暴脱之危象"},{"q":"患者昨日因天气降温受凉，出现咳嗽，痰清稀色白，恶寒发热，无汗，鼻塞流涕，咽喉痒，舌苔薄白，最可能的脉象是","o":["浮滑脉","浮数脉","浮紧脉","沉细脉","浮缓脉"],"a":2,"e":"风寒束表，卫阳被遏，故恶寒发热、无汗；肺气失宣则咳嗽、痰清稀色白、鼻塞流涕、咽喉痒，脉浮紧为风寒表实之征。浮滑脉主风痰或咳嗽痰多；浮数脉主风热表证；沉细脉主里虚；浮缓脉为太阳中风、自汗出，均与本例外感风寒无汗不符"},{"q":"患者，男，73岁。2小时前突发心前区剧烈疼痛，急诊入院。刻下：面色发白，肢冷有汗出量多，神志模糊，呼之不应，唇舌青紫，脉微欲绝。此属下列何证","o":["痰蒙心神证","痰火扰神证","心阳虚脱证","瘀阻脑络证","心脉瘀阻证"],"a":2,"e":"心阳虚脱，阳气暴亡，故脉微欲绝；心脉瘀阻则唇舌青紫，阳气外亡故面色苍白、肢冷汗多、神志模糊、呼之不应，为真心痛之危候。痰蒙心神证以神昏、苔白腻、脉滑为主，无剧烈胸痛；痰火扰神见神昏谵语、苔黄腻；瘀阻脑络以头痛、半身不遂为主；心脉瘀阻虽胸痛但无亡阳之象"},{"q":"病人发热微恶寒，肢节烦痛，心下痞结，微呕，其证属","o":["少阳兼阳明病证","阳明兼太阳病证","少阳兼太阳病证","少阳病证","太阳病证"],"a":2,"e":"发热微恶寒、肢节烦痛为太阳表证未解，心下痞结、微呕为少阳枢机不利、胆胃不和，故属少阳兼太阳病证。少阳兼阳明病证当有大便秘结、潮热等里实；阳明兼太阳病证以发热恶寒、汗出而喘、大便硬为主；单纯少阳病证见寒热往来、胸胁苦满、口苦咽干；太阳病证则无心下痞、呕等少阳见症"},{"q":"患者，男，53岁。小便频数短赤、灼热涩痛3天。查尿常规，小便隐血（+++）。刻下：时有发热，面赤口渴，心烦失眠，舌尖有溃疡，灼热疼痛，舌红苔黄，脉数。此属下列何证","o":["肝火上炎证","痰火扰神证","肺热炽盛证","小肠实热证","膀胱湿热证"],"a":3,"e":"小肠实热，心火下移小肠，故小便频数短赤、灼热涩痛、尿血；心火上炎则舌尖溃疡灼痛、心烦失眠、面赤口渴、脉数。膀胱湿热虽有尿频尿痛，但无舌尖溃疡等心火上炎之象；肝火上炎见目赤胁痛、口苦、脉弦数；痰火扰神见神昏谵语、苔黄腻；肺热炽盛以咳喘痰黄为主"},{"q":"患者喘促声低，呼多吸少，动则益甚，腰膝酸软，舌淡，脉沉细。其证属于","o":["表证","寒证","虚证","热证","实证"],"a":2,"e":"喘促声低、呼多吸少、动则益甚为肾虚不纳气，腰膝酸软、舌淡、脉沉细皆属虚象，故辨为虚证。表证应有恶寒发热、脉浮；寒证以寒象为主、脉紧或迟；热证见身热、口渴、脉数；实证见喘促气粗、声高有力、脉实有力，均与本例声低息弱、动则加重相反"},{"q":"患者，女，33岁。近期出现崩漏，伴有面色淡白，心悸失眠，乏力，脉弱，辨证为","o":["气不摄血证","气血两虚证","气随血脱证","气滞血瘀证","气虚血瘀证"],"a":0,"e":"气虚不能统摄血液，血溢脉外故见崩漏；气血不足不能上荣则面色淡白、乏力，心失所养则心悸失眠，脉弱为气虚之象。气血两虚证虽有面白心悸，但出血不突出且气血双亏之象更著；气随血脱见于大出血后气息微弱、脉微欲绝；气滞血瘀见刺痛、舌紫暗、脉涩；气虚血瘀见乏力兼刺痛、舌淡紫"},{"q":"患者，男，50岁。咳喘20余年，现咳嗽痰少，口燥咽干，形体消瘦，腰膝酸软，颧红盗汗，舌红少苔，脉细数。其病机是","o":["肺气虚损","肺阴虚亏","肺肾阴虚","肺肾气虚","肾气虚衰"],"a":2,"e":"久咳耗肺阴，肺阴亏虚则干咳痰少、口燥咽干；肾阴不足则腰膝酸软、颧红盗汗、舌红少苔、脉细数，故为肺肾阴虚。肺气虚损以咳喘无力、痰清稀、气短为主；肺阴虚亏仅有肺部阴虚见症，无腰膝酸软等肾虚表现；肺肾气虚以呼多吸少、气短乏力为主，无颧红盗汗；肾气虚衰以腰膝酸软、夜尿多为主"},{"q":"患者，女，30岁。因工作繁忙，近半年来出现白带绵绵不断，曾服清热除湿方药10余剂，未效。近1周连续加班劳累，带下量多，淋漓不断，色白质稀，无臭味，伴见面色萎黄，神倦乏力，少气懒言，纳呆食少，腰腹酸冷，手足不温，舌淡苔白，脉缓弱。该患者带下量多的病机为","o":["脾虚气陷","脾肾阳虚","湿浊下注","肝郁脾虚","寒湿下注"],"a":1,"e":"脾阳虚则运化失职、带下清稀量多，肾阳虚则腰腹酸冷、手足不温；舌淡苔白、脉缓弱、面色萎黄、神疲乏力皆为阳虚之象，故病机为脾肾阳虚。脾虚气陷以带下清稀、小腹坠胀、脱肛为主，无腰腹冷痛；湿浊下注带下质稠或有异味；肝郁脾虚见胸胁胀满、情志不遂；寒湿下注见带下清冷、苔白腻，无明显虚象"},{"q":"患者，男，42岁。患精神分裂症多年，近半月来病情加重，出现狂躁妄动，胡言乱语，少寐多梦，打人毁物，不避亲疏，舌淡红，苔白，脉弦，属于","o":["狂病","癫病","痫病","惊风","脏躁"],"a":0,"e":"狂病以精神亢奋、狂躁妄动、打人毁物、不避亲疏、胡言乱语为主要表现，多因痰火扰神所致，本例与之相符。癫病以精神抑郁、表情淡漠、沉默痴呆、语无伦次为主；痫病为发作性神志异常、口吐白沫、四肢抽搐、醒后如常；惊风多见于儿童、抽搐伴发热；脏躁以精神恍惚、悲伤欲哭、哈欠频作为特征"},{"q":"患者，男。素嗜酒，咳嗽痰多。春节聚餐后，出现神志迷糊，满口痰涎粘连，两目瞪视，四肢厥冷，舌淡白，苔厚腻垢浊，脉沉迟有力。证属","o":["表寒证","里寒证","里热证","亡阳证","亡阴证"],"a":1,"e":"素嗜酒而痰浊内生，苔厚腻垢浊、脉沉迟有力为里寒痰浊内盛，阳气被遏故神志迷糊、四肢厥冷、两目瞪视、满口痰涎，病位在里而邪实，故属里寒证。表寒证有恶寒发热、脉浮紧；里热证见身热、口渴、苔黄、脉数；亡阳证见大汗淋漓、脉微欲绝、气息微弱；亡阴证见汗出而黏、烦躁、脉细数疾"},{"q":"患者，老年男性，体胖，有冠心病史。近半年来心胸部憋闷作痛，痛引肩背内臂，时作时止，身重困倦，舌苔白腻，最有可能出现的脉象是","o":["沉弦脉","弦细脉","细涩脉","沉滑脉","细数脉"],"a":3,"e":"体胖、身重困倦、苔白腻为痰湿内盛之象，痰浊阻痹心脉故心胸憋闷作痛、痛引肩背内臂，痰湿内阻其脉多沉滑。沉弦脉主气滞或痛证；弦细脉主肝肾阴虚或血虚肝郁；细涩脉主血瘀或精血亏少；细数脉主阴虚内热，均与痰湿内阻之胸痹不符"},{"q":"以下何项不属于呃逆的常见原因","o":["偶感风寒","热邪客胃","胃气衰败","脾失健运","寒邪客胃"],"a":3,"e":"呃逆为胃气上逆动膈所致，偶感风寒使肺胃气机不利、寒邪客胃与热邪客胃均令胃气上逆、胃气衰败则呃声低弱断续，皆为常见原因。脾失健运主要导致纳呆、腹胀、便溏等运化失常，并不直接引起胃气上逆动膈，故不属于呃逆的常见原因"},{"q":"患者今起头痛，恶寒重，发热，清涕，苔薄白而润，脉浮紧。证属","o":["里寒证","表寒证","实热证","虚热证","表热证"],"a":1,"e":"恶寒重而发热轻、头痛、清涕、苔薄白而润、脉浮紧为风寒袭表、卫阳被遏之表寒证。里寒证以畏寒肢冷、腹痛便溏、脉沉迟为主，无表证；实热证见高热、口渴、苔黄、脉数；虚热证见潮热盗汗、舌红少苔、脉细数；表热证见发热重恶寒轻、咽痛、脉浮数，均与本例风寒在表不符"},{"q":"吕某，男，51岁，军人。2016年7月9日初诊。胸闷，心悸，阵发性心前区刺痛1年，加重3天。1年来反复出现胸闷、心悸，偶有心前区刺痛。3天前因出差返家，旅途乘车劳累，到家用热水洗澡后，胸闷、心悸加重，伴心前区刺痛，经休息后稍缓解。此后因进餐胸闷、心悸复加重，并有阵发性心前区刺痛，向颈肩、左上肢放射，伴有下牙及腹部作痛，舌感麻木，急请医生到家查心电图，提示心肌缺血。平时患有高脂血症。急收入院。查：体胖高大，舌淡胖苔白厚，脉弦滑，血压14/8kPa（105/60mmHg），心律整，心率60次/min……病案中的“1年来反复出现胸闷、心悸……舌感麻木”是","o":["一般情况","主诉","现病史","既往史","个人史"],"a":2,"e":"现病史记述起病情况、主要症状特点及发展变化、伴随症状、诊治经过和发病以来一般情况，题中所述一年来胸闷心悸、心前区刺痛发作及旅途劳累后加重的过程正属此列。一般情况指饮食睡眠、二便、体重等生活状况；主诉为就诊最主要症状及持续时间；既往史为既往疾病史；个人史为生活嗜好、职业经历，均非该段内容"},{"q":"患者脘部按之有形而胀痛，推之辘辘有声为","o":["气滞","血瘀","水饮","寒凝","气虚"],"a":2,"e":"脘部按之有形、推之辘辘有声为胃中水饮停聚之征，水饮内停、气机阻滞故见胀痛，振之则有水声。气滞以胀痛走窜、按之无形、脉弦为主；血瘀为刺痛固定、部位不移、舌紫暗；寒凝见冷痛喜温、脉沉紧；气虚以隐痛喜按、乏力、脉虚无力为特点，均无振水音"},{"q":"患者男，65岁。渐发耳鸣，声小如闻蝉鸣，按之鸣减或暂止，病机为","o":["肝风内动","肝胆火盛","肝肾阴亏","气血亏损","肝经风火"],"a":2,"e":"肝肾阴亏，精血不足，耳窍失养，故耳鸣渐发、声小如蝉鸣、按之鸣减或暂止，属虚证耳鸣。肝胆火盛、肝经风火之耳鸣突发声大、按之不减、伴口苦目赤；肝风内动以眩晕、震颤、抽搐为主；气血亏损之耳鸣伴面白乏力、心悸、脉细弱，均无按之鸣减之肾虚特征"},{"q":"患者，女，56岁。咳喘10年，伴见胸闷心悸，咯痰清稀，声低乏力，面白神疲，舌质淡白，脉弱。其证候是","o":["心肺气虚","肺气虚","寒邪客肺","脾肺气虚","肾不纳气"],"a":0,"e":"肺气虚则咳喘、咯痰清稀、声低乏力；心气虚则胸闷心悸、面白神疲，舌质淡白、脉弱为气虚之象，故为心肺气虚。肺气虚仅有咳喘气短，无心悸胸闷；寒邪客肺为外感实证，见咳嗽痰白、恶寒、脉紧；脾肺气虚兼见纳呆腹胀、便溏；肾不纳气以呼多吸少、动则喘甚、腰膝酸软为主"},{"q":"患者食少纳呆，腹胀便溏，久咳气短，声低懒言，舌淡苔白，脉缓弱。宜诊断为","o":["肺气虚证","心气虚证","心脾两虚证","心肺气虚证","肺脾气虚证"],"a":4,"e":"食少纳呆、腹胀便溏为脾气虚失于运化，久咳气短、声低懒言为肺气虚失于宣降，舌淡苔白、脉缓弱皆属气虚，故宜诊断肺脾气虚证。肺气虚证仅有咳喘气短；心气虚证以心悸、胸闷、神疲为主；心脾两虚见心悸失眠、健忘、食少便溏、面色萎黄；心肺气虚见咳喘心悸，均无腹胀便溏等脾虚症状"},{"q":"患者手足厥冷、喘促气粗、心烦谵语、舌红苔黄腻，其证属","o":["太阳经证","阳明腑证","少阳病证","阳明经证","太阳腑证"],"a":3,"e":"阳明经证为邪热充斥阳明之经，里热炽盛；热盛于里、阳气郁闭不能达于四末则手足厥冷，是为热厥，心烦谵语、舌红苔黄腻、喘促气粗皆里热之象。阳明腑证以潮热、便秘、腹满硬痛、脉沉实为主；太阳经证见恶寒发热、头项强痛、脉浮；少阳病证见寒热往来、胸胁苦满；太阳腑证有蓄水、蓄血之别"},{"q":"患者出现身大热，大汗出，大渴引饮，面赤心烦，舌苔黄燥，最容易出现的脉象是","o":["濡细脉","滑数脉","洪大脉","沉迟脉","弦滑脉"],"a":2,"e":"阳明经证、气分热盛，故身大热、大汗出、大渴引饮、面赤心烦、舌苔黄燥，脉洪大为气分实热之典型脉象。濡细脉主湿盛或阴虚血少；滑数脉主湿热或痰热；沉迟脉主里寒；弦滑脉主痰热或肝郁，均与气分大热之洪大脉不符"},{"q":"患者，男，35岁。2日前食自助餐后出现胃脘胀闷疼痛，嗳气吞酸，矢气便溏，泻下物酸腐臭秽，舌苔厚腻，脉滑。诊为","o":["湿热蕴脾证","肠热腑实证","肠燥津亏证","寒湿困脾证","食滞胃脘证"],"a":4,"e":"饮食不节，食积胃脘，气机阻滞故胃脘胀闷疼痛；食积化腐则嗳气吞酸、矢气便溏、泻下物酸腐臭秽，苔厚腻、脉滑为食积之象。湿热蕴脾见身热、口苦、苔黄腻；肠热腑实见便秘、潮热、腹痛拒按；肠燥津亏见大便干结、口干舌红少津；寒湿困脾见脘腹冷痛、苔白腻、脉沉迟，均无酸腐之食积特征"},{"q":"患者滑胎2次 ，腰酸腹坠，神疲乏力，舌淡苔白，宜诊断为","o":["脾虚气陷证","气血虚证","肾气不固证","肾精不足证","肾阳虚证"],"a":2,"e":"肾气不足，冲任不固，胎元失于系养，故屡次滑胎；腰酸为肾虚之候，腹坠、神疲乏力、舌淡苔白为气虚之象，故宜诊断肾气不固证。脾虚气陷以脱肛、子宫脱垂、久泻、小腹坠胀为主；气血虚见面白心悸、脉细弱；肾精不足见发育迟缓、早衰、不孕；肾阳虚见畏寒肢冷、小便清长、脉沉迟"},{"q":"姓名： 性别：年龄： 民族：婚况： 职业：发病节气： 出生地：常住地址： 单位：入院时间：X年X月X日X时 病史采集时间：X年X月X日X时病史陈述者： 可靠程度：主诉现病史（1）起病情况（2）主要症状特点及发展变化情况（3）伴随症状（4）发病以来诊治经过及结果（5）发病以来一般情况既往史个人史婚育史家族史中医望、闻、切诊体格检查专科情况辅助检查辨病辨证依据西医诊断依据初步诊断：中医诊断：病名（包括主要疾病和其他疾病）证名西医诊断：（包括主要疾病和其他疾病）实习医师（签名）住院医师（签名）以上病历书写格式是","o":["门诊病历","住院病历","病程记录","门诊病历复诊记录","住院病历复诊记录"],"a":1,"e":"住院病历内容完整，包含入院时间、病史陈述者及可靠程度、主诉、现病史、既往史、个人史、婚育史、家族史、中医四诊、体格检查、专科情况、辅助检查、辨病辨证依据、初步诊断及各级医师签名。门诊病历较简略，无此详尽记录；病程记录为住院期间病情变化的连续记载；复诊记录针对再次就诊，均不具备入院病历之完整格式"}];
